import type { MvBook } from '../molytvoslov';
const D: MvBook[] = [{"u":"Акафіст святому рівноапостольному князю Володимиру","e":"Akathist to the Holy Equal-to-the-Apostles Prince Volodymyr","secs":[{"h":"Кондак 1","ps":["Ізбранного світи́льника, тьму ідолослуже́нія в держа́ві Ру́ськой разгна́вшаго і сві́том Боже́ственния ві́ри ю просвіти́вшаго, восхваля́єм тя, святи́й равноапостольний кня́же Влади́мире: ти же я́ко ви́ну со дерзнове́нієм предстоя́й Царю́ ца́рствующих, не преста́й моля́ся о достоя́нії твоє́м і твої́ми моли́твами сохраня́й нас от вся́ких бід і зол, да со умиле́нієм благода́рственно зове́м ті:","Ра́дуйся, Влади́мире, держа́ви Ру́ськия просвіти́телю."]},{"h":"Ікос 1","ps":["А́нгелом і челові́ком Творе́ць, времена́ і лі́та во Своє́й вла́сті положи́вий і судьби́ государств і наро́дов устроя́яй, єгда́ благоізво́ли призва́ти род ру́ський от тьми ідолослуже́нія ко сві́ту і́стини і пра́вди ві́чния, поста́ви тя, благові́рний кня́же, благовісти́теля і соверши́теля сея́ всеблагия во́лі Своєя́. Ті́мже, благодаря́ще Творця́ і Спа́са на́шего, славосло́вим тя, я́ко вели́каго ізбра́нника Бо́жия на́шего ра́ди спасе́нія, с весе́лієм зову́ще:","Ра́дуйся, равноапо́столе, ко просвіще́нію наро́да ру́ськаго Прему́дрим Про́мислом предизбранний;","ра́дуйся, от первозва́ннаго апо́стола на гора́х Ки́євських прорече́нний.","Ра́дуйся, пресла́вний сосу́де Боже́ственния благода́ті, держа́ві твоє́й дарова́нний;","ра́дуйся, пречу́дний ко́реню, із него́же на землі́ на́шей проізрасте ве́ліє дре́во правові́рія.","Ра́дуйся, я́ко тобо́ю І́м'я Госпо́днє во всіх преді́ліх страни́ твоє́й прославля́ється;","ра́дуйся, я́ко і твоє́ пресла́вноє і́м'я от всіх родо́в ру́ських с любо́вію воспіва́ється.","Ра́дуйся, Влади́мире, держа́ви Ру́ськия просвіти́телю."]},{"h":"Кондак 2","ps":["Ви́дя суєту́ безду́шних і́долов і пре́лесть дия́вола є́юже уловля́єть те́мния лю́ди в сі́ті беззако́нія, ку́пно же сли́ша святи́х первому́ченик ру́ських за Христа́ Фео́дора і ю́наго Іоа́нна, глаго́лющих безбо́жним мучи́телем: “Бо́зі ва́ші не суть бо́зі, но дре́во, є́же днесь пребива́єть — у́тро сгнило єсть. Єди́н же єсть Бог І́стинний, І́же сотвори́ Не́бо і зе́млю”; тогда́ возгорі́лся єси́ се́рдцем, во є́же взиска́ти і уві́діти Сего́ Єди́наго І́стиннаго Бо́га, Єму́же покланя́ється вся́ко колі́но Небе́сних, земни́х і преіспо́дніх, немо́лчно воспіва́я: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум всеви́шній приосени тя, єгда́ предста́ша ті пропові́дници разновернії і потща́лся єси́, да не уловле́н бу́деши в сі́ті лжеученія, но да обря́щеши ві́ру і́стинную і спаси́тельную. Ті́мже ублажа́єм тя:","Ра́дуйся, прему́дрий просвіти́телю наро́да ру́ськаго;","ра́дуйся, ра́зум богопросвіще́нний стяжа́вий.","Ра́дуйся, я́ко ухищре́нія і суєсло́вія лжеучи́телей посрами́л єси́;","ра́дуйся, я́ко глаго́ли Жи́зні Ві́чния в словесі́х Мудреця́ І́стиннаго му́дре уразумі́л єси́.","Ра́дуйся, лучу́ Боже́ственнаго сві́та посреді́ тьми лжеві́рія;","ра́дуйся, стіно́ неруши́мая посреді́ бу́рі страсте́й язи́чеських.","Ра́дуйся, Влади́мире, держа́ви Ру́ськия просвіти́телю."]},{"h":"Кондак 3","ps":["Си́лою сви́ше умудре́н, посла́л єси́ му́жи ізбра́нния во страни́ іни́я, да ви́дять і іспита́ють, ка́ко іні́ї наро́ди слу́жать Бо́гу і ка́ко ві́ру свою́ от діл свої́х показу́ють; ті́ї же вся до́брі іспита́вше, достиго́ша Царграда, іді́же ви́дяще благолі́пноє соверше́ніє Боже́ственнаго священноді́йствія, мні́ша себі́ не на землі́, но на Небесі́ стоя́ти, і со умиле́нієм се́рдця возда́ша хвалу́ Го́сподеві, зову́ще: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́ще в сердця́х свої́х тве́рдоє увіре́ніє, я́ко ві́ра греко-восто́чная воі́стину єсть правосла́вная і я́ко священноді́йствія єя́ па́че всіх іни́х велелепна, посла́нії тобо́ю му́жіє, возврати́вшеся во Оте́чествіє своє́ іспові́даша сія́ пред лице́м твої́м і пред старі́йшини твої́ми, реко́ша же: “Нікто́же вкуси́в сла́дкаго, восхо́щеть го́ркаго, та́ко і ми не мо́жем па́ки оста́ти зді і служи́ти куми́ром”. Яковоє ізвіще́ніє приє́м, возгорі́лся єси́ ре́вностію по ві́рі і́стинній. Сего́ ра́ди велича́єм тя:","Ра́дуйся, гла́су Боже́ственния благода́ті прилі́жно внимавий;","ра́дуйся, води́тельству Свята́го Ду́ха усе́рдно послі́дствовавий.","Ра́дуйся, я́ко сові́тники твоя́ умудри́л єси́;","ра́дуйся, вся лю́ди твоя́ сові́ти твої́ми ко і́стинній ві́рі приве́л єси́.","Ра́дуйся, я́ко со тща́нієм поіска́л єси́ до́браго би́сера Христа́;","ра́дуйся, пчело́ трудолюби́вая, му́дре взискавшая цві́ти, в них же сла́дкий мед і́стини і спасе́нія.","Ра́дуйся, Влади́мире, держа́ви Ру́ськия просвіти́телю."]},{"h":"Кондак 4","ps":["Бу́рею сумне́ній і недоумі́ній не поколеба́лся єси́ повнегда́ уві́діти тебі́ ві́ру і́стинную, правосла́вную, но а́біє восхоті́л єси́ прия́ти Свято́є Креще́ніє со все́ю держа́вою твоє́ю, да ку́пно с не́ю, я́ко оте́ць со ча́ди свої́ми, досто́йно воспоє́ши Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавше боляре і старі́йшини я́же о ві́рі і́стинній, пом'яну́ша прама́тер твою́ святу́ю княги́ню О́льгу, я́же прия́т Свято́є Креще́ніє в Царегра́ді, і реко́ша: а́ще не би бла́га бисть ві́ра сія́, не би прия́ла ю сія́ мудрі́йшая в жена́х. Ті́мже і ми, при́сно помина́юще прему́друю О́льгу, благода́рственно зове́м ті:","Ра́дуйся, я́ко соблю́л єси́ Боже́ственноє сі́м'я, є́же всея́ в се́рдці твоє́ блаже́нная прама́тер твоя́;","ра́дуйся, я́ко святи́м заветам тоя́ послі́довал єси́.","Ра́дуйся, я́ко прови́діл єси́ в ней зарю́ спасе́нія наро́да твоєго́;","ра́дуйся, со́лнце возше́дшеє по заре́ той.","Ра́дуйся, сві́те, старі́йшини твоя́ просвіти́вий;","ра́дуйся, вся лю́ди твоя́ ко Христу́ приведи́й.","Ра́дуйся, Влади́мире, держа́ви Ру́ськия просвіти́телю."]},{"h":"Кондак 5","ps":["Боготка́нную оде́жду Свята́го Креще́нія восхоті́в получи́ти, поми́слил єси́, отку́ду і ка́ко імі́ти і́маши толи́к сонм па́стирей і учи́телей, да просвітя́ть вся лю́ди твоя́ с тобо́ю, і ка́ко поя́ти себі́ жену́, во ві́рі святі́й іспитанну, до́му твоєму́ благу́ю строїтельницю, ча́дом твої́м ма́тер во Христі́, советницю же всім во благоче́стії, і о сем всім поревнова́в, дух твой приведе́ тя ко страні́ Гречестей, іді́же ві́рнії от літ дре́вніх благоче́стно воспіва́ють Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше ца́ріє гречестії всю страну́ твою́ во тьмі ідолослуже́нія косня́щу, небрего́ша тя, я́ко куми́ром служа́ща, оба́че побіжде́ні би́вше от тебе́ і уві́дівше крі́пкоє ізволе́ніє твоє́ прия́ти Свято́є Креще́ніє і вся лю́ди твоя́ ко Христу́ привести́, іспо́лнишася ра́дости і вда́ша ті сестру́ свою́ А́нну на брак, па́стирі же і учи́тели наро́ду твоєму́. Ті́мже і ми, при́сно ра́дующеся свято́му сему́ сою́зу твоєму́, воспіва́єм тя:","Ра́дуйся, я́ко посіти́л єсть тя Восто́к сви́ше;","ра́дуйся, я́ко звізда́ Всеви́шняго приведе́ тя к Восто́ку, іді́же Прему́дрость созда́ себі́ дом і утверди́ столпо́в седьм, седьм Собо́ров Вселе́нських, і́же утверди́ша ві́ру Христо́ву по вселе́нній.","Ра́дуйся, я́ко сія́ єсть ві́ра апо́стольськая, сія́ ві́ра вселе́нную всю утверди́;","ра́дуйся, я́ко от чи́стаго істо́чника чи́стоє уче́ніє Христо́во прия́л єси́.","Ра́дуйся до́му твоєго́ і чад твої́х до́брий рачи́телю,","ра́дуйся, всего́ наро́да твоєго́ прему́дрий наста́вниче.","Ра́дуйся, Влади́мире, держа́ви Ру́ськия просвіти́телю."]},{"h":"Кондак 6","ps":["Па́стиріє і учи́тели, ї́хже прия́л єси́, прехва́льне кня́же, от царе́й гре́чеських, я́ко да напая́ють всю страну́ Ру́ськую уче́ньми Боже́ственними, со тща́нієм теча́ху на ді́ланіє своє́, благода́рственно пою́ще призва́вшему наро́д твой ко спасе́нію Го́споду Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ пречу́дне чу́вственний світ в помраченною неду́гом сліпоти́ о́чію твоє́ю, в душе́ твоє́й сві́ту благода́ті возсія́вшу, єгда́, просвіти́вся Боже́ственним Креще́нієм, ізше́л єси́ от святи́я купі́лі, є́же ощути́в, ра́достно воскликнул єси́: “ни́ні позна́х Бо́га І́стиннаго”. Ті́мже ублажа́єм тя:","Ра́дуйся, світи́льниче, огне́м Боже́ственния благода́ті во тьмі язи́чества возжже́нний;","ра́дуйся, благовестителю сві́та Христо́ва, омраче́нная очеса́ і се́рдця наро́да твоєго́ отверза́яй.","Ра́дуйся, я́ко у́мною о́чію твоє́ю прови́діл єси́ Бо́жиє смотре́ніє о держа́ві твоє́й;","ра́дуйся, я́ко до конця́ потща́лся єси́, да і всі лю́діє твої́ просвітя́ться в нем.","Ра́дуйся, богосві́тлая главо́ князе́й Ру́ських;","ра́дуйся, славнейшеє украше́ніє і похвало́ Це́ркве Христо́ви.","Ра́дуйся, Влади́мире, держа́ви Ру́ськия просвіти́телю."]},{"h":"Кондак 7","ps":["Хотя́ просвіти́ти Боже́ственним Креще́нієм наро́д ру́ський, пе́рвіє повелі́л єси́ крести́тися синово́м і вельмо́жам твої́м, да всі лю́діє, послі́дующе стопа́м їх, со благи́м проізволе́нієм присту́п'ят ко Свято́му Креще́нію, благоче́стно зову́ще Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́во творе́ніє во Христі́ яви́ тя, по Святі́м Креще́нії, о́браз житія́ твоєго́: ревни́тель бо пе́рвіє бив ідолослуже́нія, посліди́ ви́ну по ві́рі Христо́вой ревнова́л єси́: возлюби́л же єси́ кро́тость і милосе́рдіє, воздержа́ніє і целому́дріє і все житіє́ по за́повідем Госпо́днім. Чудя́щеся у́бо благо́му преміне́нію сему́, благоче́стно зове́м ті:","Ра́дуйся, я́ко росо́ю Свята́го Ду́ха пла́мень страсте́й в себі́ угаси́л єси́;","ра́дуйся, я́ко огне́м Боже́ственния благода́ті вся помишле́нія і вся чу́вствія твоя́ согрел єси́.","Ра́дуйся, селе́нія Госпо́дня, це́ркві святи́я, па́че всіх селе́ній земни́х, возлюби́вий;","ра́дуйся, Боже́ственния слу́жби і Христо́ва уче́нія па́че всіх дія́ній і уче́ній взиска́вий.","Ра́дуйся, о́браз но́ваго житія́ всім лю́дем твої́м в себі́ показа́вий;","ра́дуйся, си́рих і убо́гих благи́й корми́телю і попечи́телю.","Ра́дуйся, Влади́мире, держа́ви Ру́ськия просвіти́телю."]},{"h":"Кондак 8","ps":["Стра́нноє бі, ку́пно же і радостотво́рноє виді́ніє, єгда́ тьмочисленний сонм муже́й і жен, ю́нош і дів, та́же незло́бивих младе́нець с ра́достію теча́ху к ріці́ Днепру, я́коже ко Іорда́ну, іді́же креща́хуся во І́м'я Отця́ і Си́на і Свята́го Ду́ха, ієре́ом на бре́зі возносящим тайнодейственния моли́тви і воспіва́ющим Го́споду піснь: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь бил єси́ об'ят неізрече́нною ра́достію, достоблаже́нне кня́же, зря креща́ємия лю́ди твоя́, і во умиле́нії се́рдця, возда́в хвалу́ Спаси́телю Бо́гу, усе́рдно моли́л єси́ Єго́, да при́зрить на новопросвіще́нния лю́ди Своя́, да утверди́ть їх во ві́рі і благоче́стії і да просла́вить І́м'я Своє́ в страна́х ру́ських. Воспомина́юще у́бо пресла́вноє і прерадостноє сих сбитіє́, прино́сим ті благода́рственния і похва́льния пі́сні сія́:","Ра́дуйся, вино́вниче спасе́нія безчи́сленних душ в землі́ Ру́ськой;","ра́дуйся, неоскудіва́ємий істо́чниче благослове́ній і ми́лостей Бо́жиїх к наро́ду твоєму́.","Ра́дуйся, благи́й вертогра́дарю, сад Боже́ственния ві́ри в ца́рстві твоє́м насади́вий;","ра́дуйся, пото́че сла́дости, напоі́вий водо́ю благоче́стія лю́ди ру́ськия.","Ра́дуйся, я́ко Боже́ственную ві́ру просла́вил єси́, пре́лесть же і́дольськую посрами́л єси́;","ра́дуйся, я́ко Цар царе́й дарова́ тебі́ му́дрость Соломо́нову, кро́тость Дави́дову, ре́вность Іліїну́, правові́ріє апо́стольськоє.","Ра́дуйся, Влади́мире, держа́ви Ру́ськия просвіти́телю."]},{"h":"Кондак 9","ps":["Все єстество́ А́нгелов, храни́телей ро́да челові́чеськаго, просла́ви тя, благові́рний кня́же, єгда́ повелі́л єси́ отце́м і ма́терем вдаяти ді́ти своя́ в уче́ніє кни́жноє, да разумі́ють, я́же ві́рують, і да позна́ють, ка́ко житіє́ своє́ до́брі по ві́рі провожда́ти. Ті́мже і ни́ні при́зри на учащіяся Боже́ственним писа́нієм, і на отце́в і ма́терей їх, па́стирей же і учи́телей, споспішеству́ющих їм во уче́нії, благослови́, укріпи́ і наста́ви я во труді́х їх, да возраста́ють во ві́рі і́стинній і в добро́м житії́, пою́ще Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́я многовіща́нния не мо́гуть досто́йно ізобрази́ти вели́чіє благодія́ній, дарова́нних тобо́ю, кня́же, землі́ твоє́й: водворив бо в ней Боже́ственную ві́ру, ізба́вил єси́ ю от мра́ка язи́чеськаго і ві́чния поги́белі, откри́л єси́ єй путь ко і́стинному просвіще́нію, ко спасе́нію і земно́му благоде́нствію. Сего́ ра́ди со благодаре́нієм благоче́стно зове́м ті:","Ра́дуйся, могущества і сла́ви держа́ви Ру́ськия основа́телю;","ра́дуйся, і́стиннаго просвіще́нія і благоче́стія в ней насади́телю.","Ра́дуйся, в наро́ді твоє́м язи́чеських суєві́рій і злих оби́чаєв іскорени́телю;","ра́дуйся, і́дольських тре́бищ і куми́ров потреби́телю.","Ра́дуйся, святи́х хра́мов созда́телю;","ра́дуйся, равноапо́стольному царю́ Константи́ну равноче́стний подо́бниче.","Ра́дуйся, Влади́мире, держа́ви Ру́ськия просвіти́телю."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ от ві́чния поги́белі ца́рство твоє́, в бе́здні ідолослуже́нія гибнувшеє, под'ял єси́ ве́лія труди́ і попече́нія, обходя́ гра́ди і ве́сі землі́ твоєя́ і посила́я повсю́ду па́стирі духо́вния, во є́же Боже́ственною ві́рою Святи́м Креще́нієм лю́ди твоя́ просвіти́ти, і научи́ти їх Єди́ному І́стинному Бо́гу пі́ти: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ тве́рдая бил єси́ землі́ твоє́й во вся дні живота́ твоєго́ проти́ву враго́в тоя́ і вино́вник благоде́нствія і сла́ви єя́; бу́ди і ни́ні защи́тник необори́мий от враг ви́димих і неви́димих і помо́щник в ну́ждіх і ско́рбіх нам, с любо́вію вопію́щим тебі́:","Ра́дуйся, благопопечительнейший па́стирю наро́да ру́ськаго;","ра́дуйся, благострадательнейший о́тче си́рих і стра́ждущих.","Ра́дуйся, гото́вий споспі́шниче і́щущих ві́чнаго спасе́нія і і́стиннаго просвіще́нія;","ра́дуйся, сла́ва і ра́дованіє держа́ви Ру́ськия.","Ра́дуйся, при́сний помо́щниче в многотруднем ді́лі народоуправлепія;","ра́дуйся, мо́щний спобо́рниче в бра́ні во́їнства ру́ськаго.","Ра́дуйся, Влади́мире, держа́ви Ру́ськия просвіти́телю."]},{"h":"Кондак 11","ps":["Пі́ніє умиле́нноє прийми́ от нас, уго́дниче Бо́жий, сокруши́ твої́ми моли́твами вся враги́ на́ша, насади́ правосла́вную ві́ру среди́ язи́к страни́ ру́ськия, неві́дущих і́стиннаго Бо́га, іскорени́ в ней вся є́ресі і раско́ли, да си́нове русскиє єди́ними усти́ і єди́ним се́рдцем сла́в'ять Бо́га, пою́ще Єму́: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоза́рноє світи́ло, просвіща́ющеє сія́нієм свої́м страну́ ру́ськую, ти єси́ достохва́льне кня́же Влади́мире, разгоня́я мрак ідолослуже́нія і показу́я путь к і́стинному просвіще́нію і небе́сному блаже́нству. Сего́ ра́ди, прославля́юще тя глаго́лем:","Ра́дуйся, звіздо́, просвіще́нная от незаходи́маго Со́лнця Пра́вди;","ра́дуйся, путеводи́телю, пра́вую стезю́ к ві́чному спасе́нію нам откри́вий.","Ра́дуйся, мо́щний споспі́шниче і укріпле́ніє пропові́дников правосла́вния ві́ри;","ра́дуйся, при́сний покрови́телю благи́х наста́вников ю́ношества і всіх благотрудящихся на по́льзу о́бщую.","Ра́дуйся, ско́рий помо́щниче всіх, к по́мощі твоє́й прибіга́ющих;","ра́дуйся, я́ко всім усе́рдно тя чту́щим, благотворния сові́ти подає́ши.","Ра́дуйся, Влади́мире, держа́ви Ру́ськия просвіти́телю."]},{"h":"Кондак 12","ps":["Благода́ть Пресвята́го Ду́ха іспроси́ нам, преблаги́й па́стирю наш, от Всеще́драго Бо́га і Спа́са на́шего, вразумля́ющую і укріпля́ющую нас в ді́лі спасе́нія, да не безпло́дна бу́деть в нас насажде́нная тобо́ю свята́я ві́ра, но да уклоня́ющеся от путе́й нече́стія і заблужде́ній, хо́дим во сві́ті за́повідей Бо́жиїх і дости́гнем ві́чнаго блаже́нства, воспіва́юще Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще твоя́ премно́гая і пресла́вная благодія́нія, явле́нная держа́ві на́шей в просвіще́ніі тоя́ сві́том Боже́ственния ві́ри, ку́пно же ве́лія твоя́ труди́ і по́двиги, во благоустроє́ніє єя́ под'ятия, усе́рдно благодари́м і восхваля́єм тя, с любо́вію зову́ще:","Ра́дуйся, богоізбра́нне і богопрославленне самодержче землі́ Ру́ськия;","ра́дуйся, несокрушимоє огражде́ніє єя́, покро́ве і защище́ніє.","Ра́дуйся, ра́йськоє дре́во, проізрастившеє дві пречу́дния отра́сли, святи́х страстоте́рпцев Бори́са і Глі́ба,","ра́дуйся, первостоя́телю святи́х Ру́ськия Це́ркве.","Ра́дуйся, апо́столов сопресто́льниче і сликовствователю;","ра́дуйся, я́ко на зе́млю Ру́ськую ви́ну призира́єши благ вре́менних і ві́чних єй у Бо́га хода́тайствуєши.","Ра́дуйся, Влади́мире, держа́ви Ру́ськия просвіти́телю."]},{"h":"Кондак 13","ps":["О прехва́льний і преди́вний равноапо́столе, вели́кий кня́же Влади́мире, прийми́ ми́лостивно от нас благодаре́ніє сіє́ о всіх, я́же тобо́ю воздаде́ Госпо́дь нам, отце́м і пра́отцем на́шим і всей держа́ві Ру́ськой, наче́н от дне Креще́нія да́же до сего́ часа́, і моли́ Всеблага́го Бо́га проба́вити ми́лость Свою́ на ни і на ро́ди родо́в на́ших, утверди́ти ни в правові́рії і благоче́стії, храни́ти же от всіх бід і зол, да сподо́бимся с тобо́ю, я́коже ча́да со отце́м, во ві́ки воспіва́ти Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелом і челові́ком Творе́ць, времена́ і лі́та во Своє́й вла́сті положи́вий і судьби́ государств і наро́дов устроя́яй, єгда́ благоізво́ли призва́ти род ру́ський от тьми ідолослуже́нія ко сві́ту і́стини і пра́вди ві́чния, поста́ви тя, благові́рний кня́же, благовісти́теля і соверши́теля сея́ всеблагия во́лі Своєя́. Ті́мже, благодаря́ще Творця́ і Спа́са на́шего, славосло́вим тя, я́ко вели́каго ізбра́нника Бо́жия на́шего ра́ди спасе́нія, с весе́лієм зову́ще:","Ра́дуйся, равноапо́столе, ко просвіще́нію наро́да ру́ськаго Прему́дрим Про́мислом предизбранний;","ра́дуйся, от первозва́ннаго апо́стола на гора́х Ки́євських прорече́нний.","Ра́дуйся, пресла́вний сосу́де Боже́ственния благода́ті, держа́ві твоє́й дарова́нний;","ра́дуйся, пречу́дний ко́реню, із него́же на землі́ на́шей проізрасте ве́ліє дре́во правові́рія.","Ра́дуйся, я́ко тобо́ю І́м'я Госпо́днє во всіх преді́ліх страни́ твоє́й прославля́ється;","ра́дуйся, я́ко і твоє́ пресла́вноє і́м'я от всіх родо́в ру́ських с любо́вію воспіва́ється.","Ра́дуйся, Влади́мире, держа́ви Ру́ськия просвіти́телю."]},{"h":"Кондак 1","ps":["Ізбранного світи́льника, тьму ідолослуже́нія в держа́ві Ру́ськой разгна́вшаго і сві́том Боже́ственния ві́ри ю просвіти́вшаго, восхваля́єм тя, святи́й равноапостольний кня́же Влади́мире: ти же я́ко ви́ну со дерзнове́нієм предстоя́й Царю́ ца́рствующих, не преста́й моля́ся о достоя́нії твоє́м і твої́ми моли́твами сохраня́й нас от вся́ких бід і зол, да со умиле́нієм благода́рственно зове́м ті:","Ра́дуйся, Влади́мире, держа́ви Ру́ськия просвіти́телю."]},{"h":"Молитва","ps":["О, вели́кий уго́дниче Бо́жий, богоізбра́нний і богопросла́вленний, равноапостольний кня́же Влади́мире! Ти отри́нул єси́ злові́ріє і нече́стіє язи́чеськоє, уві́ровал єси́ во Єди́наго І́стиннаго Триіпоста́снаго Бо́га і, восприя́в Свято́є Креще́ніє, просвіти́л єси́ сві́том Боже́ственния ві́ри і благоче́стія всю страну́ Ру́ськую. Сла́в'яще у́бо і благодаря́ще Премилосе́рдаго Творця́ і Спаси́теля на́шего, сла́вим, благодари́м і тя, просвіти́телю наш і о́тче, я́ко тобо́ю позна́хом спаси́тельную ві́ру Христо́ву і крести́хомся во І́м'я Пресвяти́я і Пребоже́ственния Тро́йці: то́ю ві́рою ізба́вихомся от пра́веднаго осужде́нія Бо́жия, ві́чнаго ра́бства дия́воля і а́дова мучи́тельства; то́ю ві́рою восприя́хом благода́ть всиновле́нія Бо́гу і наде́жду наслі́дованія Небе́снаго блаже́нства. Ти єси́ пе́рвий вождь наш к Нача́льнику і Соверши́телю на́шего ві́чнаго спасе́нія Го́споду Ісу́су Христу́; ти єси́ те́плий моли́твенник і хода́тай о страні́ Ру́ськой, о во́їнстві і о всіх лю́діх. Не мо́жеть язи́к наш ізобрази́ти вели́чіє і висоту́ благодія́ній, тобо́ю ізлія́нних на зе́млю на́шу, отце́в і пра́отцев на́ших і на нас, недосто́йних. О всеблаги́й о́тче і просвіти́телю наш! При́зри на не́мощі на́ша і умоли́ премилосе́рдаго Царя́ Небе́снаго, да не прогні́вається на ни зіло́, я́ко по не́мощем на́шим по вся дні согріша́єм, да не погуби́ть нас со беззако́ньми на́шими, но да поми́луєть і спасе́ть нас, по ми́лості Своє́й, да всади́ть в се́рдці на́ше спаси́тельний страх Свой, да просвіти́ть Своє́ю благода́тію ум наш, во є́же разумі́ти нам путі́ Госпо́дні, оста́вити стезі́ нече́стія і заблужде́ній, тща́тися же во стезя́х спасе́нія і і́стини, неукло́ннаго ісполне́нія за́повідей Бо́жиїх і уста́вов Святи́я Це́ркве. Моли́, благосе́рде, Человіколю́бця Го́спода, да проба́вить нам вели́кую ми́лость Свою́, да ізба́вить нас от наше́ствія іноплеме́нних, от вну́тренних нестроє́ній, м'яте́жей і раздо́ров, от гла́да, смертоно́сних болі́зней і от вся́каго зла, да пода́сть нам благорастворе́ніє возду́ха і плодоно́сіє землі́, да дасть па́стирем ре́вность о спасе́нії пасо́мих, всім же лю́дем споспіше́ніє о є́же усе́рдно слу́жби своя́ ісправля́ти, любо́в между́ собо́ю і єдиноми́сліє імі́ти, на бла́го же Оте́чества і Святи́я Це́ркве ві́рне подвиза́тися, да возсія́єть світ спаси́тельния ві́ри в страні́ на́шей во всіх конці́х єя́, да упраздня́ться вся є́ресі і раско́ли, да та́ко пожи́вше в ми́рі на землі́, сподо́бимся с тобо́ю ві́чнаго блаже́нства, хва́ляще і превознося́ще Бо́га во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Уподо́бился єси́ купцю́, і́щущему до́браго би́сера, / славнодержа́вний Влади́мире, / на висоті́ стола́ сідя́ ма́тере градо́в, богоспаса́ємаго Ки́єва: / іспиту́я же і посила́я к Ца́рскому гра́ду / уві́діти правосла́вную ві́ру, / обрі́л єси́ бесці́нний би́сер - Христа́, / ізбра́вшаго тя я́ко втора́го Па́вла, / і оттря́сшаго сліпоту́ во святі́й купі́лі, / душе́вную вку́пі і тіле́сную. / Ті́мже пра́зднуєм твоє́ успе́ніє, / лю́діє твої́ су́ще: // моли́ спасти́ся держа́ви твоєя́ Россі́йськия нача́льником і мно́жеству владо́мих."]},{"h":"Інший тропар, глас 1","ps":["Я́ко нача́льнику Креще́нія / і ко́реню ві́ри Боже́ственния, / і́долов разруши́телю, / блаже́нне кня́же Васи́ліє равноапо́стольне, вопіє́м ті: / сла́ва вразу́мльшему тя Христу́ Бо́гу, / сла́ва освяти́вшему тя Креще́нієм Свої́м, // сла́ва просвіти́вшему тобо́ю всю страну́ Ру́ськую."]},{"h":"Інший тропар, глас 8","ps":["Правові́рія наста́вниче / і всея́ Руси́ просвіти́телю, / благочести́вий вели́кий кня́же Влади́мире, / святи́м Креще́нієм всіх просвіти́л єси́ / і це́ркві мно́гі сла́вни украси́л єси́, / о прему́дрі Васи́ліє, // Христа́ Бо́га моли́ спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 8","ps":["Подо́бствовав вели́кому апо́столу Па́влу в сіди́нах, всесла́вне Влади́мире, / вся я́ко младе́нчеськая мудрова́нія, я́же о і́доліх тща́нія оста́вль, / я́ко муж соверше́нний украси́лся єси́ Боже́ственнаго Креще́нія багряни́цею. / І ни́ні Спа́су Христу́ во весе́лії предстоя́, // моли́ спасти́ся держа́ви Россі́йськия нача́льником і мно́жеству владо́мих."]},{"h":"Інший кондак, глас 8","ps":["Ізря́дному воєво́ді і правові́рному, / благода́рственная воспису́єть ті вся Русь, Васи́ліє, іму́щи тя нача́льника і засту́пника, / я́ко ізба́вил єси́ нас от вся́кия скве́рни і ле́сти, ті́мже ті вопіє́м: // ра́дуйся, вели́кий кня́же Влади́мире преблаже́нне."]},{"h":"Інший кондак, глас 4","ps":["Оте́чеську пре́лесть, і́доли, я́ко су́єтни, отве́рг, / Христа́, всіх і́стиннаго Бо́га, Царя́ і Благода́теля, позна́л єси́. / Ті́мже і лю́ди, ізря́дни Тому́, святи́м Креще́нієм просвіти́л єси́, / пресла́вне Влади́мире. / Сего́ ра́ди почита́єм тя, / я́ко Тро́йце служи́теля, // Христа́ моли́ дарова́ти нам ве́лію ми́лость."]},{"h":"Величання","ps":["Велича́єм тя, / святи́й равноапостольний кня́же Влади́мире, / і чтим святу́ю па́м'ять твою́, / і́доли попра́вшаго // і всю Россі́йськую зе́млю святи́м Креще́нієм просвіти́вшаго."]}],"notes":[]},{"u":"Акафіст преподобним Оптинським старцям","e":"Akathist to the Venerable Elders of Optina","secs":[{"h":"Кондак 1","ps":["Ізбра́нним служи́телем Святи́я Тро́йці, собо́ру преподо́бних Ста́рцев О́птинських, наста́вником до́брим і прему́дрим благодаре́ніє і похвали́ прино́сим. Ви же, я́ко Христо́ви Це́ркве украше́ніє, молі́теся о нас ко Го́споду, да воспіва́єм вам любо́вію:","Ра́дуйтеся, преподо́бнії Ста́рці О́птинстії, богому́дрії наста́вници ві́ри і благоче́стія."]},{"h":"Ікос 1","ps":["А́нгелов Творе́ць просла́ви вас, отці́ і Ста́рці преподо́бнії, я́ко сби́тися на вас рече́нному: світ мона́хом суть А́нгели, світ же всім челові́ком єсть мона́шеськоє житіє́. Воі́стину у́бо яви́лися єсте́ а́нгели храни́теліє страні́ на́шей Росси́йстій: і́ноком наста́вници, ко спасе́нію путевожді́є всім ві́рним ча́дом Це́ркве, вопію́щим:","Ра́дуйся, богопросла́вленний собо́ре;","ра́дуйся, богоза́рноє благода́ті сія́ніє.","Ра́дуйся, дре́во ста́рчества многопло́дноє;","ра́дуйся, во Христі́ єди́нство духо́вноє.","Ра́дуйся, по́лче, іспо́лненний си́ли Бо́жия;","ра́дуйся, во́їнство, побіжда́ющеє де́монов.","Ра́дуйся, ві́нче, Ду́хом Святи́м благоуха́ющий;","ра́дуйся, О́птини пу́стині сла́во і похвало́.","Ра́дуйся, Христо́в пречу́дний виногра́де;","ра́дуйся, ми́сленний раю́ богонасажде́нний.","Ра́дуйся, ликостоя́ніє півце́в Святи́я Тро́йці;","ра́дуйся, созві́здіє тве́рди Небе́сния.","Ра́дуйтеся, преподо́бнії Ста́рці О́птинстії, богому́дрії наста́вници ві́ри і благоче́стія."]},{"h":"Кондак 2","ps":["Ви́дяще су́єтная і привре́менная, я́же в ми́рі сем, вся́коє жите́йськоє попече́ніє отверго́сте, отці́ богому́дрії, прийдо́сте в Пу́стинь О́птину, іді́же дре́вній о́браз о́бщаго житія́ яви́сте: соу́з любве́ неразруши́мий о Христі́ і ре́вность первохристия́нськую Заві́та Но́ваго, невозвра́тно ко Го́споду устреми́стеся любо́вію, а́нгельськую піснь воспіва́юще: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум спасе́нія взиску́юще, отці́ пресла́внії, бога́тство, сла́ву і вся земна́я, я́ко мимотеку́щая, презрі́вше, єди́но же на потре́бу ізбра́сте; мно́гими труди́, скорбми́ і болі́зньми до́броє основа́ніє по́двигу положи́сте. Ті́мже, Христо́ви за́повіді сотво́рше і святи́х оте́ць сові́ти соблю́дше, доброді́тельми обогати́лися єсте́. Сего́ ра́ди вопіє́м вам:","Ра́дуйтеся, Христо́во смире́ніє возлюби́вшії;","ра́дуйтеся, кро́тость ду́ха терпі́нієм стяжа́вшії.","Ра́дуйтеся, во́лі Бо́жієй послі́довавшії;","ра́дуйтеся, свою́ во́лю отсі́кшії.","Ра́дуйтеся, моли́твою і посто́м Бо́гу служи́вшії;","ра́дуйтеся, чи́стим се́рдцем Го́спода зря́щії.","Ра́дуйтеся, стра́сті тіле́сния воздержа́нієм умертви́вшії;","ра́дуйтеся, плоть ва́шу Ду́хові покори́вшії.","Ра́дуйтеся, ми́лость я́ко ца́рський путь ізбра́вшії;","ра́дуйтеся, разсужде́ніє я́ко верх доброді́телей обрі́тшії.","Ра́дуйтеся, благонра́вную жизнь показа́вшії.","Ра́дуйтеся, от Бо́га благи́я да́ри приє́мшії.","Ра́дуйтеся, преподо́бнії Ста́рці О́птинстії, богому́дрії наста́вници ві́ри і благоче́стія!"]},{"h":"Кондак 3","ps":["Си́ла Моя́ в не́мощі соверша́ється, рече́ Госпо́дь. Ті́мже і ви, преподо́бнії, яре́м скорбе́й і болі́зней под'є́мше, си́лою Ду́ха обогати́стеся: дар разсужде́нія прия́сте, і прему́дрость ста́рчества улучи́сте, воспіва́юще Пода́телю вся́чеських: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я о спасе́нії челові́ков ди́вноє промишле́ніє, сла́вимий в Тро́йці Бог виногра́д ста́рчества оби́льно во Єги́пті возрасти́, і іспо́лни сей всю зе́млю; і отра́сль єго́ в послі́дняя лі́та дости́же пу́стині О́птинськия. Сія́ до́брими виногра́дари отребля́єма і вода́ми пита́ємая святого́рськими і фиваї́дськими, бога́тий плод принесе́. Сіє́ до́брі разумі́вше, воззове́м Ста́рцем О́птинським си́це:","Ра́дуйся, Мойсе́є, ізбра́нний пустинножи́телю;","ра́дуйся, ста́рчества О́птинськаго насади́телю.","Ра́дуйся, Анто́ніє, богоуго́дний подви́жниче;","ра́дуйся, смире́нія і кро́тости наста́вниче.","Ра́дуйся, о́тче Льве, по Бо́зі пла́менний ревни́телю;","ра́дуйся, ста́рчества О́птинськаго возрасти́телю.","Ра́дуйся, ду́шу свою́ за ча́да положи́ти гото́вий;","ра́дуйся, во оби́тель Про́мислом Бо́жиїм приведе́нний.","Ра́дуйся, Мака́ріє, висото́ смире́нія;","ра́дуйся, глубино́ прему́дрости ста́рчеськия.","Ра́дуйся, Ісаа́кіє, вертогра́да ста́рчества храни́телю;","ра́дуйся, оте́чеських заві́тов ві́рний ісполни́телю.","Ра́дуйтеся, преподо́бнії Ста́рці О́птинстії, богому́дрії наста́вници ві́ри і благоче́стія!"]},{"h":"Кондак 4","ps":["Бу́рноє мо́ре без ко́рмчаго нікто́же мо́жеть прейти́; ізра́їльтяне же, Моїсе́ом путеводи́мії, я́ко по су́ху прейдо́ша є. Сей проо́браз ста́рчества приє́мше, богоно́снії отці́ О́птинстії, я́коже о́ний Мойсе́й, чрез мо́ре жите́йськоє мно́гим ко спасе́нію путеводи́теліє яви́лися єсте́, указу́юще єди́н Путь, Христа́ Го́спода, Єму́же при́сно воспіва́єм: Аллилу́я."]},{"h":"Ікос 4","ps":["Слу́шаяй вас, Мене́ слу́шаєть, рече́ Госпо́дь Свої́м ученико́м, на про́повідь я посила́я. І та́ко положе́но бисть свята́го ста́рчества основа́ніє, да всяк ві́чния жи́зні іски́й, вопроша́єть ста́рця своєго́, да блага́я позна́єть во спасе́ніє. Сіє́ Боже́ственноє уставле́ніє ві́дуще, ви, святі́ї Льве і Мака́ріє, созда́сте ста́рчество на тве́рдем ка́мені смире́нія, ті́мже восхва́лим Ста́рцев О́птинських си́це:","Ра́дуйтеся, любо́вію к бли́жнім озаре́ннії;","ра́дуйтеся, благода́тію ста́рчества одаре́ннії.","Ра́дуйтеся, к Бо́гу ві́рнії путеводи́теліє;","ра́дуйтеся, мно́гих душ просвіти́теліє.","Ра́дуйтеся, смире́нію Христо́ву науча́ющії;","Ра́дуйтеся, в пра́вді жи́ти нас укрепля́ющії.","Ра́дуйтеся, мона́шеськаго житія́ ревни́теліє;","ра́дуйтеся, послуша́нія до́брії учи́теліє.","Ра́дуйтеся, на путь покая́нія наставля́ющії;","ра́дуйтеся, к любві́ Бо́жієй всіх возвиша́ющії.","Ра́дуйтеся, до́брії ді́лателіє виногра́да Христо́ва;","ра́дуйтеся, я́ко отве́рзеся вам Ца́рство Небе́сноє.","Ра́дуйтеся, преподо́бнії Ста́рці О́птинстії, богому́дрії наста́вници ві́ри і благоче́стія!"]},{"h":"Кондак 5","ps":["Богоблаже́ннії отці́ Мойсе́є і Ісаа́кіє, ре́вностію о до́мі Бо́жиєм дви́жимії, неле́ностнії зижди́теліє оби́телі яви́лися єсте́, поло́жше во главу́ у́гла Ка́мень краєуго́лен. Сего́ ра́ди воздвиго́сте ди́вния красоти́ хра́ми Бо́жия, іді́же ми ни́ні воспіва́єм: Аллилу́я."]},{"h":"Ікос 5","ps":["Виді́нія і созерца́нія та́їн Боже́ственних сподо́бльшеся, яви́стеся благочи́нія церко́внаго приле́жнії ревни́теліє і благолі́пія богослуже́нія рачи́теліє, є́же жи́ти вам в дому́ Госпо́дні і зрі́ти красоту́ єго́. Ті́мже і ми ни́ні, услажда́ющеся красото́ю оби́телі О́птинськия і разумі́юще ізря́дноє попече́ніє ва́ше о ней, благода́рно вам взива́єм:","Ра́дуйся, Анто́ніє, усе́рдний скита́ строї́телю;","ра́дуйся, уде́ла Предте́чі Госпо́дня попечи́телю.","Ра́дуйся, Мака́ріє, писа́ньми мно́гих просвіти́вий;","ра́дуйся, слу́жби церко́вния украси́вий.","Ра́дуйся, Амвро́сіє, ди́вно на возду́сі моли́вийся;","ра́дуйся, в моли́тві сла́ву Бо́жию созерца́вий.","Ра́дуйся, богому́дрий наста́вниче і учи́телю,","ра́дуйся, Ша́мординськия оби́телі созда́телю і окорми́телю.","Ра́дуйся, Іларіо́не, заблу́ждших обраща́яй;","ра́дуйся, тіх к та́їнством церко́вним привлека́яй.","Ра́дуйся, Ісаа́кіє, оби́телі до́брий управи́телю;","ра́дуйся, і́ноков ві́рний путеводи́телю.","Ра́дуйтеся, преподо́бнії Ста́рці О́птинстії, богому́дрії наста́вници ві́ри і благоче́стія!"]},{"h":"Кондак 6","ps":["Пропові́дници І́стини яви́стеся, богоно́снії Ста́рці О́птинстії, наставля́юще вся бли́жняя і да́льняя, я́ко столп єсть і утвержде́ніє і́стини Це́рков Правосла́вная, єя́же вні нікто́же мо́жеть спасе́ніє улучи́ти і жизнь ві́чную наслі́дити. Си́це ва́ми науче́ннії, ко Го́споду взива́єм ра́достно: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́сте сві́том доброді́тельнаго житія́ і світ і́стиннаго богопозна́нія уясни́сте, із'ясне́ніє слове́с святи́х оте́ць нам яви́вше, к сим же і своя́ писа́нія оста́вивше. Сего́ ра́ди, уподо́бльшеся челові́ку домови́ту, і́же ізно́сить от сокро́вища своєго́ но́вая і ве́тхая, умно́жили єсте́ тала́нти Влади́ці Христу́ і просла́вистеся от Него́; ми же тщі́мся пі́ти вам такова́я:","Ра́дуйтеся, зако́на Бо́жия ревни́теліє;","ра́дуйтеся, і́стиннаго любому́дрія рачи́теліє.","Ра́дуйтеся, ключ разумі́нія нам подава́ющії;","ра́дуйтеся, две́рі і́стини отверза́ющії.","Ра́дуйтеся, прему́дрости Бо́жия сокро́вище;","ра́дуйтеся, слове́с Боже́ственних істо́чниче.","Ра́дуйтеся, сві́та єва́нгельськаго сія́ніє;","ра́дуйтеся, за́повідей Христо́вих соблюде́ніє.","Ра́дуйтеся, писа́ній оте́чеських із'ясни́теліє;","ра́дуйтеся, благоче́стія насади́теліє.","Ра́дуйтеся, да́нний вам тала́нт возрасти́вшії;","ра́дуйтеся, в ра́дость Влади́ки Христа́ вше́дшії.","Ра́дуйтеся, преподо́бнії Ста́рці О́птинстії, богому́дрії наста́вници ві́ри і благоче́стія!"]},{"h":"Кондак 7","ps":["Хотя́й угоди́ти Бо́гові, велі́ній Єго́ яви́лся єси́ усе́рдний храни́тель, преподо́бне Мака́ріє, соблюда́я за́повідь Госпо́дню: а́ще кто тя уда́рить в лани́ту десну́ю, обрати́ тому́ і другу́ю. Си́лою толи́каго смире́нія ісхожда́ху ду́си нечи́стії от одержи́мих ті́ми. Ми же, о́браз зря́ще сей смиренному́дрія, сла́вим Бо́га: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вих ви́дяще ізбра́нников Бо́жиїх, притека́ху к вам люде́й мно́жества, ча́юще сові́та і благослове́нія, утіше́нія же і ісціле́нія. Ви же всім вся яви́лися єсте́: грі́шния на путь покая́нія наста́вльше, малові́рния утверди́вше, стра́ждущим спострада́вше, немощни́м ісціле́нія дарова́вше. Ті́мже і нас укріпля́єте пі́ти вам:","Ра́дуйся, Мака́ріє, зло́бу дия́волю побіди́вий;","ра́дуйся, того́ смире́нієм низложи́вий.","Ра́дуйся, Амвро́сіє, в болі́зніх долготерпіли́вий;","ра́дуйся, сле́зи стра́ждущих ізсуши́вий.","Ра́дуйся, Іо́сифе, свята́го Амвро́сія преє́мниче,","ра́дуйся, по до́брім учи́тели мона́хов наста́вниче.","Ра́дуйся, Цари́ці Небе́сния люби́миче блаже́нний,","ра́дуйся, Є́ю от одра́ болі́зні возста́вленний.","Ра́дуйся, Варсоно́фіє, сла́ву земну́ю презрі́вий,","ра́дуйся, во́їнству Царя́ Небе́снаго причте́нний.","Ра́дуйся, незри́мих враго́в побіди́телю,","ра́дуйся, прозорли́вий душ врачева́телю.","Ра́дуйтеся, преподо́бнії Ста́рці О́птинстії, богому́дрії наста́вници ві́ри і благоче́стія!"]},{"h":"Кондак 8","ps":["Стра́нников і прише́льцев себе́ на землі́ би́ти помишля́юще, святи́й Амвро́сіє со ученики́, ті́сний путь служе́нія бли́жнім ізбра́сте. Сего́ ра́ди яви́шася на вас дарова́нія духо́внаго разсужде́нія, тіле́с ісціле́нія, суде́б Бо́жиїх тайнозре́нія, душ ізнемога́ющих врачева́нія. Си́ми да́ри а́ки мре́жами мно́жество душ уловля́юще, Святі́й Тро́йці воспіва́ли єсте́ піснь: Аллилу́я."]},{"h":"Ікос 8","ps":["Всім се́рдцем, душе́ю і ми́слію Бо́га возлюби́вше, не то́кмо утіше́нія тре́бующих ніколи́же оставля́сте, поле́зная на потре́бу коєму́ждо подаю́ще, но і все вре́м'я житія́ моли́тві приліжа́ще, і́стиннаго богоми́слія сподо́билися єсте́, преподо́бнії, посто́м і моли́твою, нестяжа́нієм і чистото́ю, разсужде́нієм і ми́лостію украше́ннії, сли́шіте от нас сицева́я:","Ра́дуйтеся, всегда́ пред Го́сподем ходи́вшії;","ра́дуйтеся, от дія́нія к созерца́нію восте́кшії.","Ра́дуйтеся, тяготи́ мно́гих поне́сшії;","ра́дуйтеся, та́ко зако́н Христо́в іспо́лнившії.","Ра́дуйтеся, бли́жнему блага́я іска́вшії;","ра́дуйтеся, тіх не́мощі любо́вію покрива́вшії.","Ра́дуйтеся, си́лу вра́жию низложи́вшії;","ра́дуйтеся, ко́зні бісо́в сокруши́вшії.","Ра́дуйтеся, лю́ди Бо́жия до́брі спаса́ющії;","ра́дуйтеся, ми́сленния та́ти от тіх отгоня́ющії.","Ра́дуйтеся, со́вість от гріхо́в очища́ющії;","ра́дуйтеся, скорб серде́чную облегча́ющії.","Ра́дуйтеся, преподо́бнії Ста́рці О́птинстії, богому́дрії наста́вници ві́ри і благоче́стія!"]},{"h":"Кондак 9","ps":["Всяк язи́к, всяк во́зраст, вся́ко сосло́віє хва́лить ви, собо́ре досточу́дний преподо́бних Ста́рцев: упасли́ бо єсте́ ста́до Христо́во усе́рдно і неув'яда́ємия вінці́ сла́ви от Пастиренача́льника прия́ли єсте́. Ті́мже і нас науча́єте повинова́тися ста́рцем і па́стирем, да, смиренному́дріє стяжа́вше, благода́ть обря́щем пі́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Ка́ко боже́ственную ва́шу к челові́ком любо́в ізглаго́лем: до кро́ве бо подвиза́ющеся і ду́ші своя́ за ча́да полага́юще, служе́нія своєго́ ніка́коже оста́вили єсте́. Ми же, предста́тельством ва́шим у Царя́ ца́рствующих оби́телі О́птинськия узрі́вше возрожде́ніє, ча́єм і хра́мов душ на́ших обновле́ніє улучи́ти, со умиле́нієм вам глаго́люще:","Ра́дуйся, Некта́ріє, блаже́нний наста́вниче,","ра́дуйся, гряду́щих прозорли́вий прови́дче.","Ра́дуйся, Ісаа́кіє, сла́вний преподобному́чениче,","ра́дуйся, тве́рдий крестоно́сче.","Ра́дуйся, Анато́ліє, наро́да Бо́жия окормле́ніє,","ра́дуйся, в годи́ну іскуше́ній всіх укріпле́ніє.","Ра́дуйся, за ві́ру поруга́нія приє́мий,","ра́дуйся, в ми́рі дух твой Бо́гу преда́вий.","Ра́дуйся, Ни́коне, мона́хов кро́ткоє утіше́ніє,","ра́дуйся, іспові́дниче многострада́льний.","Ра́дуйся, мно́жество скорбе́й претерпі́вий,","ра́дуйся, сумня́щихся в Правосла́вії утверди́вий.","Ра́дуйтеся, преподо́бнії Ста́рці О́птинстії, богому́дрії наста́вници ві́ри і благоче́стія!"]},{"h":"Кондак 10","ps":["Спа́са ми́ра ві́рнії ученици́ яви́стеся, богоблаже́ннії, благоче́стно во Христі́ пожи́вшії: о́ви у́бо в труді́х зижди́тельних, о́ви же в не́мощіх многоболі́зненних, о́ви же в гоне́ніїх непра́ведних; проідо́сте путь притру́днаго сего́ житія́ і многоплаче́внаго, о́браз нам подаю́ще, ка́ко достої́ть в ско́рбіх пі́ти Го́споду Сил: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єсте́ Це́ркве Правосла́вния, забра́ло же неруши́моє честна́го і́ночества: вся бо ору́жія Бо́жия приє́мше і обо́лкшеся в броня́ пра́вди, і нас ві́рно науча́єте, ка́ко щит ві́ри, шлем спасе́нія і меч духо́вний, глаго́л Бо́жий обоюдуо́стрий, восприйма́ти подоба́єть. Помина́юще вас я́ко наста́вников, усе́рдно мо́лимся, да сподо́бит Госпо́дь подража́ти ві́рі ва́шей і вопи́ти:","Ра́дуйтеся, му́дрости Бо́жієй науча́ющії;","ра́дуйтеся, вода́ми жи́зні напая́ющії.","Ра́дуйтеся, мона́шествующих укріпле́ніє;","ра́дуйтеся, священної́ноков вспоможе́ніє.","Ра́дуйтеся, во оби́телі ва́шей незри́мо пребива́ющії;","ра́дуйтеся, чад свої́х не оставля́ющії.","Ра́дуйтеся, ско́рії в ско́рбіх помо́щници;","ра́дуйтеся, неуси́пнії оби́телі охрани́теліє.","Ра́дуйтеся, покро́вом Всецари́ці осене́ннії;","ра́дуйтеся, Ду́ха Свята́го сосу́ди ізбра́ннії.","Ра́дуйтеся, снаслі́дници Ца́рствія Христо́ва;","ра́дуйтеся, по благода́ті си́нове Отця́ Небе́снаго.","Ра́дуйтеся, преподо́бнії Ста́рці О́птинстії, богому́дрії наста́вници ві́ри і благоче́стія!"]},{"h":"Кондак 11","ps":["Пі́ніє от серде́ць на́ших ізноси́моє сподо́бльшеся приноси́ти вам, отці́ преподо́бнії, пред честни́ми моща́ми ва́шими, недоуміва́єм, ка́ко досто́йно просла́вити просла́вльшаго вас, ди́внаго во святи́х Свої́х Бо́га на́шего. То́чію моли́твами ва́шими укріпля́ємі, немо́лчно вопіє́м Єму́: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоза́рния лучи́ Со́лнця Пра́вди, столпи́ благоче́стія, достиза́ющії Небесе́, воі́стину яви́лися єсте́, отці́ на́ші преподо́бнії! Ни́ні же, во Оби́теліх Небе́сних наслажда́ющеся, Престо́лу Святи́я Тро́йці предстоїте́, но і нас недосто́йних не оставля́єте, дар многоці́нен нам яви́вше цільбоно́сния мо́щі ва́ша, к ни́мже притека́юще, зове́м:","Ра́дуйтеся, Мойсе́є со Анто́нієм, опло́ті ста́рчества;","ра́дуйся, о́тче Льве, ста́рчества ко́реню крі́пкий.","Ра́дуйся, Мака́ріє, о́бразе смиренному́дрія;","ра́дуйся, Ісаа́кіє, домоправи́телю Влади́ки Христа́.","Ра́дуйся, Іларіо́не, душ і тіле́с ціле́бниче;","ра́дуйся, Анато́ліє, моли́тви світи́льниче.","Ра́дуйся, Амвро́сіє, благоуха́нний кри́не ста́рчества;","ра́дуйся, Іо́сифе, блага́го ко́рене отра́сле до́брая.","Ра́дуйся, Варсоно́фіє, до́блій стратила́те Христо́в;","ра́дуйся, Анато́ліє, уті́шителю скорб'я́щих.","Ра́дуйся, Некта́ріє, прозорли́вче і те́плий моли́твенниче;","ра́дуйтеся, Ісаа́кіє со Ни́коном, сла́внії му́ченици і іспові́дниці.","Ра́дуйтеся, преподо́бнії Ста́рці О́птинстії, богому́дрії наста́вници ві́ри і благоче́стія!"]},{"h":"Кондак 12","ps":["Благода́ть Бо́жию приє́мшії, Ста́рці преподо́бнії, тече́ніє житія́ проідо́сте в по́двизіх і доброді́теліх, не іму́ще зді пребива́ющаго гра́да, но гряду́щаго взиску́юще, єго́же і достиго́сте, Го́рняго о́наго прекра́снаго Ієрусали́ма, іді́же с ли́ки А́нгелов во сві́тлості неізрече́нній поє́те Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще і пра́зднующе всесві́тлую па́м'ять ва́шу, отці́ пресла́внії, почита́єм труди́ і лише́нія, ско́рби і болі́зні, гоне́нія і страда́нія ва́ша: не то́чію бо о́вці ста́да Христо́ва укріпи́сте, но і ві́ри Христо́ви іспові́дниці би́сте. Ті́мже і, блаже́нств єва́нгельських прича́стници яви́вшеся, сли́шіте воспіва́ємая вам сицева́я:","Ра́дуйтеся, нището́ю ду́ха бога́тії;","ра́дуйтеся, мно́гаго ра́ди пла́ча уті́шеннії.","Ра́дуйтеся, наслі́дници землі́ кро́тких;","ра́дуйтеся, обрі́тшії пра́вду Христо́ву.","Ра́дуйтеся, я́ко поми́лованіє улучи́вшії;","ра́дуйтеся, чи́стим се́рдцем Бо́га зря́щії.","Ра́дуйтеся, дух ми́рен стяжа́вшії;","ра́дуйтеся, мно́жество душ тім спаса́вшії.","Ра́дуйтеся, гоне́ніє за пра́вду Бо́жию претерпі́вшії;","ра́дуйтеся, в Небе́сноє Ца́рствіє возше́дшії.","Ра́дуйтеся, гони́мії от неві́рних на землі́;","ра́дуйтеся, я́ко мзда ва́ша мно́га на Небесі́х.","Ра́дуйтеся, преподо́бнії Ста́рці О́птинстії, богому́дрії наста́вници ві́ри і благоче́стія!"]},{"h":"Кондак 13","ps":["О вели́ції уго́дниці Бо́жії, преподо́бнії Ста́рці О́птинстії! Ми́лостивно приймі́те от нас сіє́ хвале́ніє, с любо́вію вам ни́ні приноси́моє, і те́плим ва́шим хода́тайством ко Го́споду іспросі́те нам во ві́рі утвержде́ніє, покая́ніє і во́лі Бо́жієй послі́дованіє, да ізба́вленнії му́ки ві́чния, ку́пно с ва́ми воспіва́єм Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов Творе́ць просла́ви вас, отці́ і Ста́рці преподо́бнії, я́ко сби́тися на вас рече́нному: світ мона́хом суть А́нгели, світ же всім челові́ком єсть мона́шеськоє житіє́. Воі́стину у́бо яви́лися єсте́ а́нгели храни́теліє страні́ на́шей Росси́йстій: і́ноком наста́вници, ко спасе́нію путевожді́є всім ві́рним ча́дом Це́ркве, вопію́щим:","Ра́дуйся, богопросла́вленний собо́ре;","ра́дуйся, богоза́рноє благода́ті сія́ніє.","Ра́дуйся, дре́во ста́рчества многопло́дноє;","ра́дуйся, во Христі́ єди́нство духо́вноє.","Ра́дуйся, по́лче, іспо́лненний си́ли Бо́жия;","ра́дуйся, во́їнство, побіжда́ющеє де́монов.","Ра́дуйся, ві́нче, Ду́хом Святи́м благоуха́ющий;","ра́дуйся, О́птини пу́стині сла́во і похвало́.","Ра́дуйся, Христо́в пречу́дний виногра́де;","ра́дуйся, ми́сленний раю́ богонасажде́нний.","Ра́дуйся, ликостоя́ніє півце́в Святи́я Тро́йці;","ра́дуйся, созві́здіє тве́рди Небе́сния.","Ра́дуйтеся, преподо́бнії Ста́рці О́птинстії, богому́дрії наста́вници ві́ри і благоче́стія."]},{"h":"Кондак 1","ps":["Ізбра́нним служи́телем Святи́я Тро́йці, собо́ру преподо́бних Ста́рцев О́птинських, наста́вником до́брим і прему́дрим благодаре́ніє і похвали́ прино́сим. Ви же, я́ко Христо́ви Це́ркве украше́ніє, молі́теся о нас ко Го́споду, да воспіва́єм вам любо́вію:","Ра́дуйтеся, преподо́бнії Ста́рці О́птинстії, богому́дрії наста́вници ві́ри і благоче́стія."]},{"h":"Молитва","ps":["О, преподо́бнії і богоно́снії отці́ на́ші, Ста́рці О́птинстії, богому́дрії учи́теліє ві́ри і благоче́стія, столпи́ і світи́льници всім взиску́ющим спасе́нія і жи́зні ві́чния: Льве, Мака́ріє, Мойсе́є, Анто́ніє, Іларіо́не, Амвро́сіє, Ісаа́кіє, Анато́ліє, Іо́сифе, Варсоно́фіє, Анато́ліє, Некта́ріє, Ни́коне іспові́дниче і преподобному́чениче Ісаа́кіє, мо́лим вас при́сно ми, недосто́йнії, да сохрани́ть Христо́с Бог предста́тельством ва́шим Це́рков Свою́ Святу́ю, страну́ Россі́йськую, оби́тель О́птинськую і вся́кий град і страну́, іді́же сла́виться і правосла́вно іспові́дується і́м'я Єго́ Боже́ственноє.","Молі́теся о нас, о преподо́бнії Ста́рці О́птинстії, да у́зрим беззако́нія на́ша і принесе́м пред Го́сподом на́шим Ісу́сом Христо́м покая́ніє многосле́зноє, да очи́стить мно́гія гріхи́ на́ша і да́руєть нам времена́ ми́рная і ко спасе́нію благоуспе́шная, да укроти́ться суєта́ ві́ка сего́ под крі́пкую ру́ку Бо́жию, я́ко да стяже́м дух ми́ра, кро́тости, братолю́бія і милосе́рдія ко стра́ждущим.","О, преподо́бнії, молі́те і Ма́тер Сві́та, Цари́цю Небе́сную, Пречи́стую Богоро́дицю, да отве́рзеть две́рі милосе́рдія Си́на Своєго́ і Бо́га на́шего і да сподо́бит і нас до́браго отві́та на Стра́шнім Суди́щі, ві́чних мук да ізба́вить і ку́пно с ва́ми да удосто́їть во Ца́рствії Небе́снім сла́вити і воспіва́ти пречестно́є і великолі́поє і́м'я Отця́, і Си́на, і Свята́го Ду́ха во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 6","ps":["Правосла́вния ві́ри світи́льници, / мона́шества непоколеби́мії столпи́, / землі́ Россі́йськия уті́шителіє, / преподо́бнії ста́рці О́птинстії, / любо́в Христо́ву стяжа́вши / і ду́ші своя́ за ча́да полага́вши, / молі́теся ко Го́споду, / да утверди́ть земно́є Оте́чество ва́ше в Правосла́вії і благоче́стії // і спасе́ть ду́ші на́ші."]},{"h":"Кондак, глас 4","ps":["Воі́стину ди́вен Бог во святи́х Свої́х, / пу́стинь О́птину я́коже вертогра́д ста́рчества яви́вий, / іді́же богопросвеще́нії отці́, / та́йная се́рдця челове́чеського ві́дуще, / наро́да Бо́жия печа́льници до́блії яви́шася: / сі́ї бо на путь покая́нія гріхо́м отягоще́нния наста́виша, / во ві́рі коле́блющіяся сві́том Христо́ва уче́нія просвіти́ша / і Бо́жії прему́дрости научи́ша, / стра́ждующим і немощни́м спострада́ша і ісціле́нія дарова́ша. / Ни́ні же, во сла́ві Бо́жії пребива́юще, // мо́ляться непреста́нно о душа́х на́ших."]},{"h":"Величання","ps":["Ублажа́єм вас, преподо́бнії отці́ на́ші ста́рці О́птинстії, і чтим святу́ю па́м'ять ва́шу, наста́вници мона́хов, і собесі́дниці а́нгелов."]}],"notes":[]},{"u":"Акафіст преподобному Симеону Стовпнику","e":"Akathist to our Venerable Father Symeon the Stylite","secs":[{"h":"Кондак 1","ps":["Ізбра́нному от младе́нчества світи́льнику ми́ра і ціли́телю неду́гов душе́вних і тіле́сних к преподо́бному отцю́ на́шему Симео́ну смире́нно притека́юще, я́ко могу́щему нас свободи́ти от страсте́й і вся́ких бід, із глубини́ душі́ принесе́м хвале́ніє і моли́тву, усе́рдно зову́ще:","Ра́дуйся, Симео́не, ди́вний столпниче і вели́кий чудотво́рче."]},{"h":"Ікос 1","ps":["А́нгел Храни́тель дан бисть тебі́ от Бо́га, єгда́ плод моли́тви усе́рдния дарова́н бил єси́ роди́телем твої́м. Той бі тя сохраня́я, па́че же в му́дрости духо́вній поуча́я, єгда́ снігосві́тлою оде́ждею оді́ялся єси́ при креще́нії твоє́м. Ми же, ві́дяще тя чу́днаго ізбра́нника Бо́жия би́ти, сія́ похвали́ тебі́, я́ко до́лжния, дерза́єм принести́:","Ра́дуйся, роди́телей твої́х плод моли́тви богодарова́нний.","Ра́дуйся, даро́в Свята́го Ду́ха во святі́м креще́нії сподо́бивийся.","Ра́дуйся, Бо́жия благода́ті сосу́де ізбра́нний.","Ра́дуйся, любве́ Бо́жия челові́ком явле́ніє.","Ра́дуйся, земні́й му́дрости ненаученний.","Ра́дуйся, небе́сною сугу́бо обогащенний.","Ра́дуйся, Ті́лом і Кро́вію Христо́вою та́їнственно обоженний.","Ра́дуйся, в моли́тві восхище́нний.","Ра́дуйся, Симео́не, ди́вний столпниче і вели́кий чудотво́рче."]},{"h":"Кондак 2","ps":["Ви́дя Госпо́дь смире́ніє і простоту́ се́рдця твоєго́, ізбра́ тя во ору́жіє Своє́, да посрами́ши лука́воє мудрова́ніє мудрецо́во ві́ка сего́, і от ове́ць о́тчих сотвори́ тя па́стиря ове́ць слове́сних стада́ Христо́ва, да ку́пно поєте́ Творцю́: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум твой імі́я а́лчущий і жа́ждущий пра́вди Христо́ви, не усумні́лся єси́ вопроси́ти честна́го ста́рця о словесі́х свята́го Єва́нгелія. І, поучи́вся єго́ богонаученних глаго́лов, в то́мже часі́ тве́рдо возжела́л єси́ оста́вити дом о́тчий і вся кра́сная ми́ра сего́ і ті́сним путе́м, веду́щим в живо́т ві́чний, поіти́. Сего́ ра́ди вопіє́м ті:","Ра́дуйся, во хра́мі пребива́ніє от ю́ности возлюби́вий.","Ра́дуйся, із до́ма о́тча ізше́дий.","Ра́дуйся, бегающих ми́ра покро́ве.","Ра́дуйся, богоугожде́нія о́бразе.","Ра́дуйся, благо́є і́го Христо́во с любо́вію восприя́вий.","Ра́дуйся, плоть я́ко мече́м посекий.","Ра́дуйся, заблу́ждших наставля́яй.","Ра́дуйся, до́брі жи́тельствующих утвержда́яй.","Ра́дуйся, Симео́не, ди́вний столпниче і вели́кий чудотво́рче."]},{"h":"Кондак 3","ps":["Открове́нієм Бо́жиїм бисть тебі́ во сні виді́ніє: основа́ніє зда́нію полага́я, ров копал єси́ і глас сли́шал єси́ трикра́ти, па́че углублятися, і, дости́гшу ті мно́гія глубини́, повелі́ ті Госпо́дь со всім усе́рдієм твої́м созида́ти. І сби́стся чу́дноє виді́ніє сіє́ над тобо́ю: глубино́ю смире́нія положи́л єси́ тве́рдоє основа́ніє доброді́телем всім, і́миже укра́шен, непреста́нно Го́споду взива́л єси́: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я жела́ніє крі́пкоє житія́ і́ночеськаго, ко єди́ній оби́телі прише́л єси́. Смире́нія же ра́ди сем дній без я́стія і питія́ пред врати́ єя́ пад на землі́ преби́л єси́, дерзнове́нія не іми́й в ту́ю вни́ти. Блаже́нний же ігу́мен тоя́ оби́телі, прови́дя тя Бо́жия ізбра́нника би́ти, минувшими де́ньми іспита́ тя, я́ко хо́щеши Го́сподеві рабо́тати, і ли́ку бра́тії своєя́ сопричте. І ми всі почита́єм тя:","Ра́дуйся, і́стинний послу́шателю велі́ній Христо́вих.","Ра́дуйся, житію́ равноа́нгельному поревнова́вий.","Ра́дуйся, мир сей оста́вивий.","Ра́дуйся, житія́ по́стничеськаго пла́менні возжелі́вий.","Ра́дуйся, воздержа́нієм на стра́сті вооружи́вийся.","Ра́дуйся, до́брий во́їне Христо́в.","Ра́дуйся, во смире́нії на послуша́ніє себі́ покори́вий.","Ра́дуйся, тща́ніє ве́ліє к науче́нію монасти́рському яви́вий.","Ра́дуйся, Симео́не, ди́вний столпниче і вели́кий чудотво́рче."]},{"h":"Кондак 4","ps":["Бу́рю страсте́й утиша́я, я́ко ягнець кро́ток отце́в духо́вних всегда́ послу́шал єси́ і, за смире́ніє твоє́, єще́ юн сий, о́браза а́нгельськаго сподо́бился єси́, в не́мже воздержа́ніє і труди́ усугубляя, плоть умерщвля́л єси́, ду́шу спаса́я, і в глубині́ се́рдця взива́я Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́ша ігу́мен бра́тію пові́дающу, я́ко смрад от тебе́ ісхо́дить і че́рви спадають с тілесе́ твоєго́, вопроси́ тя, чесого́ ра́ди бисть ті та́ко. Ти же, главу́ преклони́вий, в молча́нії предстоя́л єси́. Тогда́ взя́ша одужду с тебі́ і кро́вію обагре́нноє ті́ло твоє́ узрі́ша, с ве́рвієм жестким вонзе́нним в него́. Со у́жасом мно́гим страда́нія твоя́ помишля́я і ми си́це зове́м ті:","Ра́дуйся, Свята́го Ду́ха жили́ще освяще́нноє.","Ра́дуйся, о́браз Бо́жий не помрачи́вий в себі́.","Ра́дуйся, терпі́нієм Іовлем бра́тію удиви́вий.","Ра́дуйся, вели́коє му́жество в себі́ яви́вий.","Ра́дуйся, ревни́телю і́стини.","Ра́дуйся, лампа́до єле́я благово́ннаго.","Ра́дуйся, растлі́нния хра́ми душ на́ших обновля́яй.","Ра́дуйся, куми́ри мудрова́нія на́шего низлага́яй.","Ра́дуйся, Симео́не, ди́вний столпниче і вели́кий чудотво́рче."]},{"h":"Кондак 5","ps":["Благода́тною си́лою укріпля́єм, но́вия по́двиги во умерщленіє пло́ті твоєя́ поне́сл єси́. Стра́ха же ра́ди, я́ко і бра́тія, подража́юще тебі́, по́двиги не по ра́зуму воспри́йметь, повелі́ ті ігу́мен отити о них. Ти же, незло́бив, во́лю єго́ ісполня́я, в пусти́ні в кладезі безво́днім всели́лся єси́, па́ки і та́мо воспіва́л Христу́ Бо́гу піснь: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дя блаже́нний ігу́мен Тимофе́й виді́ніє во сні, я́ко мно́жество наро́да оби́тель єго́ обстої́ть і о рабі́ Бо́жиєм Симео́не вопроша́ють, у́жасом одержи́м бі і, воспряну́в от сна, бра́тії пові́да сіє́. А́біє же ку́пно с ни́ми і́де в пусти́ню і воззва́ тя. Почита́юще по́двиги твоя́, і ми по до́лгу велича́єм тя:","Ра́дуйся, си́лу ду́ха Іо́сифа яви́вий.","Ра́дуйся, ве́лія по́двиги Христа́ ра́ди соверши́вий.","Ра́дуйся, Крест Христо́в безро́потно понеси́й.","Ра́дуйся, Це́ркві украше́ніє.","Ра́дуйся, пра́вди Бо́жия ди́вний служи́телю.","Ра́дуйся, до́брий ко́рмчий корабля́ Ісу́сова.","Ра́дуйся, пра́вило ві́ри благочести́вия.","Ра́дуйся, о́бразе кро́тости духо́вния.","Ра́дуйся, Симео́не, ди́вний столпниче і вели́кий чудотво́рче."]},{"h":"Кондак 6","ps":["Пропові́дник сло́ва Бо́жия єпи́скоп Васс по во́лі Бо́жієй при́йде, єгда́ в келії пусти́нній водвори́лся єси́. Ве́лію ре́вность о Мойсе́ї і Ілії́ показа́в, четиредесятидневнаго поста́ возжелі́л єси́. Да не приобщи́шися бра́шна во вре́м'я сіє́, невходну келію твою́ святи́теля устро́їти моля́ше, є́же і сотвори́, і отиде, Го́сподеві поя́: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́, преподо́бне, чу́дним воздержа́нієм твої́м, єгда́ прешедшим днем поста́ твоєго́ обрі́те тя святи́тель Бо́жий я́ко ме́ртва, на землі́ лежа́ща, воздви́же тя і Та́їн безсме́ртних Христо́вих прича́стія сподо́би. Посе́м мно́гим бра́тіям пові́дав о ди́внім по́двизі твоє́м, научи́ їх прославля́ти Го́спода, ди́вная діла́ во святи́х Свої́х явля́юща, і тебі́, уго́днику Єго́, воспіва́ти сицева́я:","Ра́дуйся, земни́й путь твой по стопа́м Христо́вим ше́ствовавий.","Ра́дуйся, посто́м Мойсе́ю і Ілії́ подража́вий.","Ра́дуйся, на Го́спода упова́ніє твоє́ возложи́вий.","Ра́дуйся, во упова́нії сем пи́щі і питія́ не приобщи́вийся.","Ра́дуйся, я́ко сві́том боже́ственним озарялся єси́.","Ра́дуйся, я́ко і нас, ві́рних, моли́твами твої́ми укріпля́єши.","Ра́дуйся, я́ко воздержа́нієм безпло́тним уподо́бился єси́.","Ра́дуйся, тім, я́ко ору́жієм духо́вним, неви́димих враго́в побіди́л єси́.","Ра́дуйся, Симео́не, ди́вний столпниче і вели́кий чудотво́рче."]},{"h":"Кондак 7","ps":["Хотя́ по́двиги твоя́ па́че усугу́бити, я́ко на лі́ствицю возводя́щую к небесі́, на верх гори́ возше́л єси́: да не сойдеши отту́ду, око́вами себе́ на ней утверди́, глаго́лов же святи́теля Меле́тія послу́шав, не плоть, но ра́зум в Христо́во послуша́ніє пліни́в, до конця́ живота́ своєго́ взива́л єси́: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вая Вифесда́ яви́ся гора́, на не́йже подвиза́лся єси́, препободне. Не то́кмо єди́ною в лі́то і пе́рвіє входящим ісціле́нія на той подавашася, но і всегда́ і всім в біда́х, болі́зніх і ско́рбіх су́щим і с наде́ждою к Бо́гу притекающим блага́я по́мощ твоя́ даровашеся, і всі возвраща́хуся, сла́в'я Бо́га, і тя, уго́дника Єго́ велича́ху, зову́ще:","Ра́дуйся, свіще́, Боже́ственним пла́менем возже́нная.","Ра́дуйся, світи́льниче горя́й і світя́й.","Ра́дуйся, ціли́телю болі́зней душе́вних.","Ра́дуйся, врачу́ неду́гов тіле́сних.","Ра́дуйся, пита́телю а́лчущих пра́вди.","Ра́дуйся, істо́чниче жа́ждущим і́стини.","Ра́дуйся, моли́твенниче о душа́х на́ших.","Ра́дуйся, хода́таю нам і благ земни́х.","Ра́дуйся, Симео́не, ди́вний столпниче і вели́кий чудотво́рче."]},{"h":"Кондак 8","ps":["Стра́нно житіє́ своє́ сотвори́л єси́, блаже́нне, єгда́ ви́дя наро́д мног, грядущ к тебі́, уразумі́, я́ко чтуть і прославля́ють тя. Сла́ви убіга́я, смире́ніє же возлюби́в, на столпі́ висо́цім пребива́ти благоволи́л єси́ і, я́ко по степе́нем лі́ствиці к небе́сній висоті́ восходя́, і мраз, і дождь, і зной палящий претерпіва́я, Го́сподеві непреста́нно піл єси́: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь іспо́лнился єси́ послуша́нія, іспиту́ющим тя святи́м отце́м пусти́нником: повину́яся бо велі́нію їх, я́ко Бо́жию, потща́лся єси́ сни́ти со столпа́ твоєго́ на зе́млю, є́же і ви́дяще ті́ї, уразумі́ша, я́ко от Бо́га ді́ло твоє́, і рі́ша, да пребу́деши на столпі́ твоє́м невозбра́нно. Тогда́ враг ро́да челові́ча уми́сли іскуси́ти тя: во о́бразі а́нгела сві́тла предста́ ті, ти же на мгнове́ніє не уразумі́л єси́, блаже́нне, ле́сти вра́жия, оба́че зна́менієм честна́го Креста́ побіди́л єси́ того́ кова́рство. По́сліжде покая́ніє ве́ліє Го́споду прине́сл єси́, сему́ же і ми поучи́вшеся, хва́лим тя си́це:","Ра́дуйся, стрі́ли лука́ваго разжже́нния отрази́вий.","Ра́дуйся, кова́рство врага́ побіди́вий.","Ра́дуйся, си́лою кре́стною вооружи́вийся.","Ра́дуйся, лож огне́м і́стини попали́вий.","Ра́дуйся, моли́твою, я́ко мече́м, вооруженний.","Ра́дуйся, шле́мом спасе́нія вінча́нний.","Ра́дуйся, сугу́боє покая́ніє Бо́гу принеси́й.","Ра́дуйся, на Бо́жиє милосе́рдіє наде́жду возложи́вий.","Ра́дуйся, Симео́не, ди́вний столпниче і вели́кий чудотво́рче."]},{"h":"Кондак 9","ps":["Вся́каго грі́шника ка́ющагося приє́мляй Госпо́дь і твоє́ покая́ніє прия́т, і па́ки просла́ви тя. Дия́вол же, по́двига твоєго́ не терп'я́ще, я́звою лю́тою порази́ тя, і бисть в но́зі твоє́й лю́тий гной с черв'ями. По мно́зім вре́мені уві́дів о тебі́ ма́ти твоя́, при́йде ко столпу́ твоєму́ і пла́кася го́рко. Ти же, блаже́нне, на во́лю Госпо́дню упова́я, в бу́дущем ві́ці усрі́сти тя єй обіща́л єси́ і, над предавшею дух єя́ в ру́ці Госпо́дні, моли́тву сотвори́в, Го́сподеві воспі́л єси́: Аллилу́я."]},{"h":"Ікос 9","ps":["Ві́тіії суєму́дреннії не возмо́гуть із'яснити си́лу чудотворе́ній твої́х, ї́хже в сла́ву Бо́жию і чу́дним і́менем Госпо́днім соверша́л єси́. Води́ не імі́вшу мі́сту тому́, моли́твою твоє́ю, свя́те, земля́ потрясе́ся і во́ду оби́льно даде́. Жена́ ні́кая, змію́ ма́лую во воді́ во чре́во своє́ приє́мшая, водо́ю твоє́ю напоі́вшися, ісцілі́ а́біє. І і́ни мно́зі ісціліва́ху у столпа́ твоєго́ святи́ми твої́ми моли́твами. Лю́діє же, ви́дяще ве́лія чудеса́ Бо́жия, с ра́достію прославля́ху тя:","Ра́дуйся, Небе́снаго Царя́ ра́бе благи́й і ві́рний.","Ра́дуйся, прия́тий от Него́ тала́нт усугубивий.","Ра́дуйся, житіє́м твої́м небеса́ возвесели́вий.","Ра́дуйся, чудеси́ вселе́нную удиви́вий.","Ра́дуйся, помо́щниче наш і моли́твенниче.","Ра́дуйся, от іскуше́ній вра́жиїх защи́тниче.","Ра́дуйся, я́ко тобо́ю стра́сті на́ша утоля́ються.","Ра́дуйся, я́ко тобо́ю блага́я жела́нія на́ша ісполня́ються.","Ра́дуйся, Симео́не, ди́вний столпниче і вели́кий чудотво́рче."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ грі́шния і к покая́нію призва́ти, послі́довал єси́ стопа́м Го́спода на́шего Ісу́са Христа́ і прибі́гшаго под кров твой разбо́йника Іонафа́на хотя́щим уби́ти єго́ не пре́дал єси́, но после ве́лія єго́ покая́нія, отити єму́ с ми́ром ко Го́споду умоли́л єси́, даби́ блаже́нства ра́йськаго улучи́в, во ві́чності восхва́лить Всеще́драго Человіколю́бця Бо́га благодарственною пі́снію: Аллилу́я."]},{"h":"Ікос 10","ps":["Царя́ Небе́снаго і Го́спода благи́й раб і ві́рний служи́тель бил єси́, ча́дом же твої́м духо́вним - оте́ць і наста́вник многоми́лостивий: на єди́нім мі́сті, на столпі́ тебі́ обита́ющу, мно́жество наро́да, і ві́рних, і неві́рних, к тебі́ прихожда́ху, і всім всяк помо́щник бил єси́, вся́кия болі́зні душе́вния і тіле́сния врачу́я, найпа́че же неві́рующія сві́том Христо́ва Єва́нгелія просвіща́л єси́, я́ко да креще́ннії во і́м'я Пресвяти́я Тро́йці, Го́спода превознесуть і тебі́, до́брому па́стирю своєму́, воззову́ть:","Ра́дуйся, зерца́ло Трисія́ннаго Сві́та.","Ра́дуйся, небе́снаго озаре́нія іспо́лненний.","Ра́дуйся, от бога́тства ду́ха бли́жнія просвіща́яй.","Ра́дуйся, стра́ху Бо́жию науча́яй.","Ра́дуйся, во́лі Госпо́дней безропотний ісполни́телю.","Ра́дуйся, о сла́ві Єго́ ревни́телю.","Ра́дуйся, па́стирю наш до́брий.","Ра́дуйся, отці́ ми́лостивий і кро́ткий.","Ра́дуйся, Симео́не, ди́вний столпниче і вели́кий чудотво́рче."]},{"h":"Кондак 11","ps":["Пі́ніє возлю́бленному Христу́ в житії́ твоє́м принося́, да́ра проро́чества сподо́бился єси́, гряду́щую засуху, глад і мор предвозвіща́я, наше́ствіє неві́рних предре́кл єси́ і мно́гими слеза́ми і те́плою моли́твою Го́спода уми́лостивил єси́, да отврати́ть гнів Свой, пра́ведно дви́жимий, і не попу́стить язи́ком побіди́ти христия́ни, принося́щих покая́ніє і благодаря́щих Го́спода за Єго́ ве́лію ми́лость і непреста́нно пою́щих Єму́: Аллилу́я."]},{"h":"Ікос 11","ps":["Сві́та небе́снаго сосу́де ізбра́нний показа́лся єси́, єгда́ приспі́ час твой от ми́ра сего́ в селе́нія возлю́бленная і жела́ємая прейти́. О блаже́нній кончи́ні твоє́й та́ко учени́к твой Анто́ній повіству́єть: «Во єди́н день, в п'ято́к, по дев'я́том часі́, ожидающим нам єго́ поуче́нія і благослове́нія, не призрі́л он на нас со столпа́. Та́кожде і в суббо́ту, і в неді́лю. І устраши́лся аз, і взидо́х на столп, і узрі́х преподо́бнаго со главо́ю поникшею до́лу і ру́ці на пе́рсіх. Мня́ху, я́ко моли́тву ді́єть, умолча́х аз, посліди́ же реко́х: «Благослови́ нас, о́тче!» Он же не отвіща́. Тогда́ поми́слих, я́ко а́ще ко Го́споду отиде преподо́бний оте́ць, і уразумі́х, я́ко єсть та́ко, і воспла́кахся го́рко, і, приступи́в, лобиза́х єго́, глаго́ля: «На кого́ оставля́єши нас, о́тче?» І ми про́сим тя: і нас грі́шних не оставля́й твої́ми благоприя́тними ко Го́споду моли́твами, із глубини́ душі́ зову́щих ті:","Ра́дуйся, от младе́нчества всего́ себ'я́ Го́сподеві преда́вий.","Ра́дуйся, за́повіді Бо́га, я́ко благо́є сокро́вище в се́рдці своє́ приє́мий.","Ра́дуйся, благода́тію райською облагоуханний.","Ра́дуйся, сві́том моли́тви просвіще́нний.","Ра́дуйся, во Христа́ облече́нний.","Ра́дуйся, ри́зою нетлі́нія украше́нний.","Ра́дуйся, ко Го́споду вся помишле́нія твоя́ обрати́вий.","Ра́дуйся, бли́жніх я́коже себі́ возлюби́вий.","Ра́дуйся, Симео́не, ди́вний столпниче і вели́кий чудотво́рче."]},{"h":"Кондак 12","ps":["Благода́ті дар іспроси́ у Го́спода, о́тче, теб'я́ ві́рно хваляшим; воньми́ воздиха́нієм на́шим, і слез на́ших не пре́зри, і не оста́ви нас, я́коже обіща́лся єси́ не оставля́ти ні столпа́ твоєго́, ні гори́, тобо́ю ізбра́нния, во благодія́ніє прибегающим к тебі́ челові́ком, под кро́вом твої́м сохраняємим, Го́сподеві же пою́щим: Аллилу́я."]},{"h":"Ікос 12","ps":["Воспіва́я житіє́ твоє́, богоблаже́нне о́тче, прославля́єм Бо́га, і, я́коже на погребе́ніє твоє́ стеко́шася ко гро́бу твоєму́ святи́телі, і па́стирі, і мирсті́ї со слеза́ми і моли́тви мно́гими, свіщи́ і фимія́м нося́ще, та́ко і ми, соше́дшеся в день па́м'яті твоєя́, усе́рдния хвали́ і моле́нія прино́сим ті:","Ра́дуйся, от ю́ности ми́ру уме́рий.","Ра́дуйся, благо́є і́го Христо́во взе́мий.","Ра́дуйся, із темни́ці тілесе́ к ві́чному житію́ ра́достно ізше́дий.","Ра́дуйся, лицезрі́нієм Боже́ственнаго сві́та наслаждающийся.","Ра́дуйся, я́ко при́сно Пресвяті́й Тро́йце предстої́ши.","Ра́дуйся, я́ко непреста́нно моли́тви о нас возсила́єши.","Ра́дуйся, цільбоно́сния мо́щі нам оста́вивий.","Ра́дуйся, ро́да христия́нськаго помо́щниче.","Ра́дуйся, Симео́не, ди́вний столпниче і вели́кий чудотво́рче."]},{"h":"Кондак 13","ps":["О вели́кий і преди́вний уго́дниче Бо́жий, преподо́бне о́тче наш Симео́не! Ни́ні престо́лу Бо́жию предстої́ши і проше́нія на́ша Го́споду прино́сиши, і сія́ ма́лая моле́нія от нас грі́шних прийми́, і, я́коже не отри́нул єси́ разбо́йника, прибі́гшаго к твоєму́ столпу́, но і от земни́х бід ізба́вил єси́ того́, і вождь бил єси́ Єму́ в Ца́рство Небе́сноє, та́ко і нас, грі́шних, не оста́ви твої́м заступле́нієм, но і во вре́менній жи́зні сей помога́й нам, і в бу́дущей небе́сних оби́телей моли́твами твої́ми дости́гнути сподо́би, іді́же с тобо́ю Христу́, Спаси́телю на́шему, воззове́м: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгел Храни́тель дан бисть тебі́ от Бо́га, єгда́ плод моли́тви усе́рдния дарова́н бил єси́ роди́телем твої́м. Той бі тя сохраня́я, па́че же в му́дрости духо́вній поуча́я, єгда́ снігосві́тлою оде́ждею оді́ялся єси́ при креще́нії твоє́м. Ми же, ві́дяще тя чу́днаго ізбра́нника Бо́жия би́ти, сія́ похвали́ тебі́, я́ко до́лжния, дерза́єм принести́:","Ра́дуйся, роди́телей твої́х плод моли́тви богодарова́нний.","Ра́дуйся, даро́в Свята́го Ду́ха во святі́м креще́нії сподо́бивийся.","Ра́дуйся, Бо́жия благода́ті сосу́де ізбра́нний.","Ра́дуйся, любве́ Бо́жия челові́ком явле́ніє.","Ра́дуйся, земні́й му́дрости ненаученний.","Ра́дуйся, небе́сною сугу́бо обогащенний.","Ра́дуйся, Ті́лом і Кро́вію Христо́вою та́їнственно обоженний.","Ра́дуйся, в моли́тві восхище́нний.","Ра́дуйся, Симео́не, ди́вний столпниче і вели́кий чудотво́рче."]},{"h":"Кондак 1","ps":["Ізбра́нному от младе́нчества світи́льнику ми́ра і ціли́телю неду́гов душе́вних і тіле́сних к преподо́бному отцю́ на́шему Симео́ну смире́нно притека́юще, я́ко могу́щему нас свободи́ти от страсте́й і вся́ких бід, із глубини́ душі́ принесе́м хвале́ніє і моли́тву, усе́рдно зову́ще:","Ра́дуйся, Симео́не, ди́вний столпниче і вели́кий чудотво́рче."]},{"h":"Молитва","ps":["О святи́й і вели́кий уго́дниче Бо́жий Симео́не! По́двигом до́брим подвиза́вся на землі́, восприя́л єси́ на небесі́х віне́ць пра́вди, єго́же угото́вал єсть Госпо́дь всім лю́б'ящим Єго́. Ті́мже, взира́юще на святи́й твой о́браз, ра́дуємся о пресла́внім сконча́нії жи́тельства твоєго́ і чтим святу́ю па́м'ять твою́. Ти же, предстоя́ Престо́лу Бо́жию, прийми́ моле́нія на́ша і ко Всемилостивому́ Бо́гу принеси́, о є́же прости́ти нам вся́коє прегріше́ніє і по́мощі нам ста́ти проти́ву ко́знем дия́вольским, да ізба́вльшеся от скорбе́й, болі́зней, бід і напа́стей і вся́каго зла, благоче́стно і пра́ведно поживе́м в ни́нішнем ві́ці і сподо́бимся предста́тельством твої́м, а́ще і недосто́йни єсьми́, ви́діти блага́я на землі́ живи́х, сла́в'яще Єди́наго во святи́х Свої́х сла́вимаго Бо́га, Отця́ і Си́на і Свята́го Ду́ха, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 1","ps":["Терпі́нія столп бил єси́, / ревнова́вий пра́отцем, преподо́бне: / І́ову во страстеіх, Іо́сифу во іскуше́ніїх, / і безпло́тних жи́тельству, сий в тілесі́, / Симео́не о́тче наш, // моли́ Христа́ Бо́га, спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 2","ps":["Ви́шніх іща́й, ви́шнім совокупля́яйся, / і колесни́цю о́гненную столп соді́лавий: / тім собесі́дник А́нгелом бил єси́, преподо́бне, / с ни́ми Христу́ Бо́гу // моля́ся непреста́нно о всіх нас."]},{"h":"Величання","ps":["Ублажа́єм тя, / преподо́бне о́тче Симео́не, / і чтим святу́ю па́м'ять твою́, / наста́вниче мона́хов / і собесі́дниче А́нгелов."]}],"notes":[]},{"u":"Акафіст святій преподобномучениці великій княгині Єлисаветі","e":"Akathist to the Holy Venerable Martyr Grand Duchess Elizabeth","secs":[{"h":"Кондак 1","ps":["Ізбра́нная от ро́да держа́внаго дщер Це́ркве Ру́ськия, любо́вію ізоби́льною і милосе́рдієм Бо́гу і бли́жнім до́брі послужи́вшая, за ві́ру во Христа́ Го́спода на́шего ду́шу свою́ положи́вшая і вінце́м сла́ви Христо́ви украше́нная, восхваля́юще по́двиги і страда́нія твоя́, с любо́вію воспіва́єм ті си́це:","Ра́дуйся, благові́рная княги́не Єлисаве́то, преподобному́ченице достосла́вная."]},{"h":"Ікос 1","ps":["А́нгельським попече́нієм храни́мая і ма́терію твоє́ю благоче́стію поуча́ємая, в труді́х, моли́твах і ми́лостині ізмла́да о́браз доброді́тельнаго житія́ яви́ла єси́. По кончи́ні же ма́тере твоєя́ і бли́жніх сро́дников кре́стний путь, Го́сподем запові́данний, уразумі́ла єси́. Ті́мже, див'я́щеся таково́му от ю́ности твоєму́ ізбра́нію, со умиле́нієм взива́єм ті:","Ра́дуйся, от ю́ности Христа́ возлюби́вшая;","ра́дуйся, во мла́дости нача́тки благоче́стія приі́мшая.","Ра́дуйся, Христо́ва а́гнице ізбра́нная;","ра́дуйся, страх Бо́жий в душе́ восприя́вшая.","Ра́дуйся, доброді́телі ма́тере твоєя́ насле́дствовавшая;","ра́дуйся, трудолю́бію і милосе́рдію є́ю науче́нная.","Ра́дуйся, се́рдцем в Бо́зі утвержде́нная;","ра́дуйся, с ві́рою і упова́нієм крест твой поне́сшая.","Ра́дуйся, землі́ оте́чества твоєго́ цві́те благоуха́нний;","ра́дуйся, чистото́ю жи́зні твоєя́ Небеса́ возвесели́вшая.","Ра́дуйся, на служе́ніє стра́ждущим Бо́гом ізбра́нная;","ра́дуйся, пред Го́сподем о нас те́плая моли́твеннице.","Ра́дуйся, благові́рная княги́не Єлисаве́то, преподобному́ченице достосла́вная."]},{"h":"Кондак 2","ps":["Ви́ді Госпо́дь благо́є се́рдця твоєго́ ізволе́ніє, я́ко возжелі́ла єси́ житіє́ проводи́ти во благоче́стії і чистоті́, к небе́сній красоті́ о́чі се́рдця твоєго́ устремля́ющи і любо́в к Бо́гу в себі́ возгрева́ющи. Моли́твами твої́ми і на́ша сердця́ то́ю же любо́вію просвіти́, да с тобо́ю воспої́м Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум просвіще́н іму́щи і все упова́ніє на Бо́га возложи́вши, не убоя́лася єси́, свята́я Єлисаве́то, оста́вити дом отця́ твоєго́ і в но́воє Оте́чество всели́тися, єгда́ бра́ком сочета́лася єси́ с россі́йським вели́ким кня́зем Се́ргиєм. Ми же с любо́вію взива́єм ті си́це:","Ра́дуйся, от За́пада на Восто́к прише́дшая;","ра́дуйся, в но́вім Оте́чествії єдине́ніє с Це́рковію обрі́тшая.","Ра́дуйся, за́повіді Госпо́дні іспо́лнити возжеле́вшая;","ра́дуйся, в сердця́х на́ших по Бо́зі ревнова́ніє воспламеня́ющая.","Ра́дуйся, в супру́жестві цілому́дренні пожи́вшая;","ра́дуйся, в доброді́ланії нас наставля́ющая.","Ра́дуйся, благові́рная княги́не, страні́ на́шей ві́рно послужи́вшая;","ра́дуйся, супру́гу твоєму́ в ді́ліх благи́х му́драя помо́щнице.","Ра́дуйся, семе́йств благочести́вих покрови́тельнице;","ра́дуйся, матери́нською любо́вію нас согріва́ющая.","Ра́дуйся, красото́ю душе́вною і тіле́сною всіх удивля́ющая;","ра́дуйся, всего́ ми́ра христия́нськаго украше́ніє.","Ра́дуйся, благові́рная княги́не Єлисаве́то, преподобному́ченице достосла́вная."]},{"h":"Кондак 3","ps":["Си́лою Боже́ственния благода́ті ко спасе́нію умудре́нная, позна́ла єси́ ві́ру і́стинную, княги́не ми́лостивая Єлисаве́то. Ті́мже, во Святі́й Землі́ пребива́ющи і в жела́нії се́рдця своєго́ прия́ти Правосла́віє укріпи́вшися, воспі́ла єси́ просвіти́вшему тя Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́щи се́рдце, до́брій землі́ подо́бноє, ві́ру правосла́вную удо́б восприя́ла єси́, ті́мже Свята́го Миропома́занія і причаще́нія Святи́х Христо́вих Тайн в пра́здник Воскре́шенія пра́веднаго Ла́заря сподо́билася єси́. Ми же, сла́в'яще просвіще́ніє твоє́ благода́тію Свята́го Ду́ха, велича́єм тя:","Ра́дуйся, от заблужде́ній отре́кшаяся;","ра́дуйся, ві́ру правосла́вную приє́мшая.","Ра́дуйся, пома́занієм Свята́го Ду́ха запечатле́нная;","ра́дуйся, с Це́рковію і́стинною воссоєдине́нная.","Ра́дуйся, святі́й пра́ведній Єлисаве́ті тезоімени́тая;","ра́дуйся, в по́двизіх єй усе́рдно подража́вшая.","Ра́дуйся, синово́м За́пада путь к і́стинній ві́рі показу́ющая;","ра́дуйся, от благочести́вих люде́й россі́йських любо́вію почита́ємая.","Ра́дуйся, ми́лостивая ма́ти, ми́лость у Влади́ки і Го́спода обрі́тшая;","ра́дуйся, і о на́шем поми́лованії усе́рдно моля́щаяся.","Ра́дуйся, світ Боже́ственний в се́рдці своє́м носи́вшая;","ра́дуйся, тьму жи́зні на́шея сві́том Христо́вих за́повідей озаря́ющая.","Ра́дуйся, благові́рная княги́не Єлисаве́то, преподобному́ченице достосла́вная."]},{"h":"Кондак 4","ps":["Бу́ря зло́би врага́ ро́да челові́чеськаго не поколеба́ тя, свята́я, єгда́ благові́рний супру́г твой внеза́пную смерть от уби́йць злонра́вних восприя́т, єму́же сострада́ющи, ве́ліє му́жество і христия́нськую любо́в яви́ла єси́, о покая́нії же уби́йць моля́щися, твори́ла єси́ піснь: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавше росси́йстії лю́діє о убіє́нії супру́га твоєго́, моля́ху Бо́га, да укріпи́ть тя, свята́я Єлисаве́то, в несе́нії ско́рби сея́. Ти же, єва́нгельською любо́вію дви́жима, в темни́ці уби́йцю посіти́ла єси́, к покая́нію єго́ подвиза́ющи і моли́тви вознося́щи ко Го́споду о проще́нії єго́. Сего́ ра́ди прийми́ от нас, недосто́йних, похвали́ сія́:","Ра́дуйся, за́повідь Христо́ву о любві́ ко враго́м іспо́лнившая;","ра́дуйся, уби́йцю супру́га твоєго́ єва́нгельськи прости́вшая.","Ра́дуйся, мно́зі ско́рби і біди́ претерпі́вшая;","ра́дуйся, в ско́рбіх і печа́ліх нам помога́ющая.","Ра́дуйся, заблу́ждших на путь і́стини і покая́нія наставля́ющая;","ра́дуйся, о поми́лованії грі́шних те́плі хода́тайствующая.","Ра́дуйся, во тьмі печа́лей сві́том наде́жди нас озаря́ющая;","ра́дуйся, путево́дная звіздо́ всім спасе́нія ча́ющим.","Ра́дуйся, окамене́нния сердця́ на́ша во умиле́ніє приводя́щая;","ра́дуйся, о вся́кой ско́рби на́шей Христа́ умоля́ющая.","Ра́дуйся, зло́бу ми́ра добро́м побежда́вшая;","ра́дуйся, лю́дем россі́йським любо́в і́стинную показа́вшая.","Ра́дуйся, благові́рная княги́не Єлисаве́то, преподобному́ченице достосла́вная."]},{"h":"Кондак 5","ps":["Боготе́чная звізда́ яви́лася єси́ в землі́ Росси́йстій, свята́я Єлисаве́то, єгда́ бога́тство і сла́ву я́ко прах вміни́вши, в ру́ці Бо́жії жизнь свою́ предала́ єси́, Крест Госпо́день ви́ну пред очи́ма іму́щи. Ті́мже, моли́твою і ді́ли милосе́рдія Бо́гу угоди́вши, днесь в ра́дості Єму́ поє́ши: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше тя лю́діє богоспаса́ємаго гра́да Москви́ ди́вную устрої́тельницю оби́телі милосе́рдія, возра́довашася, я́ко мно́зі жени́, ді́ви і ста́риці росси́йстії обріто́ша зді ти́хоє і душеспаси́тельноє приста́нище, подража́юще святи́м жена́м-мироно́сицям Ма́рфі і Марі́ї в служе́нії Бо́гу і бли́жнім. Сего́ ра́ди, прославля́юще тя, глаго́лем си́це:","Ра́дуйся, среди́ сла́ви земни́я суєту́ мирська́го житія́ уразумі́вшая;","ра́дуйся, імі́ніє своє́ разда́вшая і нищету́ Христо́ву возлюби́вшая.","Ра́дуйся, град Москву́ оби́телію ди́вною украси́вшая;","ра́дуйся, благо́є і́го Христо́во на ра́мо восприї́мшая.","Ра́дуйся, служе́нію святи́х жен-мироно́сиць подража́вшая;","ра́дуйся, мно́гія же́ни во оби́тель милосе́рдія приве́дшая.","Ра́дуйся, ко спасе́нію сесте́р твої́х му́драя упра́вительнице;","ра́дуйся, оби́телі твоєя́ неуси́пная храни́тельнице.","Ра́дуйся, в по́двизіх тіле́сних і духо́вних нас укріпля́ющая;","ра́дуйся, путь от землі́ на Не́бо нам показу́ющая.","Ра́дуйся, світи́ло милосе́рдія, над гра́дом Москво́ю возше́дшеє;","ра́дуйся, всіх служа́щих бли́жнім покрови́тельнице.","Ра́дуйся, благові́рная княги́не Єлисаве́то, преподобному́ченице достосла́вная."]},{"h":"Кондак 6","ps":["Пропові́дниця любве́ Боже́ственния і милосе́рдія неістощи́маго била́ єси́ в землі́ на́шей, свята́я Єлисаве́то, благоче́стія ревни́тельнице, в сердця́х люде́й россі́йських любо́в ко Го́споду і милосе́рдіє к бра́тіям бе́дствующим возгрева́ющи. Ті́мже і ми, твої́м заві́том послі́дующе, вку́пі с си́рими і убо́гими Бо́гу воспої́м: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ла єси́ сві́том і́ночеськаго житія́ в страні́ Росси́йстій, преподо́бная ма́ти на́ша Єлисаве́то, в пості́ і моли́тві, в нощни́х бді́ніїх і стро́гом воздержа́нії пребива́ющи, благоче́стію і смире́нію се́стри оби́телі твоєя́ поуча́ла єси́. Ми же, тобо́ю на путь ті́сний по́двига духо́внаго наставля́ємі, ублажа́єм тя:","Ра́дуйся, путь равноа́нгельнаго житія́ ізбра́вшая;","ра́дуйся, в цілому́дрії чистоту́ се́рдця твоєго́ сохра́ньшая.","Ра́дуйся, в нестяжа́нії висоту́ ду́ха твоєго́ показа́вшая;","ра́дуйся, в послуша́нії Бо́гу і бли́жнім послужи́вшая.","Ра́дуйся, му́драя княги́не і і́нокине пречестна́я;","ра́дуйся, о́бразе жена́м христия́нським.","Ра́дуйся, посто́м, бді́нієм і непреста́нними моли́твами Бо́гу угоди́вшая;","ра́дуйся, от сна гріхо́внаго ду́ші на́ша пробужда́ющая.","Ра́дуйся, ко ісполне́нію за́повіді о любві́ к Бо́гу і бли́жнім всіх наставля́ющая;","ра́дуйся, моли́тві те́плой нас науча́ющая.","Ра́дуйся, наста́внице і́нокиням і собесі́днице а́нгелом;","ра́дуйся, в со́нмі преподо́бних жен на Небесі́ просла́вленная.","Ра́дуйся, благові́рная княги́не Єлисаве́то, преподобному́ченице достосла́вная."]},{"h":"Кондак 7","ps":["Хотя́щи во́лю Госпо́дню твори́ти, свята́я Єлисаве́то, на вся́кий час свою́ во́лю отсека́ла єси́, к сові́ту пусти́нних ста́рцев Гавриї́ла і Алексі́я притека́ющи і і́ни му́жи духоно́сния вопроша́ющи, ї́хже му́дрими наставле́нії житіє́ во оби́телі милосе́рдія до́брі устроя́ла єси́, непреста́нно с се́страми взива́ющи Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́воє чу́до показа́ Госпо́дь, єгда́ дарова́ ті, свята́я Єлисаве́то, благода́ть і си́лу немощни́я ісціля́ти, безнаде́жния утіша́ти, заблу́ждшия вразумля́ти. Ти же, облегче́ніє і отра́ду с любо́вію подаю́щи, си́рим, забве́ним і немощни́м смире́нно послужи́ла єси́. Ті́мже і нас, убо́гих, твоє́ю моли́твою от страсте́й гріхо́вних ісціли́ і бу́ди нам ко спасе́нію управи́тельниця, да благода́рственно воспоє́м ті:","Ра́дуйся, в послуша́нії духо́вним отце́м і вели́ким ста́рцем пожи́вшая;","ра́дуйся, Вели́кая Ма́тушка людьми́ россі́йськими нарече́нная.","Ра́дуйся, дар немощни́я ду́ші врачева́ти от Бо́га стяжа́вшая;","ра́дуйся, боля́щия от одра́ болі́зні возставля́ющая.","Ра́дуйся, вдови́ць і сиро́т благосе́рдая попечи́тельнице;","ра́дуйся, а́лчущих пита́тельнице і су́щим в біда́х ско́рая засту́пнице.","Ра́дуйся, всі́ми презрі́нних і отве́рженних не оставля́ющая;","ра́дуйся, мно́гія ду́ші от тьми гріхо́вния і поги́белі спаса́ющая.","Ра́дуйся, унива́ющим в ско́рбіх і обстоя́ніїх му́драя уті́шительнице;","ра́дуйся, і нас, удруче́нних болі́зньми і немощми́, укріпля́ющая.","Ра́дуйся, ка́ющимся грі́шником пред Го́сподем предста́тельнице;","ра́дуйся, лю́дем россі́йським богодарова́нная помо́щнице.","Ра́дуйся, благові́рная княги́не Єлисаве́то, преподобному́ченице достосла́вная."]},{"h":"Кондак 8","ps":["Стра́нноє і стра́шноє виді́ніє яви́ Госпо́дь духовнику́ оби́телі милосе́рдія ієре́ю Митрофа́ну, ти же, о свята́я ма́ти, сіє́ виді́ніє із'ясня́ющи, прорекла́ єси́, я́ко ве́ліє і гро́зноє іспита́ніє гряде́ть на Це́рков Ру́ськую і держа́ву на́шу: святи́нь поруга́ніє, брань братоуби́йственная, сму́та ве́лія, кончи́на му́ченичеськая семе́йства ца́рськаго; но поми́луєть Бог Россі́ю по моли́твам святи́х єя́, с ни́миже ти ни́ні воспіва́єши Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Вся благода́тію Боже́ственною просвіща́єма, свята́я Єлисаве́то, ми́сленнима очи́ма гні́вноє посіще́ніє Бо́жиє страни́ на́шея зрі́ла єси́ і проро́чеськи віща́ла єси́, я́ко мно́зі му́ченици і іспові́дниці в землі́ Ру́сстій возсія́ють. Ті́мже все упова́ніє на Бо́жию Ма́тер возложи́ти лю́ди росси́йстії призива́ла єси́, ві́рующи, я́ко моли́твами Єя́ устро́їться і благослови́ться земля́ на́ша. Ми же, ві́дуще прорече́нія твоєго́ о судьбі́ отчи́зни на́шея сбитіє́, ублажа́єм тя си́це:","Ра́дуйся, храм Покро́ва Пресвяти́я Богоро́диці во оби́телі воздви́гшая;","ра́дуйся, в ру́ці Пречи́стій Ма́тері оби́тель твою́ преда́вшая.","Ра́дуйся, хра́мов святи́х і благолі́пних устрої́тельнице;","ра́дуйся, к Богоро́диці неуси́пная моли́твеннице.","Ра́дуйся, хра́ми Бо́жії сосу́дами і ри́зами благоукраси́вшая;","ра́дуйся, я́ко се́рдце твоє́ оби́телію Свята́го Ду́ха соді́лася.","Ра́дуйся, житіє́м свої́м Го́споду і Ма́тері Єго́ ві́рно послужи́вшая;","ра́дуйся, все упова́ніє на Бо́га возлага́ти нас науча́ющая.","Ра́дуйся, кро́тость, тишину́ і мир сердця́м на́шим подаю́щая;","ра́дуйся, благода́тними да́ри сві́тло украше́нная.","Ра́дуйся, му́жественні ско́рби і клевету́ претерпі́вшая;","ра́дуйся, себі́ в же́ртву Бо́гу угото́вившая.","Ра́дуйся, благові́рная княги́не Єлисаве́то, преподобному́ченице достосла́вная."]},{"h":"Кондак 9","ps":["Вся любо́вію к Бо́гу пламене́ющи, свята́я Єлисаве́то, не убоя́лася єси́, єгда́ прийдо́ша во оби́тель твою́ лю́діє безбо́жнії, хотя́щії суд непра́веден над тобо́ю соверши́ти. Ти же, Го́сподом сохраня́єма, сме́рті тогда́ ізбі́гла єси́, о вразумле́нії і просвіще́ніі неразу́мних і заблу́ждших моля́щися, Бо́гу же во благодаре́нії воспіва́ющи: Аллилу́я."]},{"h":"Ікос 9","ps":["Віті́й челові́чеських уста́ не возмо́гуть досто́йно восхвали́ти крі́пость любве́ твоєя́ во дні бід і напа́стей вели́ких, обише́дших Оте́чество на́ше, єгда́ не восхоті́ла єси́ поки́нути Россі́ю і оби́тель, тобо́ю созда́нную, се́стри тоя́ за ві́ру правосла́вную да́же до сме́рти стоя́ти увіщава́ющи. Ми же с любо́вію восхваля́єм тя:","Ра́дуйся, зе́млю на́шу возлюби́вшая;","ра́дуйся, от люде́й правосла́вних с любо́вію прославля́ємая.","Ра́дуйся, щито́м ві́ри огражда́тися нас науча́ющая;","ра́дуйся, жела́ніє кре́стним путе́м слі́довати в нас укріпля́ющая.","Ра́дуйся, от ро́ва поги́белі мно́гія спа́сшая;","ра́дуйся, оби́телі твоє́й і гра́ду Москві́ покро́ве і защи́тнице.","Ра́дуйся, се́стри оби́телі милосе́рдія во ві́рі і наде́жді утверди́вшая;","ра́дуйся, на по́двиг му́ченичества за Христа́ їх наста́вльшая.","Ра́дуйся, приобщи́тися страсте́м Христо́вим удосто́ївшаяся;","ра́дуйся, в по́двизі іспові́дничества ві́рния утвержда́ющая.","Ра́дуйся, любві́ же́ртвенней, ві́чній нас науча́ющая;","ра́дуйся, в ра́дость Го́спода твоєго́ вше́дшая.","Ра́дуйся, благові́рная княги́не Єлисаве́то, преподобному́ченице достосла́вная."]},{"h":"Кондак 10","ps":["Спаси́тельнаго по́двига і́щущи, свята́я Єлисаве́то, с ра́достію благодари́ла єси́ Бо́га, я́ко сподо́би тя понести́ крест Єго́. Ті́мже просія́ побі́дою ві́ра твоя́, єгда́, ко Голго́фі своє́й восходя́щи, непреста́нно возглаша́ла єси́: Сла́ва Бо́гу за вся! Умоли́, о ма́ти на́ша, да да́руєть нам Госпо́дь стяжа́ти му́дрость і си́лу за ві́ру пра́вую да́же до сме́рти стоя́ти і воспіва́ти Єму́ єди́ними усти́ і єди́ним се́рдцем: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ необори́мая і заступле́ніє страні́ на́шей дарова́ся свята́я іко́на Бо́жия Ма́тере Держа́вная, ю́же прия́ла єси́ во Оби́телі милосе́рдія, свята́я Єлисаве́то, я́ко зна́меніє побі́ди над миродержи́тели тьми ві́ка сего́. Сего́ ра́ди і ми, все упова́ніє на Держа́вную Влади́чицю возложи́вше, тебі́ я́ко і́стинную служи́тельницю і послу́шницю Пречи́стия Ма́тере Го́спода восхваля́єм:","Ра́дуйся, іспо́лненная благода́ті і си́ли Бо́жия;","ра́дуйся, ізбра́вшая благу́ю часть, я́же не оти́меться от тебе́.","Ра́дуйся, в кро́тости і смире́нії Бо́жієй Ма́тері подража́вшая;","ра́дуйся, я́ко му́драя єва́нгельськая ді́ва єле́й благода́ті собра́вшая.","Ра́дуйся, Пресвяти́я Богоро́диці благогові́йная служи́тельнице;","ра́дуйся, у Престо́ла Си́на Єя́ непреста́нная моли́твеннице.","Ра́дуйся, о́браз самоотверже́нія нам яви́вшая;","ра́дуйся, друг дру́га тяготи́ носи́ти науча́ющая.","Ра́дуйся, скорбми́ і слеза́ми в Ца́рство Небе́сноє возше́дшая;","ра́дуйся, любві́ і терпі́нію в страда́нії су́щих всіх науча́ющая.","Ра́дуйся, а́нгельськи на землі́ пожи́вшая;","ра́дуйся, на Небесі́ віне́ць сла́ви улучи́вшая.","Ра́дуйся, благові́рная княги́не Єлисаве́то, преподобному́ченице достосла́вная."]},{"h":"Кондак 11","ps":["Пі́ніє моле́бноє Бо́жієй Ма́тері возноси́ла єси́, свята́я Єлисаве́то, в день пра́зднованія І́верськия іко́ни Єя́, єгда́ взя́ша тя нечести́вії і в темни́цю вверго́ша. Ти же благодари́ла єси́ Христа́ Бо́га на́шего, да́вшаго тебі́ не то́чію є́же в Него́ ві́ровати, но і є́же по Нем страда́ти, в у́зах темни́чних воспіва́ющи Єму́: Аллилу́я."]},{"h":"Ікос 11","ps":["Світ Боже́ственний осія́ тя, страстоте́рпице свята́я княги́не Єлисаве́то, ку́пно с преподобному́ченицею Варва́рою, о Христі́ сестро́ю твоє́ю, і с про́чими страстоте́рпці імени́тими, єгда́ в глубо́кий ров низри́нуша вас нечести́вії. Ти же, ра́ни вели́каго кня́зя Іоа́нна об'язу́ющи і страда́нія бли́жніх облегча́ющи, воспіва́ла єси́ свяще́нная піснопі́нія, за убива́ющих си́це моля́щися: О́тче, отпусти́ їм, не ві́дять бо, что творя́ть. Уврачу́й і на́ших душ ра́ни, преподо́бная ма́ти, да с любо́вію воспоє́м ті:","Ра́дуйся, му́ченичеськую кончи́ну свою́ предуве́девшая;","ра́дуйся, страстоте́рпице великоімени́тая.","Ра́дуйся, Страсте́м Христо́вим приобщи́вшаяся;","ра́дуйся, си́лою Боже́ственною в страда́ніїх укрепля́ємая.","Ра́дуйся, за мучи́телей свої́х, Христу́ подража́ющи, моли́вшаяся;","ра́дуйся, до са́мия кончи́ни твоєя́ піснь Бо́гу воспева́вшая.","Ра́дуйся, кро́вію своє́ю зе́млю Ру́ськую ороси́вшая;","ра́дуйся, со́нму но́вих му́ченик сопричте́нная.","Ра́дуйся, я́ко ли́ку преподо́бних і пра́ведних жен приобщи́лася єси́;","ра́дуйся, святи́х благові́рних княги́нь землі́ Ру́ськия досто́йная сонасле́днице.","Ра́дуйся, же́ртво непоро́чная і благоприя́тная, Бо́гу принесе́нная;","ра́дуйся, со всі́ми святи́ми землі́ на́шея торжеству́ющая.","Ра́дуйся, благові́рная княги́не Єлисаве́то, преподобному́ченице достосла́вная."]},{"h":"Кондак 12","ps":["Благода́ть істоча́ють честні́ї мо́щі ва́ша, святи́я преподобному́ченици Єлисаве́то і Варва́ро, ї́хже от поруга́нія і безче́стія спа́сше, благочести́вії лю́діє із Россі́ї во святи́й град Ієрусали́м принесо́ша і во ві́си Гефсима́нийстій погребо́ша, іді́же мно́зії к ним приходя́ще, ублажа́ють вас, воспіва́юще Бо́гу, ди́вному во святи́х Свої́х: Аллилу́я."]},{"h":"Ікос 12","ps":["Сві́та небе́снаго і благоуха́нія чу́днаго храм святи́я мироно́сиці Марі́ї Магдали́ни во Ієрусали́мі іспо́лнися, єгда́ гроб с ті́лом твої́м отве́рст бисть. Ті́мже ни́ні Це́ркве Правосла́вния ча́да всі ра́дуються і лику́ють о Го́споді, притека́юще к чудото́чней ра́ці моще́й твої́х, преподобному́ченице Єлисаве́то, і благодаря́ще просла́вльшаго тя Го́спода, пою́ть си́це:","Ра́дуйся, я́ко мо́щі твоя́ нетлі́нієм процвіто́ша;","ра́дуйся, во Святу́ю Зе́млю ті́лом принесе́нная.","Ра́дуйся, в саду́ моле́нія Госпо́дня погребе́нная;","ра́дуйся, во хра́мі святи́я мироно́сиці упокоє́нная.","Ра́дуйся, явле́нієм моще́й твої́х Це́рков Ру́ськую возвесели́вшая;","ра́дуйся, су́щих в разсі́янії россі́йських люде́й духо́вно укріпи́вшая.","Ра́дуйся, я́ко Госпо́дь чрез мо́щі твоя́ ісціля́єть вся́кия ско́рби і болі́зні;","ра́дуйся, по мо́рю жите́йському пла́вающих ти́хоє приста́нище.","Ра́дуйся, віне́ць доброді́телей собра́вшая;","ра́дуйся, сла́вою і че́стію от Бо́га вінча́нная.","Ра́дуйся, Го́рняго Ієрусали́ма блаже́нная обита́тельнице;","ра́дуйся, ко Ієрусали́му Небе́сному всім нам путеводи́тельнице.","Ра́дуйся, благові́рная княги́не Єлисаве́то, преподобному́ченице достосла́вная."]},{"h":"Кондак 13","ps":["О, вели́кая страстоте́рпице, жен россі́йських украше́ніє і ра́досте на́ша, княги́не ми́лостивая Єлисаве́то, прийми́ от се́рдця воздиха́ніє на́ше, с любо́вію тебі́ приноси́моє, і твої́м предста́тельством ко Го́споду дух пра́вия ві́ри і благоче́стія в нас укріпи́, в доброді́телі і милосе́рдії утверди́, помози́ крест скорбе́й с терпі́нієм і наде́ждою понести́, в любві́ і согла́сії наро́д наш сохрани́, да сподо́бимся в ра́дость Го́спода вни́ти, со а́нгели і всі́ми святи́ми пою́ще Єму́: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгельським попече́нієм храни́мая і ма́терію твоє́ю благоче́стію поуча́ємая, в труді́х, моли́твах і ми́лостині ізмла́да о́браз доброді́тельнаго житія́ яви́ла єси́. По кончи́ні же ма́тере твоєя́ і бли́жніх сро́дников кре́стний путь, Го́сподем запові́данний, уразумі́ла єси́. Ті́мже, див'я́щеся таково́му от ю́ности твоєму́ ізбра́нію, со умиле́нієм взива́єм ті:","Ра́дуйся, от ю́ности Христа́ возлюби́вшая;","ра́дуйся, во мла́дости нача́тки благоче́стія приі́мшая.","Ра́дуйся, Христо́ва а́гнице ізбра́нная;","ра́дуйся, страх Бо́жий в душе́ восприя́вшая.","Ра́дуйся, доброді́телі ма́тере твоєя́ насле́дствовавшая;","ра́дуйся, трудолю́бію і милосе́рдію є́ю науче́нная.","Ра́дуйся, се́рдцем в Бо́зі утвержде́нная;","ра́дуйся, с ві́рою і упова́нієм крест твой поне́сшая.","Ра́дуйся, землі́ оте́чества твоєго́ цві́те благоуха́нний;","ра́дуйся, чистото́ю жи́зні твоєя́ Небеса́ возвесели́вшая.","Ра́дуйся, на служе́ніє стра́ждущим Бо́гом ізбра́нная;","ра́дуйся, пред Го́сподем о нас те́плая моли́твеннице.","Ра́дуйся, благові́рная княги́не Єлисаве́то, преподобному́ченице достосла́вная."]},{"h":"Кондак 1","ps":["Ізбра́нная от ро́да держа́внаго дщер Це́ркве Ру́ськия, любо́вію ізоби́льною і милосе́рдієм Бо́гу і бли́жнім до́брі послужи́вшая, за ві́ру во Христа́ Го́спода на́шего ду́шу свою́ положи́вшая і вінце́м сла́ви Христо́ви украше́нная, восхваля́юще по́двиги і страда́нія твоя́, с любо́вію воспіва́єм ті си́це:","Ра́дуйся, благові́рная княги́не Єлисаве́то, преподобному́ченице достосла́вная."]},{"h":"Молитва перша","ps":["О, вели́кая княги́не, свята́я преподобному́ченице Єлисаве́то, Россі́йськая похвало́, гра́да Москви́ пресла́вноє украше́ніє і Святи́я Землі́ свяще́нноє достоя́ніє!","Ти во дні житія́ твоєго́ ві́ру, наде́жду, любо́в нело́жни стяжа́вши, милосе́рдієм к стра́ждущим сві́тло просія́ла єси́. Терпі́нієм же скорбе́й і іскуше́ній о́браз смире́нія бли́жнім яви́вши, ізгна́нієм і страда́ньми житіє́ увінча́ла єси́ і во Ца́рствії Небе́снім ни́ні пребива́єши.","Сего́ ра́ди мо́лим тя, страстоте́рпице свята́я, моли́твами твої́ми да́руй нам се́рдце смире́нноє і покая́нноє, милосе́рдіє неоскудева́ющеє, служе́ніє бли́жнім же́ртвенноє, терпі́ніє непоколе́блемоє, му́жество в ско́рбіх і обстоя́ніїх неослабева́ющеє, в стра́шний же час сме́ртний упова́ніє тве́рдоє на Го́спода на́шего Ісу́са Христа́, Єму́же подоба́єть вся́кая сла́ва, честь і поклоне́ніє со Безнача́льним Єго́ Отце́м, і Пресвяти́м, Благи́м і Животворя́щим Єго́ Ду́хом ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О, святи́я новому́ченици Це́ркві Ру́ськия, вели́кая княги́не Єлисаве́то і пречестна́я і́нокине Варва́ро, ку́пно єва́нгельськия за́повіді ді́лом во оби́телі милосе́рдія соверши́вшия, ві́ри ра́ди правосла́вния до сме́рти подвиза́вшіяся і до́брий плод в терпі́нії страсте́й Христу́ прине́сшия! Молі́теся Єму́, я́ко побіди́телю сме́рти, да утверди́ть Це́рков Ру́ськую Правосла́вную і Оте́чество на́ше. Се бо лука́вий враг вооружа́ється на ни, хотя́ нас погуби́ти в междоусо́бних бра́ніх, ско́рбіх, печа́ліх, болі́зніх, ну́ждах і біда́х лю́тих. Умолі́те Го́спода низложи́ти вся немощни́я де́рзости єго́; ві́ру в сердця́х люде́й правосла́вних укріпі́те, нам же му́жества дар низпослі́те, да, отве́ргшеся себе́ і взе́мше крест свой, послі́дуєм Христу́, распина́юще плоть свою́ со страстьми́ і похотьми́. Сохрані́те нас от вся́каго зла, освяті́те путі́ жи́зні на́шея, да́руйте покая́ніє нелицемі́рноє, тишину́ і мир душа́м на́шим, іспросі́те у Го́спода всім нам мита́рств го́рких і ві́чния му́ки ізба́витися і Небе́сному Ца́рствію наслі́дником би́ти со всі́ми святи́ми, от ві́ка угоди́вшими Бо́гу, да ра́дующеся воздади́м хвалу́, честь і поклоне́ніє Отцю́ і Си́ну і Свято́му Ду́ху во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 1","ps":["Смире́нієм досто́їнство кня́жеськоє сокри́вши, / богому́драя Єлисаве́то, / сугу́бим служе́нієм Ма́рфи і Марі́ї / Христа́ почти́ла єси́. / Милосе́рдієм, терпі́нієм і любо́вію себі́ предочи́стивши, / я́ко же́ртва пра́ведная Бо́гу принесла́ся єси́. / Ми же, чту́ще доброді́тельноє житіє́ і страда́нія твоя́, / я́ко і́стинную наста́вницю усе́рдно про́сим тя: / свята́я му́ченице вели́кая княги́не Єлисаве́то, // моли́ Христа́ Бо́га спасти́ і просвіти́ти ду́ші на́ша."]},{"h":"Кондак, глас 2","ps":["Вели́чіє по́двига ві́ри кто пові́сть: / во глубині́ землі́, я́ко в раї́ сві́тлости, / страстоте́рпиця вели́кая княги́ня Єлисаве́та / со А́нгели во псалмі́х і пі́ніїх ра́довашеся / і, убіє́ніє претерпіва́ющи, / о безбо́жних мучи́теліх взива́ше: / Го́споди, прости́ їм гріх сей, / не ві́дять бо, что творя́ть. / Тоя́ моли́твами, Христе́ Бо́же, // поми́луй і спаси́ ду́ші на́ша."]},{"h":"Інший кондак, глас 5","ps":["От сла́ви ца́рственния, взе́мши Крест Христо́в, прешла́ єси́ к сла́ві Небе́сній, моля́щи враго́в, і обріла́ єси́ ра́дость ві́чную, свята́я му́ченице княги́не Єлисаве́то, с Варва́рою му́ченицею. Ті́мже мо́лим вас: молі́те о душа́х на́ших."]},{"h":"Величання","ps":["Велича́єм тя, / свята́я преподобному́ченице Єлисаве́то, / і чтим честна́я страда́нія твоя́, / я́же за Христа́ / претерпі́ла єси́."]}],"notes":[]},{"u":"Акафіст святителю Іоасафу, єпископу Білгородському","e":"Akathist to St Joasaph, Bishop of Belgorod","secs":[{"h":"Кондак 1","ps":["Ізбра́нних во́їнов му́жества наслі́дниче і Христо́ва ста́да па́стирю предо́брий, світи́льниче ві́ри, на сві́щниці Белогра́да возсія́вий, ни́щих пита́телю і о лю́діх ко Христу́ Бо́гу моли́твенниче, похва́льная воспису́єм ті раби́ Го́спода твоєго́ от серде́ць на́ших, к любві́ твоє́й вопію́ще:","Ра́дуйся, святи́телю Христо́в Іоаса́фе, чудотво́рче преди́вний."]},{"h":"Ікос 1","ps":["А́нгел Бо́жий по́слан бисть от Богоро́диці прообразова́тельноє ді́йствіє соверши́ти і о́трока тя су́ща ма́нтією святи́тельською покри́ти, Іоаса́фе. Сіє́ роди́тель твой зрі́ти во виді́нії сподо́бився, сли́шаше і глас Цари́ці Небе́сния глаго́лющ ті: Довлі́єть Мі моли́тва твоя́. Таково́му сла́достному гла́су вне́млюще, і ми, грі́шнії, любо́вію вопіє́м ті:","Ра́дуйся, от ма́тере твоєя́ в день Рождества́ Пречи́стия рожде́нний;","ра́дуйся, покро́вом Богоро́диці от рожде́нія твоєго́ покрове́нний.","Ра́дуйся, сосу́де, от ді́тства твоєго́ Бо́гом ізбра́нний;","ра́дуйся, под сі́нію оби́телі Тро́йці Святи́я Го́сподеві воспита́нний.","Ра́дуйся, роди́телей благочести́вих возлю́бленний си́не;","ра́дуйся, па́че при́сних твої́х возлюби́вий пусти́ню.","Ра́дуйся, во Ки́єві гра́де ра́зумом науче́ніє кни́жноє стяжа́вий;","ра́дуйся, чи́стоє се́рдце твоє́ Го́сподеві отда́вий.","Ра́дуйся, дом роди́телей твої́х Го́спода ра́ди оста́вивий;","ра́дуйся, та́йно в Межиго́рськую оби́тель стопи́ твоя́ напра́вивий.","Ра́дуйся, ю́ний моли́твенниче пеще́ри те́сния;","ра́дуйся, презрі́вий земна́я, возлюби́вий небе́сная.","Ра́дуйся, святи́телю Христо́в Іоаса́фе, чудотво́рче преди́вний."]},{"h":"Кондак 2","ps":["Ви́дя о́браз ми́ра сего́ преходя́щ і сла́ву челові́чеськую я́коже дим ісчеза́ющу, от ю́ности мона́шеськоє житіє́ возлюби́л єси́ і, отроча́ сий, моли́тві і службе Бо́жієй зіло́ приліжа́л єси́, Іоаса́фе, а́нгельськую піснь при́сно воспіва́я Го́сподеві: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум твой, науче́нієм кни́жним в Богоявле́нськом бра́тстві просвіща́ємий, богоми́слію преда́л єси́, Іоаса́фе, сокро́вища прему́дрости не себі́ собира́я, па́че же си́ми в Бо́га богаті́я, моли́твою же і поще́нієм во служе́ніє Христу́ себі́ уготовля́я. Тім же і во ю́ности твоє́й сицеви́х ублаже́ній досто́їн яви́лся єси́:","Ра́дуйся, о́бразе чистоти́ і цілому́дрія;","ра́дуйся, рачи́телю благи́й смиренному́дрія.","Ра́дуйся, отри́нувий, я́коже сор, ми́ра сего́ душетлі́нния сла́дости;","ра́дуйся, оми́вий ду́шу твою́ слеза́ми чи́стими мла́дости.","Ра́дуйся, ді́вство твоє́ нерастлі́нно Го́сподеві сохрани́вий;","ра́дуйся, прельще́нія во́зраста ю́наго побіди́вий.","Ра́дуйся, весно́, луча́ми благода́ті осія́нная;","ра́дуйся, у́тро, доброді́тельми облагоуха́нноє.","Ра́дуйся, я́ко Христу́ путе́м у́зьким послі́довал єси́;","ра́дуйся, я́ко го́рняго Оте́чествія дости́гнути возжелі́л єси́.","Ра́дуйся, на ра́ло Госпо́днє ру́ці твої́ возложи́вий;","ра́дуйся, лиця́ твоєго́ ніколи́же всп'ять обрати́вий.","Ра́дуйся, святи́телю Христо́в Іоаса́фе, чудотво́рче преди́вний."]},{"h":"Кондак 3","ps":["Си́ли ду́ха твоєго́ во єди́но намі́реніє совокупи́вий, во є́же Христу́ житіє́ твоє́ безразде́льне преда́ти, а́нгельський о́браз во ю́ности ра́нней восприя́л єси́, Іоаса́фе, і со ста́рці вку́пі воспі́л єси́ Трієди́ному Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я ору́жіє непобіди́моє, крест на се́рдці твоє́м, ві́рою начерта́нний, проти́ву страсте́й і гріхо́в сме́ртних, возстаю́щих на ни, крі́пко ополчи́лся єси́, і, Го́споду побі́ди на ти́я враги́ дарова́вшу, сложи́л єси́ піснь честни́м доброді́телем, є́йже внима́юще, і ми благода́рними усти́ си́це ті воспіва́єм:","Ра́дуйся, смире́нія о́бразе, і́мже горди́ня низлага́ється;","ра́дуйся, благосе́рдія пра́вило, і́мже вся́чеськая зло́ба побіжда́ється.","Ра́дуйся, цілому́дрія носи́телю і нечи́стих по́мислов отраже́ніє;","ра́дуйся, любве́ крі́пкия рачи́телю і не́нависті істребле́ніє.","Ра́дуйся, поста́ ору́жієм от плі́на страсте́й свободи́вийся;","ра́дуйся, кро́тости си́лою от гні́ва непра́веднаго огради́вийся.","Ра́дуйся, стра́же благоче́стія, от сна гріхо́внаго ду́шу твою́ охраня́яй;","ра́дуйся, доброді́телей содру́жеством от сме́ртния тлі ту́ю ізбавля́яй.","Ра́дуйся, уго́дниче Бо́жий, си́ми доброді́тельми в па́м'яті христия́н преукраше́нний;","ра́дуйся, світи́льниче ві́ри, от Со́лнця Пра́вди во Ца́рствії Небе́снім возжже́нний.","Ра́дуйся, істо́чниче, в жизнь ві́чную теки́й; ра́дуйся, на дия́вола крі́пці возмоги́й.","Ра́дуйся, святи́телю Христо́в Іоаса́фе, чудотво́рче преди́вний."]},{"h":"Кондак 4","ps":["Бу́рю іскуше́ній і нападе́ній вра́жиїх бо́дрственним житіє́м твої́м утиша́я, от архієре́я Бо́жия на степе́нь свяще́нства возведе́н бил єси́, і со вся́ким смиренному́дрієм на ра́мена твоя́ бре́м'я служе́нія церко́внаго во честні́м Ки́єве под'я́л єси́, ко святи́ням гра́да сего́ при́сно припа́дая, іді́же і додне́сь і́ноці і правосла́внії лю́діє вопію́ть Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шаху бли́жнії і да́льнії о труді́х твої́х неуста́нних, Іоаса́фе, ка́ко пе́рвіє во гра́ді Лубна́х оби́тель, тобо́ю благоукраша́ємая, благословля́ше тебі́, ігу́мена своєго́, по сих же Ла́вра Се́ргієва тобо́ю обнови́ся, єли́ко строє́нієм домо́вним, та́ко і житія́ і́ночеськаго ісправле́нієм. Того́ ра́ди глас наро́дний восхваля́ше тя си́ми:","Ра́дуйся, хра́мов святи́х іску́сний устрої́телю;","ра́дуйся, честни́х оби́телей усе́рдний украси́телю.","Ра́дуйся, ревни́телю благолі́пія церко́внаго;","ра́дуйся, па́че сих рачи́телю ді́ланія духо́внаго.","Ра́дуйся, в се́рдці твоє́м о́браз Христа́ носи́вий;","ра́дуйся, Спаси́теля твоєго́ до конця́ возлюби́вий.","Ра́дуйся, пропові́дниче, єго́же послу́шаше в сла́дость Россі́йськая цари́ця;","ра́дуйся, і́стини глаша́таю, не взира́яй на ли́ця.","Ра́дуйся, богоми́слію дія́ніє приложи́вий;","ра́дуйся, терпі́нію житіє́м твої́м вся научи́вий.","Ра́дуйся, я́ко в по́ті лиця́ твоєго́ Бо́га ра́ди труди́лся єси́;","ра́дуйся, я́ко в по́двизі до́брі дух твой усоверши́л єси́.","Ра́дуйся, святи́телю Христо́в Іоаса́фе, чудотво́рче преди́вний."]},{"h":"Кондак 5","ps":["Боготе́чній звізді́ послуша́нія, а́ки Вифлеє́мстей, ми́сленно послі́довав, обрі́л єси́ Христа́, во хра́мині душі́ твоєя́ я́вльшася, о́тче преподо́бне, і тому́ во́лю твою́ подклони́л єси́. Ті́мже і Госпо́дь, в боре́нії твоє́м тя укріпля́я, во виді́нії повеліва́єть Афана́сію, святи́телю Мга́рському, на главу́ твою́ ру́ці возложи́ти і тім гряду́щая твоя́ возвісти́ти, да со дерзнове́нієм вопіє́ши Царю́ Небе́сному: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше тя лю́діє Белогра́дстії наста́вника до́бра Боже́ственних уче́ній на престо́лі святи́тельстім я́вльшеся і оте́чеських преда́ній храни́теля ві́рна себі́ показу́юща, судію́ же нелицеприя́тна і па́стиря неуси́пна бива́юща, ра́довахуся зіло́ і єдиноду́шні восхваля́ху тя, глаго́люще:","Ра́дуйся, учи́телю і́стиннаго богопозна́нія;","ра́дуйся, гони́телю волше́бства і гада́нія.","Ра́дуйся, обличи́телю злочести́ваго неві́рія;","ра́дуйся, іскорени́телю раско́ла і суєві́рія.","Ра́дуйся, вельмо́жу невозде́ржнаго свято́му посту́ научи́вий;","ра́дуйся, уста́ви оте́чеськия во оби́теліх крі́пко водвори́вий.","Ра́дуйся, правосла́вния і́стини насади́телю;","ра́дуйся, учи́лищ благоче́стія покрови́телю.","Ра́дуйся, і́мже лати́нстії оби́чаї ізгоня́ються;","ра́дуйся, і́мже сімена́ пра́вди Христо́ви посеява́ються.","Ра́дуйся, і́щущим науче́нія отве́рстая врата́;","ра́дуйся, сла́ви Бо́жия немо́лчная уста́.","Ра́дуйся, святи́телю Христо́в Іоаса́фе, чудотво́рче преди́вний."]},{"h":"Кондак 6","ps":["Пропові́дник сий Правосла́вія догма́тов, за́повіді Госпо́дні не усти́ то́кмо, но і всім житіє́м твої́м із'ясни́л єси́, Іоаса́фе. Та́ко бо просвіти́ся світ твой пред челові́ки, я́ко, ви́дівше до́брая діла́ твоя́, всі прославля́ху Отця́ Небе́снаго, Єму́же вся́коє диха́ніє поє́ть хвалу́: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́вшу Со́лнцю Пра́вди го́ре пред очи́ма твої́ма, нощ гріха́ на землі́ ни́зу не стра́шна бисть тебі́, Іоаса́фе святи́телю, от Го́спода я́коже на корабли́ ко́рмчий поста́вленний і руко́ю крі́пкою корми́ло єго́ приє́мий. Ті́мже досто́йно сла́вим тя і не умолчи́м, вопію́ще:","Ра́дуйся, па́стирю, не себі́ угожда́яй;","ра́дуйся, ста́до Христо́во от волко́в хи́щних ві́рно огражда́яй.","Ра́дуйся, жезло́м пра́вди нече́стіє сокруши́вий;","ра́дуйся, небрегу́щия о святи́ні от Це́ркве Бо́жия отлучи́вий.","Ра́дуйся, огра́до крі́пкая непра́ведно оби́димим;","ра́дуйся, защище́ніє тве́рдоє пра́вди ра́ди ненави́димим.","Ра́дуйся, чтеця́ смире́ннаго от кня́жеських слуг защити́вий;","ра́дуйся, презри́тели уста́вов церко́вних низложи́вий.","Ра́дуйся, надме́нних пра́ведний обличи́телю;","ра́дуйся, непоко́рних стро́гий смири́телю.","Ра́дуйся, меча́ духо́внаго в но́жни не вложи́вий;","ра́дуйся, віне́ць пра́вди от Го́спода получи́вий.","Ра́дуйся, святи́телю Христо́в Іоаса́фе, чудотво́рче преди́вний."]},{"h":"Кондак 7","ps":["Хотя́ би́ти па́стир і́стинен, і́же своя́ о́вці глаша́єть по і́мені, многоча́стні ві́си і гра́ди па́стви твоєя́ обходи́л єси́ не ну́ждею, но по Бо́зі, ніже́ непра́ведними приби́тки, но усе́рдно, о́браз ста́ду подая́ во труді́х твої́х, і ше́ствіїх, і болі́зніх, непреста́нно поуча́я і облича́я і вся челові́ки призива́я служи́ти Бо́гу і пі́ти Тому́: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́ваго не́ба і но́вия землі́ по обітова́нію Христо́ву ча́я і сих ра́ди вну́тренняго челові́ка на всяк день обновля́я, посто́м плоть твою́ от рабо́ти істлі́нія свободи́л єси́, Іоаса́фе прему́дре, і моли́твою крилі́ ду́ху твоєму́ возрасти́л єси́, і́мже і нас грі́шних духо́вні воздвиза́єши, во є́же сла́вити тя і воспіва́ти:","Ра́дуйся, во труді́х і болі́зніх обріти́й небе́сния ра́дости;","ра́дуйся, в поще́ніїх і бді́ніїх вкуси́вий духо́вния сла́дости.","Ра́дуйся, во страда́ніїх твої́х плоть смири́вий;","ра́дуйся, о́браз терпі́нія лю́дем яви́вий.","Ра́дуйся, сосу́де немощни́й, си́ли духо́вния храни́лище;","ра́дуйся, ста́мно скуде́льная, благода́ті вмісти́лище.","Ра́дуйся, кади́ло благово́нних Бо́гу куре́ній;","ра́дуйся, хра́мино святи́х піснопі́ній.","Ра́дуйся, та́їн Бо́жиїх ди́вний строї́телю;","ра́дуйся, чад Це́ркве благода́тний учи́телю.","Ра́дуйся, я́ко тебі́ А́нгели незри́мо сослужа́ху;","ра́дуйся, я́ко от тебе́ де́мони дале́че отступа́ху.","Ра́дуйся, святи́телю Христо́в Іоаса́фе, чудотво́рче преди́вний."]},{"h":"Кондак 8","ps":["Стра́нник в ми́рі сем бив, го́рняя му́дрствовал єси́, а не земна́я, Іоаса́фе преподо́бне, і, помина́я послі́дняя твоя́, моли́лся єси́ Христу́ Бо́гу, глаго́ля: в час сме́рти моєя́ прийми́ дух раба́ Твоєго́, во стра́нствії су́ща, да со всі́ми святи́ми воспою́ Ті: Аллилу́я."]},{"h":"Ікос 8","ps":["Всім се́рдцем твої́м і свято́ю любо́вію твоє́ю ме́ньшей бра́тії послужи́л єси́, святи́телю Іоаса́фе, а́лчущих пита́я, до́ми си́рих і убо́гих согріва́я, свої́ма рука́ма дрова́ вдови́цям уготовля́я, ми́лостині же твоя́ творя́ в та́йні. Но Го́споду ізво́лившу, яви́шася ми́рові блага́я діла́ твоя́, я́же сла́в'яще, взива́єм ті си́це:","Ра́дуйся, дре́во благода́тноє, от єго́же плодо́в пита́ються а́лчущії;","ра́дуйся, істо́чниче утіше́ній, от него́же напоя́ються жа́ждущії.","Ра́дуйся, я́ко шу́йця твоя́ не ві́ді, я́же творя́ше десни́ця;","ра́дуйся, я́ко трапе́за твоя́ бисть утіше́ніє су́щим в темни́цях.","Ра́дуйся, пи́щею твоє́ю воєво́ду опа́льнаго пита́вий;","ра́дуйся, я́ко воспрети́ти сіє́ тебі́ не возмо́же прави́тель лука́вий.","Ра́дуйся, разбо́йники, напа́дшия на тя, сло́вом твої́м устиди́вий;","ра́дуйся, єди́наго от них к покая́нію коне́чному обрати́вий.","Ра́дуйся, ма́терей, млеко́м пита́ющих, благо́є защище́ніє;","ра́дуйся, о отроча́тіх ма́лих му́дроє попече́ніє.","Ра́дуйся, я́ко ми́лость і суд во єди́но совокупи́л єси́;","ра́дуйся, я́ко любо́вію твоє́ю наро́дную любо́в себі́ стяжа́л єси́.","Ра́дуйся, святи́телю Христо́в Іоаса́фе, чудотво́рче преди́вний."]},{"h":"Кондак 9","ps":["Вся́кую та́йну душі́ челові́чеськія прозріва́ше духо́вноє о́ко твоє́. Ті́мже откри́ся тебі́ і гріх ієре́я о́наго, лі́ти у́бо согбе́ннаго, кля́твою же А́нгела Бо́жия на землі́ сей свя́заннаго, єго́же к покая́нію приве́д і Бо́гу примири́в, по Литургі́ї Боже́ственній от гріхо́внаго плі́на і уз привре́меннаго житія́ ізба́вил єси́, поя́ Всеми́лостивому Спа́су: Аллилу́я."]},{"h":"Ікос 9","ps":["Віті́й многовеща́нних па́че, глас наро́дний немо́лчно сла́вить тя, Іоаса́фе блаже́нне. Ті́мже і ни́ні прийми́ похвали́ сія́ от всіх нас, во умиле́нії серде́ць к тебі́ зову́щих:","Ра́дуйся, я́ко моли́тви твоя́ всено́щния благода́ть Бо́жию на зе́млю низвожда́ху;","ра́дуйся, я́ко дні́є твої́ многотру́днії бла́го Це́ркві і лю́дем приноша́ху.","Ра́дуйся, о овця́х слове́сних ста́да твоєго́ па́стирськоє попече́ніє при́сно явля́яй;","ра́дуйся, чин церко́вний благолі́пно ісправля́яй.","Ра́дуйся, бра́ні і сва́ри преще́нієм твої́м укроти́вий;","ра́дуйся, ми́рному житію́ пресві́тери і дия́кони научи́вий.","Ра́дуйся, я́ко в тебі́ но́вий сосу́д благода́ті откри́ся;","ра́дуйся, я́ко тобо́ю Пеща́нський о́браз Богома́тері яви́ся.","Ра́дуйся, та́їн серде́чних я́вноє возвіще́ніє;","ра́дуйся, гряду́щих ди́вноє прозрі́ніє.","Ра́дуйся, заві́та єва́нгельськаго ві́рний храни́телю;","ра́дуйся, за́повідей церко́вних нелицемі́рний блюсти́телю.","Ра́дуйся, святи́телю Христо́в Іоаса́фе, чудотво́рче преди́вний."]},{"h":"Кондак 10","ps":["Спасти́ от расхище́нія о́вці твоя́ хотя́, во́лки лю́тия жезло́м святи́тельським дале́че отгна́л єси́ от огра́ди церко́вния, сло́вом же і́стини, я́коже мече́м обоюдоо́стрим, нападе́нія о́них отрази́л єси́, Іоаса́фе, побі́дную піснь воспіва́я Го́сподеві: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіно́ю крі́пкою огради́л єси́ лю́ди твоя́, блаже́нне, на основа́нії ві́ри сію́ положи́в, от ка́меній же наде́жди і любве́ ту́ю воздви́гнув і па́м'ятію по́двигов твої́х на ві́ки укріпи́в. Сих ра́ди піснь слага́єм тебі́, взива́юще:","Ра́дуйся, оби́чаєв злих гони́телю, до́брих же защи́тителю;","ра́дуйся, о́бласти твоєя́ прему́дрий упра́вителю.","Ра́дуйся, Россі́йськия страни́ ору́жіє духо́вноє;","ра́дуйся, зерца́ло сві́тлоє пра́вди церко́вния.","Ра́дуйся, человікоуго́дія ра́ди нікого́же пощади́вий;","ра́дуйся, мздоприї́мство я́ві обличи́вий.","Ра́дуйся, стра́ха ра́ди челові́ча две́рі пра́вди ніколи́же затвори́вий;","ра́дуйся, єди́ному стра́ху Бо́жию се́рдце твоє́ покори́вий.","Ра́дуйся, пла́менем гні́ва Госпо́дня враги́ ві́ри опаля́яй;","ра́дуйся, я́рость гні́ва непра́веднаго кро́тостію утиша́яй.","Ра́дуйся, воєво́до Христо́в неустраши́мий;","ра́дуйся, па́стирю, вся люб'я́й і от всіх люби́мий.","Ра́дуйся, святи́телю Христо́в Іоаса́фе, чудотво́рче преди́вний."]},{"h":"Кондак 11","ps":["Пі́ніє хвале́бноє прино́сим ті от смире́нних серде́ць на́ших, Іоаса́фе блаже́нне. Сіє́ у́бо любо́вію твоє́ю прия́ти не отврати́ся, а́ще і сладча́йшия гла́си А́нгелов ни́ні сли́шиши, на небесі́ Бо́гу пою́щих: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоза́рному небесі́ угото́вав дух твой і ско́рий коне́ць житія́ земна́го проразумі́в, к погребе́нію же тілесе́ твоєго́ хра́мину угото́вити повелі́в, посіти́л єси́ оте́чеський град і роди́телі твоя́, по за́повіді Бо́жієй тім честь воздава́я і любо́вію сино́внею ду́ші їх во ві́рі і упова́нії усоверша́я, ї́миже і нас просвіти́, Іоаса́фе блаже́нне, зову́щих:","Ра́дуйся, ста́рость роди́телей посіще́нієм твої́м озари́вий;","ра́дуйся, се́ла оте́чеськая пред кончи́ною твоє́ю благослови́вий.","Ра́дуйся, я́ко неду́зі дух твой я́коже зла́то очища́ху;","ра́дуйся, я́ко доброді́телі твоя́ я́коже ка́меніє драго́є сія́ху.","Ра́дуйся, кораблю́, напа́стьми бур жите́йських неодолі́нний;","ра́дуйся, сла́вно сверши́вий путь, от Христа́ повеле́нний.","Ра́дуйся, я́ко тебі́ при́стань благооти́шная пресві́тлоє Не́бо яви́ся;","ра́дуйся, я́ко тебі́ двер Ца́рствія Христо́ва откри́ся.","Ра́дуйся, я́ко всели́лся єси́ ду́хом твої́м в го́рняя селе́нія;","ра́дуйся, я́ко і на землі́ оста́вил єси́ нетлі́нен зало́г воскресе́нія.","Ра́дуйся, звіздо́, на тве́рди духо́вній сія́ющая;","ра́дуйся, моли́тво о нас к Бо́гу неумолка́ющая.","Ра́дуйся, святи́телю Христо́в Іоаса́фе, чудотво́рче преди́вний."]},{"h":"Кондак 12","ps":["Благода́ті неістощи́мия зна́меніє непререка́ємоє яви́ нам Христо́с в нетлі́нії моще́й твої́х, Іоаса́фе прему́дре, пред ни́миже лю́діє ві́рнії моля́щеся, от ви́димих к неви́димим духо́вні восходи́ти науча́ються, Бо́га же, ди́внаго во святи́х Свої́х, сла́вити і а́нгельськи Єму́ воспіва́ти: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще пра́ведноє житіє́ твоє́, Іоаса́фе блаже́нне, сла́в'яще труди́ твоя́ і восхожде́нія от сла́ви в сла́ву, зрим і іспові́дуєм, я́ко кончи́на твоя́ рожде́ніє бисть в жизнь приснотеку́щую, єя́же струя́ми благода́тними і нас, земни́х, окропля́єши і от болі́зней душе́вних і тіле́сних, Го́споду ізволя́ющу, свобожда́єши, неду́гующим і приско́рбним многоча́стні во виді́нії явля́яся і утіше́ніє принося́, найпа́че же моля́щимся пред гробни́цею твоє́ю неви́димо вне́млеши і ви́димо по́мощ подає́ши. Ті́мже, благода́рственно воспіва́юще тя, глаго́лем:","Ра́дуйся, ра́дости приобщи́вийся, в печа́лі же су́щих не заби́вий;","ра́дуйся, у́хо твоє́ ко юдо́лі скорбе́й приклони́вий.","Ра́дуйся, я́коже Ілия́ Фесви́тянин, огне́м ре́вности по Бо́зі горя́й;","ра́дуйся, стопа́ми Чудотво́рця Мир Ликі́йських в хи́жини бі́дних входя́й.","Ра́дуйся, отча́янним неча́янноє вспоможе́ніє;","ра́дуйся, разсла́бленним благода́тноє укріпле́ніє.","Ра́дуйся, я́ко твої́ми моли́твами хро́мії хожда́ху;","ра́дуйся, я́ко тобо́ю сліпі́ї зрі́ніє получа́ху.","Ра́дуйся, от многообра́зних неду́гов ісціля́яй;","ра́дуйся, во́їни правосла́вния на бра́ні охраня́яй.","Ра́дуйся, землі́ россі́йськия защи́тниче ві́рний;","ра́дуйся, Правосла́вія побо́рниче нелицемі́рний.","Ра́дуйся, святи́телю Христо́в Іоаса́фе, чудотво́рче преди́вний."]},{"h":"Кондак 13","ps":["О пресла́вний па́стирю Білогра́дський, святи́телю Іоаса́фе! Прийми́ ма́лоє сіє́ хвале́ніє на́ше і моли́ Христа́ Бо́га, да ізба́вить зе́млю Россі́йськую і вся страни́ христия́нськия от смертоно́снаго неві́рія я́зви, от вся́кия вражди́ і нестроє́нія, от враг ви́димих і неви́димих. Це́рков же святу́ю да возрасти́ть і укріпи́ть, і вся ві́рния ко Христу́ всеми́рному Па́стирю приведе́ть, пою́щия Єму́: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгел Бо́жий по́слан бисть от Богоро́диці прообразова́тельноє ді́йствіє соверши́ти і о́трока тя су́ща ма́нтією святи́тельською покри́ти, Іоаса́фе. Сіє́ роди́тель твой зрі́ти во виді́нії сподо́бився, сли́шаше і глас Цари́ці Небе́сния глаго́лющ ті: Довлі́єть Мі моли́тва твоя́. Таково́му сла́достному гла́су вне́млюще, і ми, грі́шнії, любо́вію вопіє́м ті:","Ра́дуйся, от ма́тере твоєя́ в день Рождества́ Пречи́стия рожде́нний;","ра́дуйся, покро́вом Богоро́диці от рожде́нія твоєго́ покрове́нний.","Ра́дуйся, сосу́де, от ді́тства твоєго́ Бо́гом ізбра́нний;","ра́дуйся, под сі́нію оби́телі Тро́йці Святи́я Го́сподеві воспита́нний.","Ра́дуйся, роди́телей благочести́вих возлю́бленний си́не;","ра́дуйся, па́че при́сних твої́х возлюби́вий пусти́ню.","Ра́дуйся, во Ки́єві гра́де ра́зумом науче́ніє кни́жноє стяжа́вий;","ра́дуйся, чи́стоє се́рдце твоє́ Го́сподеві отда́вий.","Ра́дуйся, дом роди́телей твої́х Го́спода ра́ди оста́вивий;","ра́дуйся, та́йно в Межиго́рськую оби́тель стопи́ твоя́ напра́вивий.","Ра́дуйся, ю́ний моли́твенниче пеще́ри те́сния;","ра́дуйся, презрі́вий земна́я, возлюби́вий небе́сная.","Ра́дуйся, святи́телю Христо́в Іоаса́фе, чудотво́рче преди́вний."]},{"h":"Кондак 1","ps":["Ізбра́нних во́їнов му́жества наслі́дниче і Христо́ва ста́да па́стирю предо́брий, світи́льниче ві́ри, на сві́щниці Белогра́да возсія́вий, ни́щих пита́телю і о лю́діх ко Христу́ Бо́гу моли́твенниче, похва́льная воспису́єм ті раби́ Го́спода твоєго́ от серде́ць на́ших, к любві́ твоє́й вопію́ще:","Ра́дуйся, святи́телю Христо́в Іоаса́фе, чудотво́рче преди́вний."]},{"h":"Молитва перша","ps":["О святи́телю Христо́в Іоаса́фе, чудотво́рче Білогра́дський! Ві́руєм грі́шнії і недосто́йнії, я́ко о́чі Госпо́дні на пра́ведних і у́ші Єго́ на моли́тву їх, і того́ ра́ди к моли́твам твої́м прибіга́єм і хода́тайства твоєго́ за нас про́сим, по глаго́лу апо́стольському упова́юще, я́ко люби́ твоєя́ ніколи́же отпа́даєть. Во грісі́х і болі́зніх на́ших льну куря́щемуся і тро́сти сокруше́нній уподо́бихомся, і, а́ще живе́м, ми́лостію Бо́га живе́м і за моли́тви пра́ведник Єго́. Приклони́ у́бо і ти, о́тче пра́ведне, се́рдце твоє́ к моле́нію на́шему, і предста́тельством твої́м даждь ро́ду христия́нському от Го́спода мир і благослове́ніє. Правосла́віє укріпи́, нападе́нія же лука́внующих і беззако́нних на це́рков Бо́жию отжени́. Умоли́ Отця́ небе́снаго ізба́витися нам от наше́ствія вра́жеськаго, от междоусо́бій же і см'яте́ній наро́дних, от губи́тельних пові́трій і смертоно́сния я́зви, от гла́да, огня́, пото́па і іни́х бід і обстоя́ній. Іспроси́ у Христа́ Бо́га душа́м на́шим крі́пость і тілесе́м на́шим потре́бноє здра́віє, болі́знем же ісціле́ніє: хроми́м хожде́ніє, сліпи́м прозрі́ніє, разсла́бленним утвержде́ніє, печа́льним утіше́ніє і от всіх скорбе́й ізбавле́ніє. Отпа́дшия же лози́ Христо́ви ві́тві па́ки с то́ю соєдини́, єя́же і сам прича́стник би́ти сподо́бился єси́, да та́ко просла́виться тобо́ю пречестно́є і великолі́поє і́м'я Бо́га на́шего, Отця́ і Си́на і Свята́го Ду́ха, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О вели́кий уго́дниче Бо́жий і пресла́вний чудотво́рче, святи́телю Іоаса́фе! От да́льних і бли́жніх градо́в і ве́сей соше́дшеся, во є́же на мі́сті по́двигов твої́х помоли́тися і многоціле́бния мо́щі твоя́ облобиза́ти, із глубини́ се́рдця взива́єм к тебі́: жезло́м бла́гости, я́коже па́стир до́брий, упаси́ заблу́ждшия о́вці ста́да Христо́ва, во двори́ Госпо́дні сія́ всели́, огради́ нас от собла́зна, єресе́й і раско́лов, научи́ во стра́нствії су́щих го́рняя му́дрствовати: разсі́янний ум наш просвіти́ і на путь і́стини напра́ви, охладі́вшеє се́рдце согрі́й любо́вію ко бли́жнему і ре́вностію к ісполне́нію велі́ній Бо́жиїх, гріхо́м і нераді́нієм осла́бленную во́лю на́шу оживотвори́ благода́тію Ду́ха всесвята́го: да твоєму́ па́стирському гла́су послі́дующе, сохрани́м в чистоті́ і пра́вді ду́ші на́ша, і та́ко, Бо́гу помога́ющу, небе́снаго ца́рствія дости́гнем, іді́же ку́пно с тобо́ю воспросла́вим пречестно́є і великолі́поє і́м'я Отця́ і Си́на і Ду́ха Свята́го во ві́ки віко́в. Амі́нь."]},{"h":"Молитва третя","ps":["О вели́кий Святи́телю наш і чудотво́рче преди́вний Іоаса́фе, ско́рий помо́щниче к тебі́ припа́дающих! Ми́лостивно при́зри на нас недосто́йних, со слеза́ми умиле́нія зді моля́щихся і благодаре́ніє тебі́ по си́лі принося́щих. Благодари́м тя, уго́дниче Христо́в, я́ко усли́шал єси́ моле́нія нас недосто́йних і проси́мая нам оби́льно дарова́л єси́. Ві́ми і усти́ іспові́дуєм, я́ко воі́стину Христу́ те́плий о нас єси́ моли́твенник і, по да́нной ті благода́ті і да́ру, во спасе́ніє всім нам потре́бная да́руєши: боля́щия ісціля́єши, стра́ждущия утіша́єши, мир і отра́ду ско́рбним сердця́м ізлива́єши, пла́чущия ра́доватися твори́ти, печа́льния ликова́ти содіва́єши: роди́телем ча́да воздравля́єши, супру́гом подру́жія от одра́ сме́ртнаго возставля́єши, вражду́ющия умиротворя́єши, зави́стливия твори́ши ми́лостиви, і вся́кия непра́вди кара́єши, я́коже і в житії́ твоє́м пра́вди і милосе́рдія му́жественний ревни́тель бил єси́. Благодари́м тя, Святи́телю, за вели́кая твоя́ і нам явле́нная благодія́нія, і смире́нно мо́лимся тебі́ ми недосто́йнії: предста́тельствуй за нас у престо́ла Христо́ва, і помози́ нам па́м'ять при́сную твої́х благодія́ній і щедро́т на нас ізлія́нних храни́ти, да во смире́нії се́рдця про́чеє соверши́м житіє́, і небе́сноє да наслі́дуєм селе́ніє Боже́ственноє, моли́твами твої́ми, во ві́ки віко́в. Амі́нь."]},{"h":"Молитва четверта, про недугуючих і страждущих","ps":["О вели́кий уго́дниче Христо́в, святи́телю о́тче наш Іоаса́фе, ско́рий помо́щниче і ди́вний чудотво́рче! При́зри ми́лостивно на ни неду́гующия. Ві́ми, уго́дниче Христо́в, ві́ми, і усти́ і се́рдцем іспові́дуєм, я́ко по діло́м на́шим біди́ постиго́ша нас. С разбо́йником благоразу́мним іспові́дуєм Го́сподеві, я́ко досто́йная по діло́м на́шим восприє́млем і зла́я сія́ я́коже раби́ неключи́мії терпи́м. Си́ми бо вре́менними муче́ньми Госпо́дь милосе́рдий сокруша́єть горди́ню і жестокови́йноє се́рдце на́ше, да ві́чния ізбіжи́м ка́зні, грі́шником угото́ванния: сі́яхом бо сі́мена житія́ своєво́льнаго, і жнем те́рнія скорбе́й. Оба́че, немощні́ї су́ще, но в покая́ніє те́плоє прише́дше, о сем моли́тися дерза́єм, да гнів Госпо́день на ми́лость к нам преложи́ться, і тебі́, святи́телю Бо́жий і чудотво́рче, усе́рдно про́сим: проли́й те́плую моли́тву твою́ ко Христу́ Го́споду на́шему, єму́же днесь предстої́ши і мо́лишися о почита́ющих тя с любо́вію і смире́нним на твоє́ предста́тельство упова́нієм. Се бо в житії́ твоє́м, Святи́телю Христо́в, ні єди́наго же скорб'я́ща і ми́лости твоєя́ прося́ща, гріхи́ же своя́ іспові́дающа, ніколи́же презрі́л єси́. Умоли́ пра́веднаго судію́, да преложи́ть гнів пра́вди своєя́ на ми́лованіє на́ше. Благода́тію єго́ тебі́ да́нною, святи́телю милосе́рдий, уврачу́й на́ша не́мощі, болі́зней лю́тих тече́нія уста́ви, сме́рті отити́ повели́, і на покая́ніє си́лу нам да́руй. Ста́рость поддержи́, младе́нці воспита́й, ю́ность уцілому́дри, супру́жества в чистоті́ і смире́нії утверди́, нам же всім послуша́ніє трудолю́бноє і ми́рноє жи́тельство моли́твою твоє́ю да́руй, да терпі́нієм тече́м на предлежа́щий нам по́двиг житія́ сего́ вре́меннаго, взира́юще на нача́льника ві́ри і соверши́теля Го́спода Ісу́са. Єму́же сла́ва во ві́ки віко́в. Амі́нь."]},{"h":"Молитва п’ята, у день прославлення","ps":["Вели́кий і пра́зднственний день сей, день твоєго́ на землі́ прославле́нія, святи́телю о́тче наш Іоаса́фе, землі́ на́шея сла́во і ра́дованіє вели́коє, прийми́ сія́ смире́нная і те́плая моле́нія на́ша. Днесь зрим іспо́лнившийся глаго́л Госпо́день: прославля́ющия М'я просла́влю. Се бо во дні земна́го житія́ твоєго́ нічто́же іска́л єси́, то́чію же во́лю Бо́жию ісполня́ти і ча́да па́стви твоєя́ упра́вити во спасе́ніє, і того́ ра́ди мно́гія труди́, ско́рби, болі́зні, путеше́ствія под'я́л єси́. По сконча́нії же твоє́м просла́ви тя милосе́рдий Госпо́дь, тілесі́ твоєму́ нетлі́ніє і си́ли ціле́бния дарова́вий; ті́мже то́ки ісціле́ній моля́щимся істочи́л єси́ і призива́ющим тя неду́гующим і скорб'я́щим мно́гажди явля́лся єси́, і утіше́ніє і цільбу́ ско́рую тім подава́я. Сего́ ра́ди, я́коже ізбра́нника Боже́ственния благода́ті тя ві́дущи, Це́рков Христо́ва просла́віте тя я́коже но́ваго чудотво́рця землі́ на́шея сподо́бися. Благослови́ у́бо і поми́луй, архієре́ю і́стиннаго Бо́га, лю́ди правосла́вния. Да́руй їм утіше́ніє се́рдця, отра́ду і мир і ра́дость при́сную о Го́споді. Сохрани́ в ми́рі держа́ву Россі́йськую і лю́ди єя́ во і́стині утверди́, во́їном му́жество непоколеби́моє да́руй і вся лю́ди безпеча́льни сохрани́. Ізжени́ вся́кую крамолу́ і крамо́льних челові́к лука́вая разруши́ сові́тованія, па́че же тіх са́мих в покая́ніє приведи́. Па́стирем і архієре́єм пода́ждь прему́дрость, чистоту́ і пра́ведноє житіє́, я́коже і сам си́ми украша́лся єси́. Младе́нцем воспита́ніє благо́є даждь, ю́ния научи́, боля́щим і скорб'я́щим здра́віє іспроси́. Су́щим во труді́х терпі́ніє і упова́ніє посли́, бога́тим смиренному́дріє і ко бли́жнім милосе́рдіє да́руй. Нам же всім ра́дость о Го́споді при́сную пода́ждь, да всі благода́рні тя ублажа́єм, глаго́люще та́ко: велича́єм тя, святи́телю о́тче Іоаса́фе, і чтим святу́ю па́м'ять твою́, ти бо мо́лиши за нас Христа́ Бо́га на́шего."]},{"h":"Тропар, глас 3","ps":["Святи́телю Христу́ Бо́гу возлю́бленне, / пра́вило ві́ри і о́браз милосе́рдія лю́дем бил єси́, / бді́нієм же, посто́м і моли́твою / я́ко світи́льник пресві́тлий просія́л єси́, / і просла́влен от Бо́га яви́лся єси́: / ті́лом у́бо в нетлі́нії почива́я, / ду́хом же Престо́лу Бо́жию предстоя́, / чудеса́ пресла́вная істоча́єши. / Моли́ Христа́ Бо́га, / да утверди́ть нас в Правосла́вії і благоче́стії, // і спасе́ть ду́ші на́ша."]},{"h":"Інший тропар, глас 2","ps":["Моли́твенниче ізді́тства преізря́дний, / богоізбра́нний святи́телю Христо́в Іоаса́фе, / пра́вило ві́ри і о́браз милосе́рдія благоче́стним житіє́м всім явля́єши / і с ві́рою к тебі́ притека́ющим оби́льно ісціле́нія істоча́єши. / Моли́ Христа́ Бо́га, / да утверди́ть правові́ріє, мир і благоче́стіє // і спасе́ть ду́ші на́ша."]},{"h":"Кондак, глас 8","ps":["Многоразли́чния по́двиги житія́ твоєго́ кто іспові́сть? / Многообра́зния ми́лости Бо́жия тобо́ю явле́нния кто ісчи́слить? / Дерзнове́ніє же твоє́ у Пречи́стия Богоро́диці і Всеще́драго Бо́га до́брі ві́дуще, / во умиле́нії серде́чнім зове́м ті: / не лиши́ і нас твоє́я по́мощі і заступле́нія, // святи́телю Христо́в і чудотво́рче Іоаса́фе."]},{"h":"Величання","ps":["Велича́єм тя, святи́телю о́тче Іоаса́фе, і чтим святу́ю па́м'ять твою́, ти бо мо́лиши за нас Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Акафіст святій великомучениці Катерині","e":"Akathist to the Holy Great Martyr Catherine","secs":[{"h":"Кондак 1","ps":["Ізбра́нную і венча́нную ді́ву му́ченицю, неві́сту Христо́ву Єкатери́ну, похва́льними пі́сньми воспої́м, я́ко пресла́вную мучи́теля победи́тельницю і прему́друю филосо́фов наста́вницю: ти же, великому́ченице Єкатери́но, іму́щи дерзнове́ніє ко Го́споду, приклони́ся ми́лостивне к благопотре́бним проше́ніям зову́щих ті:","Ра́дуйся, Єкатери́но, неві́сто Христо́ва прему́драя."]},{"h":"Ікос 1","ps":["А́нгелом ра́вную чистоту́ іму́щи, свята́я ді́во Єкатери́но, с А́нгели Боже́ственнаго озаре́нія сподо́билася єси́, с ни́ми же воспіва́ющи Трисвяту́ю піснь, усли́ши нас, пою́щих тебі́ на землі́ сія́:","Ра́дуйся, честно́є святи́ні жили́ще;","ра́дуйся, чуде́сноє зна́меніє сби́вшагося на тебі́ Бо́жия Про́мисла.","Ра́дуйся, благоволе́нія О́тча сосу́де;","ра́дуйся, страда́ній Христо́вих ісполне́ніє.","Ра́дуйся, чи́стоє Ду́ха Свята́го обита́лище;","ра́дуйся, сві́том благочести́вия ві́ри просвети́вшаяся.","Ра́дуйся, свято́ю купі́лію отрожде́нная;","ра́дуйся, ізми́вшая ри́зи своя́ в Кро́ві А́гнчей на землі́.","Ра́дуйся, лику́ющая с свяще́нними ді́вами на Небесі́.","Ра́дуйся, Єкатери́но, неві́сто Христо́ва прему́драя."]},{"h":"Кондак 2","ps":["Ви́дящи Єкатери́на себі́ виді́нія сподо́бльшуюся, тече́ к свято́му ста́рцю, іко́ну єй Богома́тере пре́жде того́ вручи́вшему, і пові́да єму́, ка́ко отвраща́ше лице́ Своє́ єй яви́вийся с Пречи́стою Своє́ю Ма́терію Христо́с, ка́ко безу́мну, і ни́щу, і худоро́дну ю наре́к, до́ндеже не оста́вить і́дольськаго нече́стія. Преподо́бний же, сли́шав сія́, наста́ви ю в та́їнствах ві́ри і крести́ ю. Она́ же во обновле́нії ду́ха благода́рно поя́ше Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум благи́й, благоро́дство і́стинноє, бога́тство неги́блющеє стяжа́вши в духо́вном отрожде́нії, свята́я Єкатери́на досто́йна яви́ся Небе́снаго Жениха́ Христа́, І́же, па́ки яви́вся єй, возлюби́ ю і дарова́нним пе́рстнем в неві́сту Себі́ обручи́. Она́ же, позна́вши тако́є к ней благоволе́ніє Бо́жиє, та́ко уязви́ся любо́вію Єго́, я́ко не му́дрствоваше бо́ліє о земни́х веща́х, но о Возлю́бленном своє́м непреста́нно ми́сляше. Таково́й благода́ті сподо́бльшаяся, сли́ши от нас:","Ра́дуйся, злово́ніє мирсько́є возненави́девшая;","ра́дуйся, во воню́ ми́ра Христо́ва теку́щая.","Ра́дуйся, до́брая люби́тельнице Жениха́ Безсме́ртнаго;","ра́дуйся, сокро́вище благоволе́нія Ви́шняго.","Ра́дуйся, денни́це пресві́тлая;","ра́дуйся, луно́ соверше́нная.","Ра́дуйся, ма́слино, в до́му Бо́жії насажде́нная;","ра́дуйся, ке́дре, в Лива́ні високора́сленний.","Ра́дуйся, Єкатери́но, неві́сто Христо́ва прему́драя."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго даде́ тогда́ святі́й Єкатери́ні дерзнове́ніє, є́же нече́ствующаго царя́ Максими́на о принесе́нії і́долом жертв обличи́ти небоя́зненно, і той преби́сть безгла́сен на мног час, не моги́й проти́витися єя́ глаго́лом. Она́ же, благодаря́щи Бо́га, воспіва́ше: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́щи свята́я Єкатери́на сви́ше да́нную єй прему́дрость, єгда́ нечести́вий цар, поста́вив пред собо́ю, вопроша́ше ю о ро́ді єя́ і са́ні, она́ іспові́да себі́ би́ти дщер ца́рськую, филосо́фськия і ри́торськия нау́ки до́брі ізучи́вшую, па́че же Христо́ву неві́сту себі́ найменова́, в я́вноє отверже́ніє і́дольськаго служе́нія. Сего́ ра́ди воспіва́єм єй си́це:","Ра́дуйся у́бо, Єкатери́но пресла́вная;","ра́дуйся, ца́рськоє свяще́ніє.","Ра́дуйся, пчело́, ди́ма і́дольськаго отлеті́вшая,","ра́дуйся, голуби́це, зла́ти крила́ іму́щая.","Ра́дуйся, кади́ло Христо́ва благоуха́нія.","Ра́дуйся, Єкатери́но, неві́сто Христо́ва прему́драя."]},{"h":"Кондак 4","ps":["Бу́рею я́рости вознеї́стовився цар на святу́ю ді́ву, рече́ к ней: «Не глаго́ли злі о бо́зіх на́ших». Свята́я же Єкатери́на отвіща́: «А́ще восхо́щеши отрясти́ мрак пре́лести от душе́вних ті оче́й, уразумі́єши бого́в твої́х ху́дость і позна́єши і́стиннаго Бо́га, Єго́же і́м'я, то́кмо глаго́лемоє, іли́ крест, ізобразу́ємий на возду́сі, прогоня́єть бо́ги твоя́ і погубля́єть. І а́ще повели́ши, явлю́ тебі́ і́стину, пою́щи Бо́гу моєму́: Аллилу́я»."]},{"h":"Ікос 4","ps":["Сли́шав нечести́вий цар свобо́дний і му́дрий отві́т твой о ві́рі Христо́вой, убоя́вся, да не бу́деть побіжде́н от тебе́, собра́ от преді́лов держа́ви своєя́ мудрецо́в, число́м п'ятьдеся́т, на прі́ніє. Ти же, Арха́нгелом Михаї́лом утвержде́нная і о побі́ді уве́ренная, возра́довалася єси́ вступи́ти в прі́ніє с ни́ми. Прийми́ у́бо, ді́во, от нас похвалу́ сію́:","Ра́дуйся, із'яви́тельнице ума́ Христо́ва;","ра́дуйся, херуви́мськоє стяжа́вшая Богопозна́ніє.","Ра́дуйся, серафи́мською воспале́нная к Бо́гу любо́вію;","ра́дуйся, му́дрих мудрі́йшая.","Ра́дуйся, духо́вний меч на неві́ріє ізостри́вшая;","ра́дуйся, нече́стія прогони́тельнице.","Ра́дуйся, ві́рних наста́внице.","Ра́дуйся, Єкатери́но, неві́сто Христо́ва прему́драя."]},{"h":"Кондак 5","ps":["Боготе́чной звізді́ била́ єси́ подо́бна, Єкатери́но, препрі́вши п'ятьдеся́т виті́й і наста́вивши їх на путь христия́нський, веду́щий к пра́ведному Со́лнцю, от Ді́ви возсія́вшему Христу́ Бо́гу, свої́ми му́дрими глаго́ли, і́же і осужде́ні би́вше за Христа́ на сожже́ніє і напу́тствовани моли́твою твоє́ю, с ра́достію ідо́ша в огнь, пою́ще: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дів царю́ющий повелі́нія своя́ в тебі́ пренебреженни і увіща́нія презре́нни, обрати́ся к лука́вству, є́же ласка́нієм прельсти́ти тя, обіща́я полца́рства тебі́ да́ти. Ти же ві́ру сокро́вищам земни́м предпоче́тши і Жениха́ Христа́ возлюби́вши па́че земна́го ца́рства і оде́жду му́ченичества па́че багряни́ци, отве́ргла єси́ єго́ суєсло́віє. Сего́ ра́ди воспису́єм ті сія́ похва́льная:","Ра́дуйся, ді́во, лесть обличи́вшая;","ра́дуйся, запина́теля змі́я попра́вшая.","Ра́дуйся, дщер царе́ва;","ра́дуйся, ді́во, ря́сни злати́ми оді́янная.","Ра́дуйся, вся́коє вещество́ превозше́дшая;","ра́дуйся, на гору́ богови́дінія восте́кшая.","Ра́дуйся, сві́том богопозна́нія просвіще́нная;","ра́дуйся, труба́ ду́ха, воспе́вшая глас і́стиннаго богосло́вія.","Ра́дуйся, до́броє ві́ри іспові́даніє;","ра́дуйся, сві́та єва́нгельськаго сія́ніє.","Ра́дуйся, зако́нов ві́чних храни́тельнице;","ра́дуйся, на́ша помо́щнице.","Ра́дуйся, Єкатери́но, неві́сто Христо́ва прему́драя."]},{"h":"Кондак 6","ps":["Пропові́дником богоно́сним, апо́столом поревнова́вши, дерзнове́нно пред лице́м мучи́теля пропові́дала єси́ Христа́, і́стиннаго Бо́га, Єму́же в ра́нах і в темни́ці пі́ла єси́: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́вий в се́рдці твоє́м світ і́стиннаго богоразу́мія отгна́л єсть мрак скорбе́й, і́же не оста́ви тя алка́ти, голуби́цею пи́щу ті посила́я, ніже́ стужа́ти о болі́зні, посіти́л бо Сам тя в темни́ці, ободря́я і мно́гі вінці́ обіщава́я. Ти же, терпіливоду́шная, сим па́че укріпи́лася єси́ і цари́цю А́вгусту і воєво́ду Порфи́рія, с во́їни прите́кших к тебі́, обрати́ла єси́ к сві́ту ві́ри Христо́вой і научи́ла пі́ти тебі́ сія́:","Ра́дуйся, мирополо́жнице Боже́ственния любве́;","ра́дуйся, адама́нте крі́пкий.","Ра́дуйся, вино́ чуде́с неізрече́нних;","ра́дуйся, врага́ терпі́нієм уби́вшая.","Ра́дуйся, я́зви Го́спода на ті́лі своє́м носи́вшая;","ра́дуйся, цари́це А́вгусте с прише́дшими к му́ченичеському по́двигу путенаста́внице.","Ра́дуйся, я́ко во тьмі світ била́ єси́;","ра́дуйся, я́ко Сам Госпо́дь, Світ ми́ра, тебі́, в темни́ці би́вшей, Себе́ яви́л єсть.","Ра́дуйся, уз гріхо́вних ско́рая ріши́тельнице;","ра́дуйся, болі́знующих ско́рая ціле́бнице.","Ра́дуйся, помо́щнице на́шего спасе́нія.","Ра́дуйся, Єкатери́но, неві́сто Христо́ва прему́драя."]},{"h":"Кондак 7","ps":["Хотя́щу безбо́жному царю́ привести́ тя к ме́рзькому ідолослуже́нію, па́ки сі́ті подстила́єть тебі́, прему́драя, є́же улови́ти тя ле́стно похвало́ю красоти́ твоєя́; ти же красоту́ вещ привре́менну і скоропрехо́дну іменова́ла єси́, Христа́ же іспові́дала єси́ Бо́га жи́ва і і́стинна і пі́ла Єму́: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вую показа́ цар я́рость і безчелові́чіє, повелі́в єпа́рху коле́сами растерза́ти ді́вственноє, чи́стоє і свято́є ті́ло твоє́, но чуде́сно руко́ю А́нгела а́біє разріше́на била́ єси́ безвре́дна і колеса́ на ча́сти сокруше́ни, і́миже мно́гі от неві́рних убіє́ни, я́ко удиви́ся сам цар і предстоя́щий наро́д, і́же і взива́ше: «Вели́к Бог христия́нський». Ми же, чудя́щеся сему́, взива́єм тебі́:","Ра́дуйся, му́ченице, А́нгелом честна́я і гові́йная;","ра́дуйся, сла́во полко́в страда́льчеських.","Ра́дуйся, сві́тлая на враги́ побі́да;","ра́дуйся, страх неві́рних.","Ра́дуйся, сосу́де мно́жайшия си́ли Бо́жия;","ра́дуйся, ра́дованіє ві́рних.","Ра́дуйся, Єкатери́но, неві́сто Христо́ва прему́драя."]},{"h":"Кондак 8","ps":["Стра́нноє сла́ви ізміне́ніє і за Христа́ страда́ніє цари́ці і воєво́ди с во́їни ви́дівше, устрані́мся любве́ ми́ра і пло́ті і впери́м себі́ к разумі́нію Бо́га, Сей бо єсть красота́, і сла́ва, і віне́ць нам, пою́щим: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь сла́дость, весь жела́ніє тебе́, свята́я Єкатери́но, бисть Ісу́с: сла́дці бо Єго́ ра́ди го́ркія му́ки терпі́ла єси́ і ски́петр, предлага́ємий тебі́, попра́ла єси́, предзря́щи бу́дущеє воздая́ніє. От нас же прийми́ похва́льная сія́:","Ра́дуйся, чи́стая, чи́сті Чи́стаго возлюби́вшая;","ра́дуйся, го́рлице, Кра́снаго Жениха́ в пусти́ні до́льнаго ми́ра вожделе́вшая.","Ра́дуйся, воню́ риз Єго́ благоуха́вшая;","ра́дуйся, я́ко се́рна на гора́х арома́тських іска́вшая Рожде́ннаго пре́жде холмо́во ві́чних.","Ра́дуйся, по́двиг страда́льчеський ра́ди любве́ Христо́ви соверши́вшая;","ра́дуйся, лик му́ченичеський Бо́гу приве́дшая.","Ра́дуйся, я́ко виті́ї тобо́ю получи́ша Ца́рство Небе́сноє;","ра́дуйся, я́ко то́єже тобо́ю получи́ти ча́єм.","Ра́дуйся, покро́ве і забра́ло на́ше.","Ра́дуйся, Єкатери́но, неві́сто Христо́ва прему́драя."]},{"h":"Кондак 9","ps":["Все єстество́ а́нгельськоє возра́довася ра́достію, зря тя, Єкатери́но, побіди́вши мироде́ржця, ше́ствующую к преми́рним я́ко побідоно́сную воєво́ду, в послі́дованії полка́ страда́льчеськаго, і воспі́ побі́дная, взива́я: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́ї многовіща́ннії заусти́шася: не возмо́гше бо противовеща́ти богодухнове́нним словесе́м твої́м, молча́нієм почита́ють дарова́нія твоя́; ми же, немощні́ї, ка́ко мо́жем отве́рсти уста́ на хвали́ твоя́? Одна́ко дерза́єм і мо́лим, сподо́би, блага́я, безбі́дно принести́ тебі́ піснь сію́:","Ра́дуйся, орга́не Ду́ха Свята́го;","ра́дуйся, заре́ неізрече́ннаго осія́нія.","Ра́дуйся, догма́тов Боже́ственних пучи́но;","ра́дуйся, хи́тросте, препре́вшая филосо́фов.","Ра́дуйся, ча́ше прему́дрости;","ра́дуйся, плете́нія виті́й растерза́вшая.","Ра́дуйся, плени́ці гріхо́вния разріша́ющая.","Ра́дуйся, Єкатери́но, неві́сто Христо́ва прему́драя."]},{"h":"Кондак 10","ps":["Спасти́ хотя́щи ду́шу твою́, о ті́лі твоє́м неради́ла єси́, Єкатери́но, і на ме́чноє усіче́ніє, мучи́телю да́вшу на то ізрече́ніє, ти ра́достно потекла́ єси́, пою́щи Свято́му Безсме́ртному: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ тве́рда і непреодоли́ма яви́лася єси́ жена́м, тебі́ на мі́сто усіче́нія провожда́ющим і с рида́нієм тя жестокосе́рду к себі́ і безразсу́дну би́ти імену́ющим: я́ко не пощади́ла єси́ сла́дкаго живота́ в цві́те ю́ности, я́ко презрі́ла єси́ земно́є предлага́ємоє ца́рство і блаже́нство. Ти же воспрети́ла єси́ неполе́зний плач їх і суєсло́віє, теку́щи скорі́йше соєдини́тися чрез смерть со свої́м Возлю́бленним, того́ ра́ди сли́шиши:","Ра́дуйся, ра́достно за Главу́ Це́ркве Христа́ под меч главу́ свою́ приклони́вшая;","ра́дуйся, до конця́ претерпі́вшая.","Ра́дуйся, тече́ніє до́брі сконча́вшая;","ра́дуйся, я́ко ні ско́рбію, ні ра́нами, ні мече́м с путі́ Христо́ва іспові́данія не соврати́лася єси́.","Ра́дуйся, я́ко пла́мень любве́ в істо́чниці кро́ве неугаси́м соблю́дшая;","ра́дуйся, му́чеников красото́.","Ра́дуйся, крі́пкоє христия́н прибі́жище.","Ра́дуйся, Єкатери́но, неві́сто Христо́ва прему́драя."]},{"h":"Кондак 11","ps":["Пі́ніє похва́льноє дерзну́хом принести́ тебі́, но оскудіва́єть сло́во на́ше і недоуміва́єть ум, ка́ко глаго́лати; оба́че сло́во твоє́ прему́дроє, мно́гих ісхити́вшеє от неві́жества і ідолонече́стія, возставля́єть нас. Даждь нам сло́во твоє́, во є́же пі́ти уди́вльшему на тебі́ вели́чія Своя́ Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоприє́мную тя свіщу́, ме́чним усіче́нієм погаше́нную, но на сві́щниці Небе́снім пред Престо́лом Святи́я Тро́йці поста́вленную, ви́дівше Святі́ї А́нгели, поклони́шася Живу́щему во ві́ки і, получи́вше от Влади́ки повелі́ніє, ді́вственноє ті́ло твоє́ на горі́ Сина́йстій погребо́ша, да не ви́димо бу́деть, я́коже сама́ хоті́ла єси́, враго́м Госпо́днім. Ми же піснь сію́ возсила́єм ті:","Ра́дуйся, солнцеобра́зная ді́во, на Небеса́ ду́хом возше́дшая;","ра́дуйся, Сіо́на Го́рняго дости́гшая.","Ра́дуйся, ві́нче добро́ти в ру́ці Госпо́дні;","ра́дуйся, ча́ше, от оби́лія до́му Бо́жия че́рплющая ра́дость.","Ра́дуйся, к ски́нії нерукотворе́нней, ві́чній прибли́жившаяся;","ра́дуйся, на горі́ зако́нній почива́ющая ті́лом.","Ра́дуйся, я́ко та́мо ви́діна би́ша ше́ствія Бо́га Сина́їна, Бо́га Іа́ковля;","ра́дуйся, мі́ста богови́дінія Мойсе́єва одержа́ніє.","Ра́дуйся, ре́вности Іліїни́ указа́ніє;","ра́дуйся, купини́ несгора́ємой явле́ніє.","Ра́дуйся, ді́во, Ді́ві Цари́це, в ри́зи позлаще́нни оде́янной, преіспещре́нной всле́дствующая;","ра́дуйся, я́ко тобо́ю Сий воспіва́ється посреді́ дів тимпа́нниць.","Ра́дуйся, я́ко на тебі́ велелі́пота Єго́;","ра́дуйся, Престо́ла Ві́чнаго предстоя́тельнице.","Ра́дуйся, от хра́ма вселе́нния моли́твенники к тебі́ назира́ющая;","ра́дуйся, кади́ло моли́тв Ви́шнему о нас благоприя́тноє.","Ра́дуйся, Єкатери́но, неві́сто Христо́ва прему́драя."]},{"h":"Кондак 12","ps":["Благода́ть дана́ тебі́ от Бо́га руково́дствовати к позна́нію і́стини Єго́, в та́йні сокрове́нній, і дая́ти всім я́же к по́льзі проше́нія. Ті́мже ми, помраче́ннії, умиле́нно про́сим тя, му́драя ді́во: просвіти́ у́мния на́ші о́чі і положи́ нам к Небесі́ стезю́ прохо́дну, да поє́м с тобо́ю ни́ні і во вся ві́ки Єди́ному Прему́дрому: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще крі́пкия твоя́ му́ченичеськия по́двиги, хва́лим тя, я́ко одушевле́нний сосу́д спасе́нія челові́ков: твої́м бо ра́зумом Бог прему́дрость прему́дрих ві́ка сего́ погуби́; тобо́ю виті́й призва́ в язи́к свят, в лю́ди обновле́нія, я́ко тім страда́ти за Христа́. Просвіти́ і нас, блага́я ді́во, помраче́нних, да зове́м ті:","Ра́дуйся, зерца́ло Бо́жия му́дрости;","ра́дуйся, си́лою Ви́шняго оді́янная.","Ра́дуйся, подви́жнице, єле́єм ра́дованія умаще́нная;","ра́дуйся, воєво́до, полк Бо́жий к ві́чному вели́честву предпосла́вшая.","Ра́дуйся, во сві́тлості святи́я вше́дшая;","ра́дуйся, во сві́ті непристу́пнім Живу́щему в ли́ці пла́менних слуг предста́вшая.","Ра́дуйся, гром трисвята́го пі́нія гла́сом свої́м умножа́ющая;","ра́дуйся, неізрече́нную сла́дость добро́ти вкуша́ющая.","Ра́дуйся, я́ко хвала́ і ра́дованіє над главо́ю твоє́ю;","ра́дуйся, я́ко ві́чная сла́ва тебі́ об'є́млеть.","Ра́дуйся, от Триіпоста́снаго Божества́ вінце́м Небе́снаго Ца́рствія увінча́нная;","ра́дуйся, благода́ті і безконе́чной сла́ви нам хода́тайце.","Ра́дуйся, Єкатери́но, неві́сто Христо́ва прему́драя."]},{"h":"Кондак 13","ps":["О свята́я великому́ченице Єкатери́но! Прийми́ сіє́ похва́льноє пі́ніє і ізба́ви нас от враг ви́димих і неви́димих і от ві́чнаго муче́нія твої́м благоприя́тним хода́тайством сохрани́, да с тобо́ю при́сно поє́м Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелом ра́вную чистоту́ іму́щи, свята́я ді́во Єкатери́но, с А́нгели Боже́ственнаго озаре́нія сподо́билася єси́, с ни́ми же воспіва́ющи Трисвяту́ю піснь, усли́ши нас, пою́щих тебі́ на землі́ сія́:","Ра́дуйся, честно́є святи́ні жили́ще;","ра́дуйся, чуде́сноє зна́меніє сби́вшагося на тебі́ Бо́жия Про́мисла.","Ра́дуйся, благоволе́нія О́тча сосу́де;","ра́дуйся, страда́ній Христо́вих ісполне́ніє.","Ра́дуйся, чи́стоє Ду́ха Свята́го обита́лище;","ра́дуйся, сві́том благочести́вия ві́ри просвети́вшаяся.","Ра́дуйся, свято́ю купі́лію отрожде́нная;","ра́дуйся, ізми́вшая ри́зи своя́ в Кро́ві А́гнчей на землі́.","Ра́дуйся, лику́ющая с свяще́нними ді́вами на Небесі́.","Ра́дуйся, Єкатери́но, неві́сто Христо́ва прему́драя."]},{"h":"Кондак 1","ps":["Ізбра́нную і венча́нную ді́ву му́ченицю, неві́сту Христо́ву Єкатери́ну, похва́льними пі́сньми воспої́м, я́ко пресла́вную мучи́теля победи́тельницю і прему́друю филосо́фов наста́вницю: ти же, великому́ченице Єкатери́но, іму́щи дерзнове́ніє ко Го́споду, приклони́ся ми́лостивне к благопотре́бним проше́ніям зову́щих ті:","Ра́дуйся, Єкатери́но, неві́сто Христо́ва прему́драя."]},{"h":"Молитва","ps":["О свята́я Єкатери́но, ді́во і му́ченице, і́стинная Христо́ва неві́сто! Мо́лим тя чрез особли́вую благода́ть, є́юже предвари́ тя Жени́х твой, Сладча́йший Ісу́с: я́коже посрами́вши пре́лести мучи́теля, му́дростію твоє́ю п'ятьдеся́т виті́й побіди́ла єси́ і, напоі́вши їх Небе́сним уче́нієм, к сві́ту і́стинния ві́ри наста́вила єси́, та́ко іспроси́ і нам о́ную Бо́жию му́дрость, да і ми, расто́ргнувше вся ко́зні а́дськаго мучи́теля і презрі́в ми́ра і пло́ті собла́зни, досто́йни яви́мся Боже́ственния сла́ви і к разшире́нію святи́я на́шея правосла́вния ві́ри сосу́ди досто́йни соді́лаємся, і с тобо́ю в Небе́сній ски́нії Го́спода і Влади́ку на́шего Ісу́са Христа́ хва́лим і прославля́єм во вся ві́ки. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Доброді́тельми, я́ко луча́ми со́лнечними, / просвіти́ла єси́ неві́рния мудреці́. / І, я́коже пресві́тлая луна́ ходя́щим в нощі́ / неві́рія тьму отгна́ла єси́, / і цари́цю уві́рила єси́, / вку́пі же і мучи́теля обличи́ла єси́, / Богозва́нная неві́сто блаже́нная Єкатери́но, / жела́нієм востекла́ єси́ в Небе́сний черто́г / к прекра́сному Жениху́ Христу́, / і от Него́ ца́рським вінце́м вінча́лася єси́: / Єму́же, со А́нгели предстоя́щи, / за ни моли́ся, // творя́щия пречестну́ю па́м'ять твою́."]},{"h":"Кондак, глас 2","ps":["Лик честни́й Боже́ственні мучениколю́бці, / воздви́гніте ни́ні, почита́юще всему́друю Єкатери́ну, / сія́ бо в три́знищі Христа́ пропові́да, // і змі́я попра́, ри́торов ра́зуми укроти́вши."]},{"h":"Інший кондак, глас 3","ps":["Вити́йствующи днесь, Єкатери́на му́чениця / і виті́ям обличи́ умовре́дную є́ресь, / А́нгел бо с Небесе́ к той приї́де, си́лу от Ви́шняго принесе́, / ю́же приє́мши, му́жеськи рече́: // Христо́с єсть му́чеником похвала́."]},{"h":"Величання","ps":["Велича́єм тя, страстоте́рпице Христо́ва Єкатери́но, і чтим честно́є страда́ніє твоє́, є́же за Христа́ претерпі́ла єси́."]}],"notes":[]},{"u":"Акафіст праведному Артемію Веркольському, чудотворцю","e":"Akathist to the Righteous Artemius of Verkola, the Wonderworker","secs":[{"h":"Кондак 1","ps":["Ізбра́нному пра́веднику, ди́вному предста́телю пред Бо́гом, пресві́тлому світи́льнику сі́верния страни́ на́шея, боголюби́вому і боголюбе́зному о́троку Арте́мію, благоде́тельними чудотворе́ніями утеша́ющему і наставля́ющему покланя́ющихся с ві́рою святі́й ра́ці твоє́й, благода́рственная воспису́юще, ра́достно і торже́ственно взива́єм:","Ра́дуйся, предста́телю наш, Арте́міє пра́ведний."]},{"h":"Ікос 1","ps":["А́нгельський нрав і ду́шу непоро́чную імі́я от святи́я купі́лі креще́нія, ізбі́гл єси́ оби́чних сві́та сего́ су́єтств і собла́знов, чужд бил єси́ претика́ній і паде́ній, вта́йні чи́стим се́рдцем моля́ся к Єди́ному Всеблаго́му Бо́гу, ми́лостиво взира́ющему на кро́тких і смире́нних. Сего́ ра́ди єдиногла́сно вопіє́м ті:","Ра́дуйся, между́ челові́ками ди́вноє явле́ніє святи́ні;","Ра́дуйся, Отцю́ Небе́сному возлю́бленний.","Ра́дуйся, Си́ну Бо́жию вожделі́нний;","Ра́дуйся, Свято́му Ду́ху сосу́де драги́й і чи́стий.","Ра́дуйся, Цари́ці Небе́сния пла́менний почита́телю;","Ра́дуйся, святи́м А́нгелам і́стинний дру́же і єдинонра́вниче.","Ра́дуйся, пра́ведникам святи́м всім слико́вниче;","Ра́дуйся, Це́ркве Христо́вой украше́ніє.","Ра́дуйся, ді́лателю благи́й, в ма́лі ві́рний, над мно́гим поста́вленний;","Ра́дуйся, вше́дий в ра́дость Го́спода твоєго́.","Ра́дуйся, нося́й віне́ць нетлі́нія;","Ра́дуйся, просла́вленний от Го́спода Бо́га дарова́нієм ісціле́ній.","Ра́дуйся, предста́телю наш, Арте́міє пра́ведний."]},{"h":"Кондак 2","ps":["Ви́дя чистоту́ се́рдця твоєго́ благопромисли́тель Бог, призира́ющий всеви́дящим о́ком Свої́м на всю твар, іспо́лни ду́шу твою́ благода́ті Своєя́ от чре́ва ма́тере. Прославля́я у́бо Єго́ ди́вноє і благо́є о тебі́ промишле́ніє, поє́м о тебі́ хвале́бно: Аллилу́я."]},{"h":"Ікос 2","ps":["Вкуси́во во мла́дости блаже́ннаго житія́ твоєго́ сла́дость Боже́ственния благода́ті, чужди́й мирськи́я уті́хи отроко́в, ти бил єси́ потає́нний се́рдця челові́к в нетлі́нном украше́нії кро́ткаго і молчали́ваго ду́ха, є́же єсть, по Апо́столу, пред Бо́гом многоці́нно. Прийми́ у́бо от півце́в твої́х хвалу́ сію́:","Ра́дуйся, смире́ннаго і благода́тнаго о́трочества Христо́ва подража́телю;","Ра́дуйся, благода́ті Бо́жієй храни́телю.","Ра́дуйся, роди́телей твої́х почита́телю;","Ра́дуйся, в дому́ о́тчем о́браз кро́тости і послуша́нія.","Ра́дуйся, све́рстников твої́х примі́р благонра́вія;","Ра́дуйся, храни́телю чистоти́ се́рдця.","Ра́дуйся, сокруше́нія серде́чнаго таї́нниче;","Ра́дуйся, прия́тноє благоуха́ніє духо́внаго умиле́нія.","Ра́дуйся, не приі́мшій іску́са мирськи́х сласте́й;","Ра́дуйся, от гріхо́вних страсте́й свобо́ду улучи́вий.","Ра́дуйся, благогові́йноє отроча́, стяжа́вшеє ду́ха стра́ха Бо́жия;","Ра́дуйся, боголюбе́зноє ча́до, па́че жи́зні твоєя́ возлюби́вшеє Христа́ Бо́га.","Ра́дуйся, предста́телю наш, Арте́міє пра́ведний."]},{"h":"Кондак 3","ps":["Си́лою Всесвята́го Ду́ха укрепле́нний, блаже́нне Арте́міє, прия́в несокруши́мий щит ві́ри, і непобіди́моє ору́жіє ‒ животворя́щий Крест Христо́в, зна́меніє стра́шноє для злих духо́в, сохрани́л єси́ себе́ ці́ла і невреди́ма от злоко́зненних сих враго́в, поя́ Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я всегда́ і во всем упова́ніє на Бо́га Промисли́теля, і в убо́гом о́тчем дому́ пребива́я, в по́ті лиця́ твоєго́ приобрета́л єси́ пропита́ніє; но лише́нний земни́х благ, по во́лі Бо́жієй, яви́лся єси́ прича́стником ві́чних небе́сних благ, пра́ведне Арте́міє. Похваля́я у́бо твою́ нищету́, лише́нія і ну́жди, приве́тственно вопіє́м ті:","Ра́дуйся, о́браз кро́тости і трудолю́бія нам яви́вий;","Ра́дуйся, нищету́ нас ра́ди обнища́вшаго Христа́ Бо́га возлюби́вий.","Ра́дуйся, жите́йських зол неприча́стний;","Ра́дуйся, грехолю́бних кори́стей чужди́й.","Ра́дуйся, за лише́ніє земно́є уті́шенний ра́йськими наслажде́ніями;","Ра́дуйся, за кро́тость і смире́ніє, наслі́дниче Ца́рствія Небе́снаго.","Ра́дуйся, за ну́жди вре́менния сподо́бивийся ізоби́лія благ ві́чной несконча́ємой ра́дости;","Ра́дуйся, за чистоту́ се́рдця удосто́ївийся лицезре́ть Бо́га вку́пі со святи́ми а́нгели.","Ра́дуйся, не прилага́вий се́рдця к бла́гам ми́ра сего́ преходя́щим;","Ра́дуйся, іска́вий небе́сних нетлі́нних благ в моли́тві дома́шней і церковной, і в обще́нії Та́їн Христо́вих.","Ра́дуйся, іспо́лненний Боже́ственния любве́;","Ра́дуйся, прича́стниче безсме́ртния трапе́зи.","Ра́дуйся, стяжа́вий смире́нієм висо́кая і нището́ю бога́тая, по подража́нію святи́телю Никола́ю;","Ра́дуйся, хра́ма єго́ в жи́зні твоє́й моли́твенник би́вий.","Ра́дуйся, от Го́спода Бо́га на Небесі́х мзду мно́гу приє́мий.","Ра́дуйся, предста́телю наш, Арте́міє пра́ведний."]},{"h":"Кондак 4","ps":["Бу́ря страсте́й і треволне́ній жите́йських не пости́же тя, імі́ющаго в се́рдці твоє́м мир Бо́жий, всели́вийся бога́тно в тя, блаже́нне Арте́міє; ві́три непостоя́нних уче́ній не волнова́ша ми́рния душі́ твоєя́. Сего́ ра́ди явля́я, я́ко Іо́сиф, мир бра́тії твоє́й, прове́л єси́ дні живота́ твоєго́ в ми́рі, тишині́ і безмо́лвії, і мир Бо́жий, обита́ющий в глубині́ ду́ха твоєго́, возбужда́ше пі́ти тя непреста́нно Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Слу́шая от зако́на Бо́жия словеса́ жи́зні ві́чния, імі́я пома́заніє от Свята́го Ду́ха, ві́дал єси́ благи́м чу́вством вся, не тре́буя, да кто учи́ть тя, но я́ко то само́ пома́заніє уча́ше тя о всем, по сло́ву возлю́бленнаго ученика́ Христо́ва; воскрили́вся же Боже́ственним дарова́нієм, отроча́ мла́до, возне́слся єси́ на висоту́ христия́нськаго благоче́стія і кро́тости, Бо́гу возлю́бленне Арте́міє. Сего́ ра́ди ди́вноє о тебі́ смотре́ніє Бо́жиє сла́в'яще, со дерзнове́нієм вопіє́м ті:","Ра́дуйся, спаси́тельнаго внима́нія себі́ ди́вний нам примі́р;","Ра́дуйся, молча́нія о́браз.","Ра́дуйся, му́дрости духо́вния сві́тлоє зерца́ло;","Ра́дуйся, істо́чниче ісціле́ній.","Ра́дуйся, чудотво́рче преди́вний;","Ра́дуйся, сокро́вище цілому́дрія.","Ра́дуйся, цві́те чистоти́ і незло́бія;","Ра́дуйся, неви́нности сосу́де.","Ра́дуйся, цві́те А́нгельськия пра́ведности;","Ра́дуйся, многоці́нний ка́меню ра́йськия жи́зні.","Ра́дуйся, сія́ніє небе́сних сві́тлостей.","Ра́дуйся, предста́телю наш, Арте́міє пра́ведний."]},{"h":"Кондак 5","ps":["Живоно́сний ток благода́ті Христо́вой восприя́в благи́м і до́брим се́рдцем, пра́ведне Арте́міє, устреми́лся єси́ соверше́нне в слід Христа́ Спаси́теля на́шего, і восхища́ясь бога́тством бла́гости, прему́дрості і человіколю́бія Бо́жия, явле́ннаго в іскупле́нії грі́шнаго челові́чества, пламені́л єси́ любо́вію к Спаси́телю на́шему, і во умиле́нії се́рдця воспіва́л єси́ Єму́: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше купножи́тели твої́ преспіва́юща тя благоче́стієм і ра́зумом, пра́ведне Арте́міє, прославля́ху благоволе́ніє Бо́жиє, утаєва́ющеє от прему́дрих і разу́мних бога́тство благода́ті і ві́дінія єя́, по сло́ву Спаси́теля, і открива́ющеє та младе́нцем. Ті́мже і ми, ра́дующеся написа́нію і́мені твоєго́ на Небесі́х, с утіше́нієм возно́сим тебі́ хвале́бния пі́сні:","Ра́дуйся, ізбра́нний сосу́де Бо́жия благода́ті;","Ра́дуйся, прия́телище даро́в Ду́ха Свята́го.","Ра́дуйся, іспо́лненний дарова́нія чуде́с ісціле́ній;","Ра́дуйся, ви́шнія прему́дрости Бо́жієй приє́мниче.","Ра́дуйся, ра́зума духо́внаго сокро́вище;","Ра́дуйся, благи́й для нас сове́тниче.","Ра́дуйся, іспо́лненний спаси́тельнаго ві́дінія;","Ра́дуйся, пла́меню любве́ неугаси́мий.","Ра́дуйся, всесві́тлая звіздо́, блиста́ющая на тве́рди церко́вній;","Ра́дуйся, отра́да печа́льним.","Ра́дуйся, немощству́ющих врачу́;","Ра́дуйся, обурева́ємих помо́щниче.","Ра́дуйся, предста́телю наш, Арте́міє пра́ведний."]},{"h":"Кондак 6","ps":["Пропові́дник пе́рвий просла́вленнаго ті́ла твоєго́, кли́рик це́ркві святи́теля Никола́я, іща́ в лесно́й ча́ще плодо́в земни́х, обрі́те сокро́вище неоціне́нноє, нетлі́нния мо́щі твоя́, пра́ведне Арте́міє, чрез три́десять три лі́та не поврежде́нния преме́нами стихі́й, і с благода́рним чу́вством прекло́нь колі́на, восклиця́ше к Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́ в пусти́нном мі́сті де́бри лесни́я, я́коже у́тренняя звізда́ после мра́ка нощна́го, і просвіти́л єси́ ско́ро населе́ніє градо́в, дре́внія Кевро́ли, Пи́неги, Арха́нгельська, Во́логди і дале́ких стран, сія́нієм благоді́тельних чуде́с твої́х. І ни́ні нікто́же умолчи́ть вопи́ти тебі́:","Ра́дуйся, світи́ло вели́коє, тьму неві́дінія просвіща́ющеє;","Ра́дуйся, сокро́вище духо́вноє, ві́рних богатя́щеє.","Ра́дуйся, чи́стая струя́ благода́ті Бо́жієй;","Ра́дуйся, страні́ твоє́й сі́верній сла́ва і утвержде́ніє.","Ра́дуйся, я́коже чи́стий А́нгел, пою́щий пі́сні богокра́сния, і руководя́щий к тому́ оби́тель твою́;","Ра́дуйся, чи́стая пти́ця, в гні́зда Небе́сная прия́тая.","Ра́дуйся, я́блоко благово́нноє, ві́рних ду́ші благоуха́ющеє;","Ра́дуйся, прекра́сная ли́ліє, сердца́ ві́рних услажда́ющая.","Ра́дуйся, млада́я вітв ра́йськаго дре́ва, ізрасти́вшая сла́дкий плод духо́вний Пресвяті́й Тро́йце;","Ра́дуйся, правосла́внаго уче́нія лучу́ немерца́ющий.","Ра́дуйся, ма́слино Це́ркве Христо́ви, істоча́ющая нам ди́вний єле́й ми́лости Бо́жієй.","Ра́дуйся, лозо́ виногра́дная, отра́дним упова́нієм на спаси́тельния обітова́нія нас напая́ющая;","Ра́дуйся, смоко́вниці, сла́достію своє́ю гріхо́вную го́реч отража́ющая.","Ра́дуйся, предста́телю наш, Арте́міє пра́ведний."]},{"h":"Кондак 7","ps":["Хотя́щу Всеви́шнему Мироправи́телю призва́ти Своєго́ пра́ведника в Небе́сния ски́нії, ма́нієм от престо́ла велелі́пния Єго́ сла́ви, возшуме́ над земле́ю бу́ря, стра́шно возгремі́ша гро́ми, возблиста́ і разлія́ся ужа́сно, я́ко пла́мень, мо́лнія, і в прикоснове́нії у́жаса ко вну́тренним чу́вством ю́наго о́трока, взята́ бисть А́нгелами душа́ пра́ведника, срета́ємая безпло́тними си́лами, ра́дующимися о дру́гі своє́м, і во весе́лії воспе́вшими Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Ди́вно бисть твоє́ призва́ніє в Небе́сний Ієрусали́м; от земна́го бо труда́ на ло́но Авраа́мово, і от малолю́днаго мі́ста в преми́рную сла́ву вели́чественно перенесена́ бисть блаже́нная душа́ твоя́, пра́ведне Арте́міє, возду́ху шум'я́щу, громо́м і мо́лніям свирепе́ющим, і вода́м от движе́нія ві́тра, я́ко рука́ми, пле́щущим. Ті́мже і ми, лику́я, воспоє́м:","Ра́дуйся, но́вий о нас к Бо́гу предста́телю;","Ра́дуйся, во ві́чний покро́в Присноде́вствующия Цари́ці вше́дий.","Ра́дуйся, А́нгелом собесі́дниче;","Ра́дуйся, Рая́ Небе́снаго жи́телю.","Ра́дуйся, безстра́стія наслі́дниче пра́ведний;","Ра́дуйся, свиді́телю нам жи́зні безсме́ртния.","Ра́дуйся, ізбежа́вий возду́шних істяза́телей, пораже́нних стріла́ми мо́лнії при твоє́м отше́ствії на Не́бо;","Ра́дуйся, не узре́вший ме́рзьких де́монських зра́ков.","Ра́дуйся, ра́йськая вітв, благоуха́нієм веселя́щая;","Ра́дуйся, благово́нная єде́мськая ро́за, ду́ші на́ша благоуха́ющая.","Ра́дуйся, прекра́сний гро́зде на трапе́зі Царе́вой положе́нний;","Ра́дуйся, те́плий наш моли́твенниче.","Ра́дуйся, предста́телю наш, Арте́міє пра́ведний."]},{"h":"Кондак 8","ps":["Стра́нно і недоумі́нно твоє́ воспита́ніє, пра́ведниче; ра́зума бо Бо́жия іспо́лнился єси́, і святи́ні Ду́ха дости́гл єси́, ні от кого́ же із челові́к учи́вшися; сокрове́но от совреме́нников і ди́вно їм бисть твоє́ в ю́них лі́тіх благоче́стіє і преставле́ніє твоє́. Но чу́дния твоя́ ісціле́нія, і разли́чния чудоді́йствія возно́сять на́ші гла́си к славосло́вію о тебі́ Бо́жию, є́же непреста́нно і ра́достно пі́ти: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь бил єси́ в Бо́гі богоми́слієм, і укріпля́ємий Бо́жієй благода́тію непристу́пен яви́лся єси́ кова́рному змі́ю, наблюда́ющему п'я́ту ше́ствующих ті́сним путе́м. Руководи́ у́бо і нас непреткнове́нно ходи́ти путе́м за́повідей Христо́вих, да благода́рно вопіє́м ті:","Ра́дуйся, путеводи́телю наш ди́вний;","Ра́дуйся, кро́ткий наста́вниче всіх спаса́ємих.","Ра́дуйся, пе́рсті Бо́жий, указу́ющий нам го́рняя;","Ра́дуйся, глас небе́сний, зову́щий всіх на по́двиги спасе́нія.","Ра́дуйся, чи́стая голуби́це, іму́щая вітв ра́йськую;","Ра́дуйся, духо́вная ла́стовице, показу́ющая в нетлі́нії ве́сну гряду́щаго ві́ка.","Ра́дуйся, предста́телю наш, Арте́міє пра́ведний."]},{"h":"Кондак 9","ps":["Все єстество́ А́нгельськоє, в ра́достний тре́петь прише́д, воздаде́ хвалу́ Бо́гу: Свят, Свят, Свят, Госпо́дь Савао́ф, єгда́ неви́нная і чи́стая душа́ твоя́, неврежде́нная от мно́гих страхова́ній бісо́вських, і перенесе́нная в преми́рную жизнь, поклони́ся Трийпоста́сному Божеству́, воспі́вши Єму́ со всі́ми святи́ми: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́ї многослове́сниє, не могу́щії усмотре́ти о́ком ра́зума, омраче́ннаго го́рдостію і страстьми́, прему́дрости тво́рчеськия в устроє́нії вселе́нния, не мо́гуть уразумі́ти прославле́нія моще́й свята́го уго́дника Бо́жия. Ми же соверше́нною ві́рою в простоті́ се́рдця возглаша́єм тебі́, просла́вленний моли́твенниче наш:","Ра́дуйся, преда́вий ві́рним в зало́г любве́ нетлі́нния своя́ мо́щі;","Ра́дуйся, уверяющий нас в і́стині Воскресе́нія і жи́зні ві́чния.","Ра́дуйся, іспо́лнивий на себі́ сло́во Бо́жиє: храни́ть Госпо́дь вся ко́сті пра́ведних;","Ра́дуйся, утверди́вий ісполне́нієм сло́во Христа́ Бо́га: влас глави́ ва́шея не поги́бнеть.","Ра́дуйся, с че́стію принесе́нний із де́бри в правосла́вний храм для о́бщаго че́ствованія і поклоне́нія;","Ра́дуйся, свиді́тельствуємий от Го́спода Бо́га да́ром чудотворе́ній.","Ра́дуйся, я́ко чи́стая ра́ка святи́х моще́й і ни́ні привлека́єть сердца́ обе́тних страннолю́бцев на поклоне́ніє тебі́;","Ра́дуйся, яви́вий і́стину слове́с Писа́нія: «в па́м'ять ві́чную бу́деть пра́ведник», і «пра́ведник я́ко фі́нікс процвіте́ть, і я́ко кедр і́же в Лива́ні умно́житься».","Ра́дуйся, загражда́ющий уста́ пререка́ющая;","Ра́дуйся, обуздова́ющий язи́к неві́рія і хули́.","Ра́дуйся, смиря́ющий горди́ню дерза́ющим на святи́ню;","Ра́дуйся, ра́зум кичли́вий пленя́ющий в послуша́ніє Христо́вой ві́ри.","Ра́дуйся, в ду́хі блаже́нния простоти́ і незло́бія дости́гнувий Не́ба.","Ра́дуйся, предста́телю наш, Арте́міє пра́ведний."]},{"h":"Кондак 10","ps":["Спасти́ Хотя́щаго вся́каго челові́ка і́скренно моли́л єси́ наста́вити тя на путь спасе́нія, і благода́тію Бо́жиєю, озари́вшею тя, прише́л єси́ в Небе́сний Ієрусали́м, іді́же узрі́в лице́м к лицю́ Того́, Єго́же і́м'я, я́ко ми́ро ізлія́нноє, та́мо воспіва́єши непреста́нно сла́ву Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ тве́рда і несокруши́ма огра́да оби́телі, свято́му і́мені твоєму́ посвяще́нней, суть неуси́пния твоя́ к Бо́гу моли́тви, святи́й пра́ведний Арте́міє. Ті́мже живу́щії в ней благода́рно возно́сять к тебі́ гла́си:","Ра́дуйся, храни́телю наш крі́пкий;","Ра́дуйся, неуси́пний защи́тниче наш.","Ра́дуйся, наста́вники на́ша охраня́ющий от па́губних бі́дствій;","Ра́дуйся, іспуща́ющий на враго́в стрі́ли стра́ха.","Ра́дуйся, щі́те тве́рдий па́че мі́дянаго;","Ра́дуйся, броне́ пра́вди, отража́ющая каменомета́нія а́дських му́ринов.","Ра́дуйся, оби́телі мона́хов і всей страні́ на́шей похвало́ і утвержде́ніє.","Ра́дуйся, тружда́ющихся по́моще;","Ра́дуйся, молчали́вих і кро́тких ра́досте.","Ра́дуйся, больни́х ісціле́ніє;","Ра́дуйся, немощни́х укріпле́ніє.","Ра́дуйся, уни́лих бо́дросте;","Ра́дуйся, скорб'я́щих утіше́ніє.","Ра́дуйся, предста́телю наш, Арте́міє пра́ведний."]},{"h":"Кондак 11","ps":["Пі́ніє на́ше хвале́бноє тебі́, живу́щему во сла́ві Отця́ сві́тов, ни́ні возсила́ємоє, недосто́йно єсть, я́ко от нечи́стих усте́н возноси́моє; но сам прийди́ посреді́ нас, неіждива́ємий істо́чниче чистоти́ і цілому́дрія, очи́сти на́ша сердця́ і душі́ помишле́нія, да тебе́ ра́ди благоприя́тно бу́деть совоку́пноє на́ше восклиця́ніє Всеще́дрому Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Сві́том за́повідей Бо́жиїх озаре́нний ізмла́да, ско́ро возше́л єси́ к Трийпоста́сному Сві́ту, пред Ни́мже хода́тайствуєши і о на́шем просвіще́ніі, о не́мже умоля́юще, с любо́вію вопіє́м ті:","Ра́дуйся, звіздо́ невече́рняго сві́та;","Ра́дуйся, луче́ сві́та, согріва́ющий на́шу хла́дность.","Ра́дуйся, свіще́, просвіща́ющая на́шу темноту́;","Ра́дуйся, я́ко огнь возгрева́ющий нас к любві́ возлюби́вшаго нас Христа́ Бо́га.","Ра́дуйся, ми́сленно прикаса́яйся, я́ко угль, хла́дним сердця́м;","Ра́дуйся, злата́я лампа́до, возжже́нная для умилостивле́нія Пра́веднаго Судії́.","Ра́дуйся, світи́льниче духо́вний, освеща́ющий ві́рним путь спасе́нія;","Ра́дуйся, о́гненная пещ, пожига́ющая те́рніє гріхо́в на́ших.","Ра́дуйся, горни́ло, куря́щеє моли́твенний арома́ть;","Ра́дуйся, кади́ло іздаю́щеє ди́вноє смире́нія благоуха́ніє.","Ра́дуйся, горя́щий пла́меню, істребля́ющий нече́стіє.","Ра́дуйся, предста́телю наш, Арте́міє пра́ведний."]},{"h":"Кондак 12","ps":["Благода́ть Боже́ственную іспроси́ нам, святи́й уго́дниче Бо́жий, да при́сно покрива́єть нас от враго́во ви́димих і неви́димих, да научи́ть ни подража́ти тебі́ в чистоті́ А́нгельськой і незло́бії, да напра́вить сердця́ на́ша к смире́нію, покая́нію і неосла́бному ісполне́нію за́повідей Христо́вих; да да́руєть нам христия́нськую кончи́ну і безбі́дно проведе́ть нас чрез возду́шний путь, да сподо́бимся та́мо узрі́ти сла́ву Вели́каго Бо́га, і ві́чно пі́ти Єму́: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще тебі́ ни́ні, а́ще і недосто́йния, но усе́рдния хвали́ бре́нними і нечи́стими уста́ми, благогові́йно мо́лим тя, святи́й пра́ведний Арте́міє: при́зри на мно́гія на́ша не́мощі душе́вния і тіле́сния, і пода́ждь нам по́мощ к соверше́нію до́брих діл, і ко всегда́шнему прославле́нію свята́го твоєго́ і́мені, вопію́щим ті:","Ра́дуйся, во́їне Царя́ ца́рствующих;","Ра́дуйся, слуго́ Го́спода госпо́дствующих.","Ра́дуйся, ра́бе ві́рний Владі́ющаго вся́ким созда́нієм;","Ра́дуйся, вінча́нний вінце́м нетлі́нія от Самаго́ нетлі́ннаго Бо́га.","Ра́дуйся, украше́нний нетлі́нною дияди́мою Ца́рствія Христо́ва;","Ра́дуйся, облече́нний в блестя́щую порфи́ру за чистоту́ се́рдця і незло́біє.","Ра́дуйся, приє́мий от руки́ Бо́жия пе́рстень синоположе́нія;","Ра́дуйся, наслі́дниче Небе́снаго ві́чнаго Ца́рствія.","Ра́дуйся, предста́телю мо́щний, спобо́рствуяй правосла́вним на ра́тующих;","Ра́дуйся, вождю́, спосо́бствуяй неви́димо во бранеіх на́шему во́їнству.","Ра́дуйся, защища́ющий преді́ли на́шего Оте́чества тве́рдим щито́м твоєго́ покро́ва;","Ра́дуйся, спасе́нія на́шего споспі́шниче і хода́таю твої́ми ко Го́споду Бо́гу о нас грі́шних моли́твами.","Ра́дуйся, предста́телю наш, Арте́міє пра́ведний."]},{"h":"Кондак 13","ps":["О преди́вний уго́дниче Бо́жий і прелюби́мий чудотво́рче, Арте́міє! Мо́лим твою́ святи́ню, ми́лостив бу́ди святі́й оби́телі твоє́й, і всім призива́ющим тя с любо́вію і упова́нієм. По своє́й чистоті́ і пра́ведности, іспроси́ у Го́спода Бо́га проще́ніє на́ших прегріше́ній і ре́вность к до́брим діло́м, да про́чеє вре́м'я живота́ на́шего поживе́м во вся́ком благоче́стії і чистоті́, і да сподо́бимся на Стра́шном Суді́ одесну́ю ста́ти Судії́, Христа́ Бо́га на́шего, і во ві́ки віко́в с тобо́ю пі́ти человіколю́бцю Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгельський нрав і ду́шу непоро́чную імі́я от святи́я купі́лі креще́нія, ізбі́гл єси́ оби́чних сві́та сего́ су́єтств і собла́знов, чужд бил єси́ претика́ній і паде́ній, вта́йні чи́стим се́рдцем моля́ся к Єди́ному Всеблаго́му Бо́гу, ми́лостиво взира́ющему на кро́тких і смире́нних. Сего́ ра́ди єдиногла́сно вопіє́м ті:","Ра́дуйся, между́ челові́ками ди́вноє явле́ніє святи́ні;","Ра́дуйся, Отцю́ Небе́сному возлю́бленний.","Ра́дуйся, Си́ну Бо́жию вожделі́нний;","Ра́дуйся, Свято́му Ду́ху сосу́де драги́й і чи́стий.","Ра́дуйся, Цари́ці Небе́сния пла́менний почита́телю;","Ра́дуйся, святи́м Ангелам і́стинний дру́же і єдинонра́вниче.","Ра́дуйся, пра́ведникам святи́м всім слико́вниче;","Ра́дуйся, Це́ркве Христо́вой украше́ніє.","Ра́дуйся, ді́лателю благи́й, в ма́лі ві́рний, над мно́гим поста́вленний;","Ра́дуйся, вше́дий в ра́дость Го́спода твоєго́.","Ра́дуйся, нося́й віне́ць нетлі́нія;","Ра́дуйся, просла́вленний от Го́спода Бо́га дарова́нієм ісціле́ній.","Ра́дуйся, предста́телю наш, Арте́міє пра́ведний."]},{"h":"Кондак 1","ps":["Ізбра́нному пра́веднику, ди́вному предста́телю пред Бо́гом, пресві́тлому світи́льнику сі́верния страни́ на́шея, боголюби́вому і боголюбе́зному о́троку Арте́мію, благоде́тельними чудотворе́ніями утеша́ющему і наставля́ющему покланя́ющихся с ві́рою святі́й ра́ці твоє́й, благода́рственная воспису́юще, ра́достно і торже́ственно взива́єм:","Ра́дуйся, предста́телю наш, Арте́міє пра́ведний."]},{"h":"Молитва","ps":["Святи́й уго́дниче Бо́жий, пра́ведний Арте́міє, при́сний храни́телю святи́я ві́ри Правосла́вния і бли́зький защи́тниче всего́ сі́вернаго кра́я Россі́йськия страни́! При́зри ми́лостивно на усе́рдную моли́тву нас грі́шних і твої́м благомо́щним предста́тельством іспроси́ нам у Го́спода проще́ніє согріше́ній на́ших, преспі́яніє во ві́рі і благоче́стії і огражде́ніє от ко́зней дия́вольських. Моли́ Го́спода, да храни́ть во здра́вії і непреміня́ємім благополу́чії ві́рних люде́й Свої́х, да пода́сть страні́ на́шей мир і тишину́, а нам нелицемі́рноє послуша́ніє, да сподо́бит всіх нас получи́ти, по христия́нстій кончи́ні, Небе́сноє Ца́рствіє, іді́же всі пра́веднії вмі́сті с тобо́ю, ві́чно сла́в'ять Отця́ і Си́на і Свята́го Ду́ха. Амі́нь."]},{"h":"Тропар, глас 2","ps":["Ви́шняго повелі́нієм / тучено́сним облако́м не́бо помрачи́вшим / і мо́лніям блиста́ющим, / гро́му же возшумі́вшу с преще́нієм, / іспусти́л єси́ ду́шу твою́ в ру́ці Го́сподеві, / прему́дре Арте́міє, і ни́ні предстої́ши престо́лу Влади́ки всіх, / і́же ві́рою і любо́вію приходя́щим к тебі́, / подая́ ісціле́ніє всім неотло́жно / і моля́ся Христу́ Бо́гу // спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 8","ps":["Возсія́ днесь пресві́тлая па́м'ять прему́драго Арте́мія: / богода́нная благода́ть я́ко рі́ки ізлива́єть от святоцеле́бния ра́ки моще́й єго́ ди́вная ісціле́нія, / і́ми же от многоразли́чних неду́г ізбавля́ємся, / с ві́рою приє́млюще я, і взива́юще: // ра́дуйся, Арте́міє богому́дре."]},{"h":"Величання","ps":["Велича́єм тя, святи́й пра́ведний о́троче Арте́міє, і чтим святу́ю па́м'ять твою́, ти бо мо́лиши о нас Христа́, Бо́га на́шего."]}],"notes":[]},{"u":"Акафіст святому апостолу Андрію Первозваному","e":"Akathist to the Holy Apostle Andrew the First-Called","secs":[{"h":"Кондак 1","ps":["Первозва́ннаго апо́стола Христо́ва, Єва́нгелія Свята́го пропові́дника, Россі́йськия страни́ богодухнове́ннаго просвіти́теля, Андре́я пресла́внаго, пі́сньми восхва́лим, стоя́ще на версі́ холма́, іді́же Крест водрузи́ десни́ця єго́, і єму́ я́ко Це́ркве возсле́дователю верхо́вному, в слід себі́ указа́вшему єй путь ко Христу́, во умиле́нії воззове́м:","Ра́дуйся, Андре́є, апо́столе Христо́в Первозва́нний."]},{"h":"Ікос 1","ps":["А́нгел благові́стник А́гнця Христа́, взе́млющаго гріхи́ ми́ра, бил єси́ Андре́є апо́столе, і с Ним во ві́ки пребива́єши на небесі́; отону́дуже і при́зри на пі́нія, приноси́мая тебі́ во хра́мі твоє́м, на мі́сті, іді́же стоя́сте но́зі твої́, і я́ко бога́т сий благода́тію Бо́жиєю, пода́ждь нам сло́во бла́го, да зове́м ті:","Ра́дуйся, денни́це от гра́да Вифсаї́ди нам возсія́вшая;","ра́дуйся, равноче́стний бра́те верхо́внаго Петра́.","Ра́дуйся, учениче́ вели́каго Предте́чі Христо́ва;","ра́дуйся, пе́рвіє про́чих апо́стол зва́нний ко апо́стольському служе́нію от Самого́ Го́спода.","Ра́дуйся, я́ко і други́м с ра́достію воззва́л єси́: прийді́те, обріто́хом жела́ємаго Мессі́ю;","ра́дуйся, і нас к Нему́ же приводя́й.","Ра́дуйся, Андре́є, апо́столе Христо́в Первозва́нний."]},{"h":"Кондак 2","ps":["Учи́телю, гді живе́ши? — вопроси́л єси́, Андре́є, Спа́са душ на́ших і, с Ним преби́в день єди́н, возлюби́л єси́ на вся дні живота́ твоєго́ обре́теннаго тобо́ю Мессі́ю, і бра́та твоєго́ старі́йшаго приве́л єси́ к Нему́. Ті́мже і нас, я́ко ме́ньшую бра́тію твою́, к Нему́ же не преста́й влещи́, да і ми, послі́дующе стопа́м твої́м, вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Прови́дя в тебі́, святи́й Андре́є, ві́ри і любве́ пла́мень, Госпо́дь па́ки тя обрі́те на є́зері Геннисаре́тсті, я́ко ри́баря, ку́пно с бра́том твої́м, вмета́юща мре́жі во глубину́, і рече́ ва́ма: гряди́та по Мні, і Аз сотворю́ ви ловця́ челові́ком. — Ти же а́біє послі́довал єси́ Єму́ і богодухнове́нним сло́вом, я́ко мре́жею, челові́ки улови́л єси́ Христу́, с ни́миже і ми, уловле́ннії тобо́ю во спасе́ніє, віща́єм ті:","Ра́дуйся, я́ко от Самого́ Го́спода лови́тві духо́вній научи́лся єси́;","ра́дуйся, я́ко на том же є́зері с про́чими апо́столи обурева́єм бив, ві́рою спа́слся єси́ в Го́спода, запреща́ющаго ві́тром і мо́рю.","Ра́дуйся, стяжа́вий ве́лію ві́ру, єгда́ ви́діл єси́ пречу́дноє насище́ніє п'яти́ ти́сящ п'ятію́ хлі́бами;","ра́дуйся, дар прия́вий от Го́спода ціли́ти всяк неду́г і вся́ку болі́знь.","Ра́дуйся, я́ко глас с небесе́ сли́шан бисть е́ллином, Христа́ тобо́ю узре́вшим;","ра́дуйся, я́ко на горі́ Єлео́нстій открове́на би́ша і тебі́ гряду́щая при кончи́ні ми́ра.","Ра́дуйся, Андре́є, апо́столе Христо́в Первозва́нний."]},{"h":"Кондак 3","ps":["Стра́нствія Влади́чня і Безсме́ртния Трапе́зи на го́рнім мі́сті Сіо́на наслади́вся, я́ко ві́рний друг Христо́в, вку́пі с про́чими апо́столи узрі́л єси́ Го́спода і Бо́га твоєго́, от Него́же і Дух Свят прия́л єси́, во є́же в'яза́ти і ріши́ти гріхи́ людські́я. І па́ки, в то́йжде го́рниці Сіо́нстій, оби́льноє бисть на тя ізлія́ніє обітова́ннаго Ду́ха во о́гненних язи́ціх. Ті́мже вся племена́ удиви́шася, ка́ко язи́ком їх глаго́лал єси́ вели́чія Бо́жия, поя́: Аллилу́я."]},{"h":"Ікос 3","ps":["От Го́спода за́повідь приї́м пропові́дати Єва́нгеліє всей тва́рі, обте́кл єси́ мно́гія гра́ди і страни́, апо́столе Андре́є, призива́я лю́ди к позна́нію І́стиннаго Бо́га і крестя́ їх во і́м'я Отця́ і Си́на і Свята́го Ду́ха; с ни́миже і ми сподо́бихомся благода́ті креще́нія. Сего́ ра́ди благода́рственная воспису́єм ті:","Ра́дуйся, чуде́с Христо́вих провозві́стниче ві́рний;","ра́дуйся, свята́го Єва́нгелія пропові́дниче громогла́сний.","Ра́дуйся, і́дольськаго служе́нія потреби́телю;","ра́дуйся, і́стиннаго благоче́стія насади́телю.","Ра́дуйся, я́ко по сло́ву твоєму́ лю́діє водо́ю і Ду́хом возрожда́ються;","ра́дуйся, я́ко тобо́ю ві́рнії Безсме́ртния Трапе́зи причаща́ються.","Ра́дуйся, Андре́є, апо́столе Христо́в Первозва́нний."]},{"h":"Кондак 4","ps":["Си́ла Бо́жия осіни́ тя, апо́столе Первозва́нний, во є́же благовісти́ти си́лу і сла́ву Си́на Бо́жия і утвержда́ти вся ві́ровати во Святу́ю Тро́йцю призва́нния. Ті́мже у́бо і нас, покланя́ющихся Єди́ному в Тріє́х Іпоста́сіх Бо́гу, на зла́чней па́жити ві́ри Христо́ви соблюди́, да благода́тію Свята́го Ду́ха ви́ну освяща́ємії, велегла́сно поє́м Єму́: Аллилу́я."]},{"h":"Ікос 4","ps":["Приве́д ко Христу́ бра́та твоєго́ Си́мона Петра́, Первозва́нне, с ним ізше́л єси́ і на апо́стольськоє служе́ніє твоє́, пе́рвіє во Антіохі́ю і Сино́п, і та́мо побіди́в де́монов полки́, от уз темни́чних спу́тника твоєго́ апо́стола Матфі́я свободи́л єси́, і ю́зники с ним би́вшия крести́л, верхо́вному Петру́ отту́ду в за́падния страни́ теку́щу, ти бра́тнєє цілова́ніє дал єси́ єму́, сам же до́брі подвиза́лся єси́ на восто́ціх. Ті́мже і ми, лю́діє Це́ркве Восто́чния, блажи́м тя:","Ра́дуйся, си́ло Бо́жия, полки́ де́монов прогоня́ющая і у́зи темни́ць сокруша́ющая;","ра́дуйся, прия́телище благода́ті апо́стольськія, от а́дових уз тайноде́йственне нас свобожда́ющия.","Ра́дуйся, за́пад і восто́к с бра́том твої́м богому́дрим, про́повіді ра́ди сло́ва Бо́жия, жре́бієм разділи́вий;","ра́дуйся, во гра́ді Сино́пе неві́ріє іуде́єв си́лою чуде́с твої́х обличи́вий.","Ра́дуйся, я́ко та́мо от безбо́жних Христа́ ра́ди біє́н бил єси́;","ра́дуйся, я́ко от Самого́ я́вльшагося ті Го́спода ісціле́ніє язв тебі́ дарова́ся.","Ра́дуйся, Андре́є, апо́столе Христо́в Первозва́нний."]},{"h":"Кондак 5","ps":["Двукра́ти возвра́щся во Святи́й Град, да ку́пно со апо́столи п'ятидеся́тний день пра́зднуєши та́мо, двукра́ти па́ки ше́ствовал єси́ от свята́го Сіо́на, во є́же Христа́ пропові́дати вселе́нній, пе́рвіє со Іоа́нном напе́рсником Госпо́днім, посе́м же с Си́моном Канани́том і Матфі́єм, і́же жре́бієм назна́менован бисть во апо́стола, і вся преді́ли Асі́ї і По́нта обте́кл єси́, сло́вом спасе́нія всіх оглаша́я, да Бо́гу пою́ть: Аллилу́я."]},{"h":"Ікос 5","ps":["От мо́ря Галиле́йськаго до По́нта Євкси́нськаго апо́стольськія мре́жі твоя́ распростри́й і все помо́ріє о́крест огласи́вий благові́стієм твої́м, восте́кл єси́, Первозва́нне, і в страни́ Ски́фії, Крест Христо́во всю́ду водружа́я в зна́меніє на́шего спасе́нія. Сего́ ра́ди і ми, а́ще і по́зднії ро́ди, вне́млюще благові́стію твоєму́ і воспомина́юще по́двиги твоя́, зове́м ті:","Ра́дуйся, в Нике́ї лю́тия разбо́йники укроти́вий і люте́йшаго драко́на умертви́вий;","ра́дуйся, Крест Христо́в посреді́ гра́да сего́ водрузи́вий, я́ко Предте́ча сий двукра́ти собра́нних та́мо оте́ць богоно́сних.","Ра́дуйся, я́ко во Асі́ї і По́нті тобо́ю світ Христо́во возсія́;","ра́дуйся, я́ко апо́стольський жезл твой предго́ріє Кавка́са сві́ту Христо́ву отве́рзе.","Ра́дуйся, і́мже мрак Киммері́йський озари́ся;","ра́дуйся, і́мже вселе́нная струя́ми води́ жи́ви напоі́ся.","Ра́дуйся, Андре́є, апо́столе Христо́в Первозва́нний."]},{"h":"Кондак 6","ps":["Бу́рею страсте́й одержи́мая і, я́ко во́ди окея́на, волну́ємая, племена́ челові́ков, я́же не ві́дяху Бо́га І́стиннаго, приве́л єси́, апо́столе, к ти́хому приста́нищу Христо́ву і тіх сердца́, а́ки у́тлую ладію́ неві́рієм обурева́ємая, на я́кори ві́ри Правосла́вния утверди́л єси́. Ті́мже і ми, я́ко ча́да Правосла́вния ві́ри, благода́рним се́рдцем і благода́рними усти́ вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["На горі́ Єлео́нстій Боже́ственнаго Учи́теля твоєго́ іногда́ со про́чими апо́столи вопроси́л єси́, Андре́є: Рци нам, что єсть зна́меніє прише́ствія Твоєго́? — На гора́х же Ки́євських, я́ко орга́н сий благода́ті Ду́ха Свята́го, ти предвозвісти́л єси́ гряду́щую сла́ву мі́ста сего́; ми же, предрече́нния нам ми́лости сея́ сподо́бльшеся, умиле́нно взива́єм ті:","Ра́дуйся, я́ко с гори́ Сіо́на зако́н нам єва́нгельський прине́сл єси́;","ра́дуйся, я́ко по вода́м Ворисфе́на апо́стол Бо́жий к нам восте́кл єси́.","Ра́дуйся, благода́ть Іорда́нову, креще́нія на́шего ра́ди, ріці́ сей дарова́вий;","ра́дуйся, на гора́х Ки́євських Крест на́шего спасе́нія водрузи́вий.","Ра́дуйся, і́мже оби́льноє ізлія́ніє благода́ті Бо́жієй зді предрече́ся;","ра́дуйся, і́мже битіє́ гра́да вели́ка і церкве́й мно́гих зді предвозвісти́ся.","Ра́дуйся, Андре́є, апо́столе Христо́в Первозва́нний."]},{"h":"Кондак 7","ps":["Днесь, во ісполне́ніє проро́чеськаго гла́са твоєго́, храм пресла́вний красу́ється на мі́сті, іді́же не су́щая я́ко су́щая прови́діл єси́ по да́ру Ду́ха Свята́го; о́крест же єго́ град ве́лій с це́рквами златове́рхими і́стину слове́с твої́х свиді́тельствуєть, єму́же і дони́ні ти, я́ко с го́рнія кафе́дри, мир благовіству́єши. Ті́мже і ми, сбитіє́ богодухнове́нних глаго́л твої́х зря́ще, ве́ліїм гла́сом взива́єм Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["От світоно́сния зари́, Первозва́ннаго апо́стола, світ богові́дінія восприї́мши, свята́я О́льга возсія́ Росси́йстій землі́ я́ко денни́ця на́шего спасе́нія, возводя́ вслід себе́, я́ко світоза́рноє світи́ло, вну́ка своєго́ Влади́мира, просвіти́теля всея́ полу́нощния страни́. Ті́мже і ми, возве́дше о́чі на́ша к тебі́, Андре́є богому́дре, я́ко к нача́льному благове́стнику на́шего спасе́нія, воспису́єм ті похва́льная сія́:","Ра́дуйся, я́ко денни́це на́шего спасе́нія, О́льзі святі́й, сві́та Боже́ственнаго позна́ніє дарова́ся;","ра́дуйся, я́ко благові́рію єя́ Христо́во Ца́рствіє отве́рзеся.","Ра́дуйся, я́ко благослове́нієм твої́м пресла́вноє світи́ло от сея́ денни́ці нам проізи́де;","ра́дуйся, я́ко по твоєму́ предвозве́стію апо́стольському равноапостольний князь нам яви́ся.","Ра́дуйся, я́ко тобо́ю свята́го Влади́мира ца́рствіє земно́є к небе́сному приобщи́ся;","ра́дуйся, я́ко Днепр і Поча́йна, рі́ки Ки́євськия, спаси́тельною купі́лію нам би́ша.","Ра́дуйся, Андре́є, апо́столе Христо́в Первозва́нний."]},{"h":"Кондак 8","ps":["Пропові́дують пресла́внаго гра́да Ки́єва і всея́ Россі́йськия страни́ па́стиріє і пасо́мії па́м'ять дія́ній твої́х, богому́дре Андре́є апо́столе; в ні́драх же пеще́рних нетлі́нно почива́ющії уго́дниці Бо́жії, со Анто́нієм і Феодо́сієм, немо́лчними усти́, я́ко жи́ви су́ще, сла́ву твою́ віко́м і родо́м возглаша́ють, тобо́ю бо водруже́нний зді Крест, я́ко благосінноли́ственноє дре́во, проізрасте́, во є́же ізнести́ нам плоди́ благоче́стія і святи́ні. Ми же ра́йськаго вертогра́да твоєго́, а́ки птенці́ духо́внії, тобо́ю науче́ни єсьми́ воспіва́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Не то́чію Русі́ єди́ния бил єси́ спасе́нія провозві́стник, Первозва́нний апо́столе Христо́в, но і вся слове́нськая племена́, я́коже ко́кош, птенці́ своя́ под крилі́ собира́яй, приве́л єси́ я ко Христу́; ти бо от Херсо́ниса во мрак полу́нощния страни́ прозира́я, су́щим та́мо лю́дем, да Бо́жию науча́ться сло́ву, прему́дрия учи́тели, Кири́лла і Мефо́дія, про́повідію твоє́ю за мно́гія ві́ки предугото́вал єси́; ми же, а́ки уста́ми сих просвіти́телей на́ших, велегла́сно вопіє́м ті:","Ра́дуйся, слове́нськая племена́ іскони́ благослови́вий;","ра́дуйся, сло́во їх разу́мноє сло́вом Бо́жиїм умудри́вий.","Ра́дуйся, я́ко глаго́лу Бо́жию послушли́вії, Це́ркве ча́да слове́сная би́ша;","ра́дуйся, я́ко в Херсо́нисі, іді́же пропові́дал єси́, пе́рвая ру́ськая пи́смена Кири́лл святи́й обрі́те і прия́т я.","Ра́дуйся, я́ко ті́ми А́лфу і Оме́гу, Нача́ток і Коне́ць — Христа́ Бо́жию прему́дрость возвісти́л єси́ їм;","ра́дуйся, я́ко і вся богодухнове́нная писа́нія учи́теліє сії́ на язи́к слове́нск нам преложи́ша.","Ра́дуйся, Андре́є, апо́столе Христо́в Первозва́нний."]},{"h":"Кондак 9","ps":["Пусти́нния Ски́фії не убоя́вся, во глубину́ полу́нощния страни́ просте́рл єси́ апо́стольськая стра́нствія твоя́, Первозва́нне, отону́дуже і во ве́тхий Рим прише́л єси́, і́же тогда́ глава́ ми́ру язи́чеському бисть; оба́че тьми ра́ди і́дольськия оста́вль єго́, і на кра́сний брег Воспо́ра прише́д, та́мо во гра́ді Византі́ї, і́же но́вий Рим і ма́тер христия́ном бисть, апо́стольський престо́л твой утверди́л єси́, да от него́ восто́к і сі́вер весь сві́том ві́ри озари́ться, ві́рнії же ча́да Це́ркве Христо́ви Бо́гу єдиноми́сленно воззову́ть: Аллилу́я."]},{"h":"Ікос 9","ps":["Ма́ти Сіо́н, — псало́мськи рече́ть челові́к, я́ко челові́к духо́вно роди́ся в нем, но́вий же Сіо́н нам бисть Ки́єв: в нем бо світ і благода́ть Бо́жия яви́ся всім синово́м росси́йстим от кафе́дри, ю́же ти, Первозва́нне апо́столе, во Византі́ї утверди́л єси́. Ті́мже і ми, Невече́рнім Сві́том озаря́ємії, благода́рні взива́єм ті:","Ра́дуйся, от гори́ Сіо́нськия снизше́дий і го́рнім сві́том Ки́єв многохо́лмний озари́вий;","ра́дуйся, гра́ду сему́ многопло́діє духо́вноє благослове́нієм твої́м, низпосла́вий.","Ра́дуйся, я́ко посреді́ вселе́нния апо́стольський престо́л твой утверди́л єси́;","ра́дуйся, я́ко под сінь єго́, в но́вом Ри́мі, вся просвіще́нния тобо́ю язи́ки собра́л єси́.","Ра́дуйся, і́мже Правосла́віє в душа́х їх утвержда́ється;","ра́дуйся, і́мже от восто́ка тьма за́пада отріва́ється.","Ра́дуйся, Андре́є, апо́столе Христо́в Первозва́нний."]},{"h":"Кондак 10","ps":["Єгда́ наста́ вре́м'я преставле́нія твоєго́, блаже́нне апо́столе, в дре́внія Па́три Аха́йськия прише́л єси́, да та́мо жрен бу́деши, тече́ніє бо сконча́л єси́, по́двигом до́брим подвиза́лся єси́, всім пропові́дав Христа́ ра́сп'ята, іуде́єм собла́зн, е́ллином же безу́міє, нам же, зва́нним і спаса́ємим, — Христа́, Бо́жию Си́лу і Бо́жию Прему́дрость, от Нея́же і научи́хомся пі́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Всю́ду і́менем Го́спода Ісу́са боля́щия ісціля́я, ме́ртвия воскреша́я, бі́си ізгоня́я, і во Па́трах предсме́ртную про́повідь твою́ чудеса́ми утверди́л єси́, апо́столе Христо́в, і анфипа́та Ле́звія обрати́л єси́ к позна́нію і́стини, єгда́ противле́нія ра́ди я́звою пораже́н бив, тобо́ю от одра́ болі́зні воздви́жен бисть, лю́діє же всі, ви́дівше в тебі́ си́лу Бо́жию, і́доли своя́ сокруши́ша, посе́м і Госпо́дь яви́ся тебі́, я́коже Па́влу іногда́ в Кори́нфі, і повелі́ взя́ти крест твой, назна́меновав сим твоє́ в Па́трах, Єго́ ра́ди, страда́ніє. Ті́мже і ми, див'я́щеся ве́лієй благода́ті в тебі́, благогові́йно взива́єм:","Ра́дуйся, ве́лія Бо́га всемогу́щаго си́ло;","ра́дуйся, многоці́нноє чуде́с сокро́вище.","Ра́дуйся, дре́вніх Патр просвіще́ніє і украше́ніє;","ра́дуйся, неві́ріє анфипа́та во ві́ру преміни́вий.","Ра́дуйся, я́ко та́мо па́ки яви́ся тебі́ Госпо́дь, на по́двиг кре́стний тя призва́вий;","ра́дуйся, я́ко угото́вася тебі́ віне́ць пра́вди.","Ра́дуйся, Андре́є, апо́столе Христо́в Первозва́нний."]},{"h":"Кондак 11","ps":["Неро́н ке́сар, я́коже іногда́ І́род, гоне́ніє на вся ві́рния воздви́гнувий, в Ри́мі Па́вла мече́м усі́кну, Петра́ же на кресті́ расп'я́, подо́бні і тебі́ дости́же в Па́трах рука́ мучи́телева, єгда́ вмі́сто кро́ткаго Ле́звія судію́ поста́ви Єгея́та лю́таго, і́же не терп'я́й креще́нія бра́та своєго́, ніже́ ісціле́нієм жени́ своєя́ ум'ягче́н бив, в темни́цю вве́рже тя і, я́коже верхо́внаго Петра́, на крест осуди́. Ти же ю́зник сий, в темни́ці мра́чній, я́ко во сві́тлім хра́мі, бра́та анфипа́това Стратокли́са во єпи́скопа Па́тром проро́чествовал єси́, Бо́гу со всі́ми ві́рними посреді́ узи́лища воспіва́я: Аллилу́я."]},{"h":"Ікос 11","ps":["На мі́сті ло́бнім крест воздвиза́єм узрі́в, на не́мже імі́л єси́ ра́сп'ят би́ти, не убоя́лся єси́, апо́столе, да́же до сме́рти свиді́тельствовати возлю́бльшаго тя і возлю́бленнаго тобо́ю Христа́, і к сему́ зна́менію спасе́нія ру́ці простира́я, умиле́нно взива́л єси́:","Ра́дуйся, Кре́сте Всечестни́й, пред ни́мже с весе́лієм предстою́, ві́дая тя, упова́ніє моє́;","ра́дуйся, Кре́сте Животворя́щий, єго́же глава́ до небе́с дости́же, подно́жіє же врата́ а́да сокруши́.","Ра́дуйся, Кре́сте достопокланя́ємий, восприє́мий Влади́ку моєго́, я́ко гро́здіє сладча́йшеє, істочи́вшеє нам спасе́ніє;","ра́дуйся, Кре́сте благослове́нний, разбо́йника спаси́й і тому́ плоди́ іспові́данія дарова́вий.","Ра́дуйся, я́ко і моєя́ ра́дости ісполне́ніє бил єси́; — ті́мже ра́дуйся і ти, страстоте́рпче, на Кресті́ ві́ру твою́ во Христа́ запечатлі́вий.","Ра́дуйся, Андре́є, апо́столе Христо́в Первозва́нний."]},{"h":"Кондак 12","ps":["Прийді́те, свиді́теліє ра́дости моєя́! — воззва́л єси́ апо́столе к соверши́телем во́лі Єгея́та, — творі́те во́лю на́ю обою́, распні́те м'я і, я́ко а́гнця, принесі́те в же́ртву созда́вшему м'я Творцю́. — І сія́ рек, возше́л єси́ на крест, я́ко на го́рнюю кафе́дру, с нея́же три дні і три но́щі пропові́дал єси́ сло́во Бо́жиє о́крест стоя́щим лю́дем, да не боя́ться сме́рті, іспові́дающе Го́спода Ісу́са. Єгда́ же сві́том небе́сним озари́ся лик твой, ужасе́ся мучи́тель і тя со креста́ взя́ти повелі́; оба́че ти, страстоте́рпче, не восхоті́л єси́ от кре́стних мук разріши́тися, до ісхо́да твоєго́ непреста́нно Бо́гу вопія́: Аллилу́я."]},{"h":"Ікос 12","ps":["Сла́в'яще апо́стольськія по́двиги твоя́, Андре́є Первозва́нне, ублажа́єм святу́ю кончи́ну твою́, є́юже Живоно́сную Страсть Си́на Бо́жия просла́вил єси́, і во умиле́нії се́рдця взива́єм ті си́це:","Ра́дуйся, дру́же Христо́в, с ра́достію кре́стная страда́нія за Него́ претерпі́вий;","ра́дуйся, апо́столе ві́рний, со креста́ глаго́ли живота́ ві́чнаго лю́дем пропові́давий.","Ра́дуйся, я́ко в час сня́тія со креста́ осіни́ тя світ, а́ки мо́лнія с небесе́;","ра́дуйся, я́ко правосла́вно іспове́дающим пропові́даннаго тобо́ю Христа́ Си́на Бо́жия обіща́л єси́ благода́ть ве́лію.","Ра́дуйся, Го́рняго Ієрусали́ма апо́стольськоє основа́ніє;","ра́дуйся, сідя́й со апо́столи на єди́ном от двоюна́десяте престо́лов, во є́же суди́ти вся колі́на Ізра́їлева.","Ра́дуйся, Андре́є, апо́столе Христо́в Первозва́нний."]},{"h":"Кондак 13","ps":["О, Первозва́нний апо́столе Христо́в Андре́є! При́зри на благохвале́нія сія́ всіх чту́щих святу́ю па́м'ять твою́, і я́ко водрузи́л єси́ кре́стноє дре́во на гора́х гра́да Ки́єва, при́сно осіня́й і нас спаси́тельним зна́менієм сим, да, Кресто́м Го́спода Бо́га і Спа́са на́шего охраня́ємі, дости́гнем в мі́ру во́зраста ісполне́нія Христо́ва і сподо́бимся с тобо́ю і со всі́ми святи́ми, во гла́сі ра́дованія, в безконе́чния ві́ки пі́ти Бо́гу, Спаси́телю на́шему: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгел благові́стник А́гнця Христа́, взе́млющаго гріхи́ ми́ра, бил єси́ Андре́є апо́столе, і с Ним во ві́ки пребива́єши на небесі́; отону́дуже і при́зри на пі́нія, приноси́мая тебі́ во хра́мі твоє́м, на мі́сті, іді́же стоя́сте но́зі твої́, і я́ко бога́т сий благода́тію Бо́жиєю, пода́ждь нам сло́во бла́го, да зове́м ті:","Ра́дуйся, денни́це от гра́да Вифсаї́ди нам возсія́вшая;","ра́дуйся, равноче́стний бра́те верхо́внаго Петра́.","Ра́дуйся, учениче́ вели́каго Предте́чі Христо́ва;","ра́дуйся, пе́рвіє про́чих апо́стол зва́нний ко апо́стольському служе́нію от Самого́ Го́спода.","Ра́дуйся, я́ко і други́м с ра́достію воззва́л єси́: прийді́те, обріто́хом жела́ємаго Мессі́ю;","ра́дуйся, і нас к Нему́ же приводя́й.","Ра́дуйся, Андре́є, апо́столе Христо́в Первозва́нний."]},{"h":"Кондак 1","ps":["Первозва́ннаго апо́стола Христо́ва, Єва́нгелія Свята́го пропові́дника, Россі́йськия страни́ богодухнове́ннаго просвіти́теля, Андре́я пресла́внаго, пі́сньми восхва́лим, стоя́ще на версі́ холма́, іді́же Крест водрузи́ десни́ця єго́, і єму́ я́ко Це́ркве возсле́дователю верхо́вному, в слід себі́ указа́вшему єй путь ко Христу́, во умиле́нії воззове́м:","Ра́дуйся, Андре́є, апо́столе Христо́в Первозва́нний."]},{"h":"Молитва","ps":["Первозва́нне апо́столе Бо́га і Спа́са на́шего Ісу́са Христа́, Це́ркве послі́дователю верхо́вний, всехва́льне Андре́є! Сла́вим і, велича́єм апо́стольськія труди́ твоя́, сла́дці помина́єм твоє́ благослове́нноє к нам прише́ствіє, ублажа́єм честна́я страда́нія твоя́, я́же за Христа́ претерпі́л єси́, лобиза́єм свяще́нния мо́щі твоя́, чтим святу́ю па́м'ять твою́ і ві́руєм, я́ко жив Госпо́дь, жива́ же і душа́ твоя́ і с Ним во ві́ки пребива́єши на небесі́, іді́же і лю́биши ни то́южде любо́вію, є́юже возлюби́л єси́ нас, єгда́ Ду́хом Святи́м прозрі́л єси́ на́ше, є́же ко Христу́ обраще́ніє, і не то́чію лю́биши, но і мо́лиши о нас Бо́га, зря во Сві́ті Єго́ вся ну́жди на́ша. Та́ко ві́руєм і та́ко сію́ ві́ру на́шу іспові́дуєм во хра́мі, і́же во і́м'я твоє́, святи́й Андре́є, пресла́вно созда́ся, іді́же святи́я мо́щі твоя́ почива́ють; ві́рующе же, про́сим і мо́лим Го́спода і Бо́га і Спа́са на́шего Ісу́са Христа́, да моли́твами твої́ми, я́же при́сно послу́шаєть і приє́млеть, пода́сть нам вся потре́бная ко спасе́нію нас грі́шних; да я́коже ти а́біє по гла́су Го́спода, оста́вль мре́жі своя́, неукло́нно Єму́ послі́довал єси́, си́це і ки́йждо от нас да і́щеть не свої́х си, но є́же к созида́нію бли́жняго і о го́рнем зва́нії да помишля́єть. Іму́ще же тя предста́теля і моли́твенника о нас, упова́єм, я́ко моли́тва твоя́ мно́го мо́жеть пред Го́сподем і Спаси́телем на́шим Ісу́сом Христо́м, Єму́же подоба́єть вся́кая сла́ва, честь і поклоне́ніє со Отце́м і Святи́м Ду́хом во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Я́ко апо́столов первозва́нний / і верхо́внаго су́щий брат, / Влади́ці всіх, Андре́є, моли́ся / мир вселе́нній дарова́ти // і душа́м на́шим ве́лію ми́лость."]},{"h":"Кондак, глас 2","ps":["Му́жества тезоімени́таго Богоглаго́льника / і Це́ркве возслі́дователя верхо́внаго, / Петро́ва сро́дника восхва́лим, / зане́ я́коже дре́вле сему́, і ни́ні нам воззва́: // прийді́те, обріто́хом жела́ємаго."]},{"h":"Величання","ps":["Велича́єм тя, / апо́столе Христо́в Андре́є, / і чтим болі́зні і труди́ твоя́, / ї́миже труди́лся єси́ // во благові́стії Христо́ві."]}],"notes":[]},{"u":"Акафіст святим праведним богоотцям Іоакиму і Анні","e":"Akathist to the Holy Righteous Ancestors of God Joachim and Anna","secs":[{"h":"Кондак 1","ps":["Ізбра́ннії от челові́чеськаго ро́да прароди́теліє Христо́ви, ро́ждшії Преблагослове́нную Богоотрокови́цю, із Нея́же по пло́ті Син Бо́жий роди́ся, святі́ї і пра́веднії Богоотці́ Іоаки́мі і А́нно! Я́ко іму́щії дерзнове́ніє ве́ліє ко Христу́ Бо́гу і ви́ну предстоя́щії Престо́лу Єго́ небе́сному, Тому́ прилі́жно молі́теся от бід нам ізба́витися, да ви́ну зове́м вам:","Ра́дуйтеся, святі́ї і пра́веднії Богоотці́ Іоаки́мі і А́нно."]},{"h":"Ікос 1","ps":["А́нгел предста́тель по́слан бисть к вам от Бо́га, святі́ї і пра́веднії Богоотці́ Іоаки́мі і А́нно, єгда́ о безпло́дії своє́м ов у́бо в пусти́ні, о́ва же в саду́ своє́м се́товасте, к Бо́гу моли́тву вознося́ще; і та́ко благові́стіє ра́достноє принесе́ безпло́тний, я́ко роди́ти і́мате Дщер Преблагослове́нную, о Не́йже возблагослови́ться весь род челові́чеський, с ни́мже і ми вам ра́достноє прино́сим хвале́ніє:","Ра́дуйтеся, ко́рене Дави́дова святопроцве́тшия ро́зги виногра́да живо́тнаго;","ра́дуйтеся, ро́ждшії Дщер, от всіх родо́в Преблагослове́нную.","Ра́дуйтеся, вопло́щшагося Си́на Бо́жия прароди́теліє всечестні́ї;","ра́дуйтеся, та́їнства, от ві́ка утає́ннаго, прояви́теліє всеїзря́днії.","Ра́дуйтеся, уті́хи Ізра́їлеви ближа́йшії по пло́ті сро́дниці;","ра́дуйтеся, обітова́ннаго ми́ру Спаси́теля єдинокро́внії ю́жиці.","Ра́дуйтеся, святі́ї і пра́веднії Богоотці́ Іоаки́мі і А́нно."]},{"h":"Кондак 2","ps":["Ви́дів себі́ святи́й Іоаки́м, во хра́мі Ієрусали́мстем безпло́дія ра́ди от архієре́я уничиже́нна, зіло́ опеча́лися, і в го́ресті ду́ші своєя́ в пусти́ню к свої́м стадо́м удали́ся, і та́мо со мно́гими слеза́ми те́плі ко Го́споду моля́шеся, да сподо́бит єго́ отце́м своєму́ ча́ду нарещи́ся, і та́ко к моли́тві же пост прилага́ше, і в сокруше́нії се́рдця Вседержи́телю Бо́гу взива́ше: Аллилу́я."]},{"h":"Ікос 2","ps":["Си́лу го́рести му́жа своєго́ свята́я А́нна уві́дівши, в дому́ своє́м сідя́щи, го́рці пла́кася і моля́шеся ко Го́споду, да поноше́ніє безпло́дія от нея́ оти́меть. Ми же, толи́коє терпі́ніє пра́ведних помина́юще, воззове́м:","Ра́дуйтеся, богоізбра́нная дво́їце, Єди́ному от Тро́йці Ма́тер по пло́ті породи́вшая;","ра́дуйтеся, Зижди́телю ва́шему Роди́тельницю непоро́чную проізве́дшії.","Ра́дуйтеся, супру́зі благослове́ннії, Преблагослове́нную в жена́х Дщер воспита́вшії;","ра́дуйтеся, в безпло́дії ва́шем от Го́спода усли́шаннії.","Ра́дуйтеся, я́ко сле́зния моли́тви ва́ша пронико́ша не́бо і во у́шію Бо́га Ізра́їлева достиго́ша;","ра́дуйтеся, я́ко поноше́ніє ва́ше вре́менноє во сла́ву ві́чную на небесі́ і на землі́ ізміни́ся.","Ра́дуйтеся, святі́ї і пра́веднії Богоотці́ Іоаки́мі і А́нно."]},{"h":"Кондак 3","ps":["Си́лою Бо́жиєю преіспо́лнен, яви́ся А́нгел Госпо́день свято́му Іоаки́му в пусти́ні і рече́ єму́: «Усли́ша Бог моли́тву твою́ і ізво́ли да́ти тебі́ благода́ть Свою́, се бо жена́ твоя́ А́нна зачне́ть і породи́ть тебі́ Дщер, о Не́йже всему́ ми́ру бу́деть ра́дость». Сія́ рек безпло́тний, повелі́ єму́ ко хра́му Ієрусали́мському па́ки отидти́, іді́же он супру́гу свою́ моля́щуся обря́щеть, с не́юже вку́пі да воспоє́ть та́мо хвале́бную піснь Бо́гу Ізра́їлеву: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́щи скорб ве́лію в се́рдці своє́м А́нна свята́я і во вертогра́д до́ма своєго́ вше́дши, ви́ді гніздо́ пти́че на дре́ві сооруже́но, птенці́ ма́лия в нем лежа́щия, а́біє моле́нія к моле́ніям прилага́ти потща́ся, да сподо́бит ю Госпо́дь ма́тер ча́ду би́ти. І се яви́ся єй а́нгел Госпо́день, глаго́ля: «Усли́шана єсть моли́тва твоя́ і воздиха́нія твоя́ пройдо́ша о́блаки, сле́зи же твоя́ пред Бо́га внидо́ша: се зачне́ши і роди́ши Дщер Преблагослове́нную, о Не́йже возблагослов'я́ться вся колі́на земна́я, і То́ю да́сться спасе́ніє всему́ ми́ру, нарече́ться же і́м'я Єй Марі́я». Таково́є а́нгельськоє всера́достноє благові́щеніє помина́юще, воспої́м Богоотце́м такова́я:","Ра́дуйтеся, супру́зі пра́веднії, от Бо́га сви́ше предизбра́ннії;","ра́дуйтеся, во всіх за́повідіх Госпо́дніх без поро́ка ходи́вшії.","Ра́дуйтеся, в ско́рбі ва́шей вре́менній утіше́ніє ві́чноє получи́вшії;","ра́дуйтеся, па́че ча́янія ва́шего десни́цею Бо́жиєю превознесе́ннії.","Ра́дуйтеся, я́ко во смире́нії ва́шем і ско́рби пом'яну́ ви Госпо́дь;","ра́дуйтеся, я́ко сподо́бистеся прароди́теліє Си́ну Бо́жию би́ти.","Ра́дуйтеся, святі́ї і пра́веднії Богоотці́ Іоаки́мі і А́нно."]},{"h":"Кондак 4","ps":["Бу́рею сомні́нія Іоаки́м пра́ведний содержи́м і о благові́стії єму́ а́нгела недоуміва́я, а́біє во град Ієрусали́м оти́де, іді́же пред врати́ хра́ма святу́ю А́нну обрі́те, Го́спода вельми́ славосло́в'ящую і ра́дость а́нгельськаго явле́нія і о ча́ді прорече́нія єму́ возвіща́ющу, ті́мже і о своє́м виді́нії супру́жнице благовісти́в, вку́пі с не́ю возопи́ ко Го́споду: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавше сро́дници і зна́ємії о пресла́вном святи́я А́нни зача́тії, Бо́га Ізра́їлева сла́вляху, А́нна же богому́драя плод чре́ва своєго́ на служе́ніє Бо́гу обрече́, те́плоє благодаре́ніє Го́сподеві возноша́ше; ми же сві́тло всесла́вноє зача́тіє Богоотрокови́ці Марі́ї воспіва́юще, Той святи́м роди́телем глаго́лем си́це:","Ра́дуйтеся, ра́достнії нам гряду́щаго в мир Іскупи́теля провозві́стници;","ра́дуйтеся, при́сно помина́ємії ча́ємаго Спаси́теля пра́отці.","Ра́дуйтеся, чрез Дщер ва́шу благослове́нную Сло́ву Бо́жию плоть взаїмода́вшії;","ра́дуйтеся, Бо́га воплоще́нна Вну́ка себі́ нариця́ющії.","Ра́дуйтеся, ве́лієй благоче́стія та́йни досто́йнії служи́теліє;","ра́дуйтеся, Бо́жия к челові́ком снисхожде́нія всеїзря́днії посре́дници.","Ра́дуйтеся, святі́ї і пра́веднії Богоотці́ Іоаки́мі і А́нно."]},{"h":"Кондак 5","ps":["Богосві́тлую звізду́ я́вльшую Со́лнце Пра́вди Христа́ Бо́га, Пресвяту́ю Богоро́дицю, пло́тію роди́ти сподо́бистеся, і вожделі́нноє і́м'я Богооте́ць прия́сте, Іоаки́мі і А́нно всеблаже́ннії, о Єя́же рождестві́ святі́м не́бо і земля́ возра́довашася, і весь род челові́чеський освяти́ся, вопія́ ди́вному во святи́х Свої́х Бо́гу Ізра́їлеву: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше роди́теліє от них ро́ждшуюся Богоотрокови́цю Марі́ю, Зижди́телеву же Ма́тер, я́ко киво́ту Бо́жию, благогові́йно Той послужи́ша; ті́мже і нас, к вам моли́твенно припа́дающих, не отврати́тесь, глаго́лющих:","Ра́дуйтеся, в рождестві́ Богоотрокови́ці Марі́ї сві́тло возликова́вшії;","ра́дуйтеся, виді́нієм Богоотрокови́ці услажде́ннії.","Ра́дуйтеся, сли́шанієм Єя́ умиле́ннії;","ра́дуйтеся, по сих от архієре́я Бо́жия благослове́ннії і ублаже́ннії.","Ра́дуйтеся, А́гницю непоро́чную в дому́ своє́м до́брі упа́сшії;","ра́дуйтеся, А́гнця і Па́стиря Ма́тер во Дщер себі́ приє́мшії.","Ра́дуйтеся, святі́ї і пра́веднії Богоотці́ Іоаки́мі і А́нно."]},{"h":"Кондак 6","ps":["Пропові́дници чуде́с Бо́жиїх яви́стеся святі́ї, єгда́ обі́т свой Бо́гові соверши́сте і триле́тнюю Богоотрокови́цю Марі́ю в храм Бо́жий со сла́вою введо́сте, да обита́єть та́мо во свята́я святи́х, о сих у́бо ра́достно Бо́гу оте́ць ва́ших славосло́вія піснь воспіва́ти потща́стеся: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ Богоотрокови́ця, я́ко луна́ по́лная, в честні́м Своє́м в храм Госпо́день вхожде́нії, Єя́же чистоті́ а́нгели удивля́хуся, і архієре́й Бо́жий Заха́рія приє́м Ю от рук ва́ших, святі́ї Іоаки́мі і А́нно, во вну́тренняя свята́я святи́х с че́стію введе́, я́ко воі́стину одушевле́нний Бо́жий киво́т, вас же по достоя́нію ублажи́ хвале́ньми такови́ми:","Ра́дуйтеся, ра́дость всеми́рную ро́ду челові́чеському породи́вшії;","ра́дуйтеся, Вино́вницю челові́чеськаго обновле́нія воспита́вшії.","Ра́дуйтеся, в храм Госпо́день Киво́т одушевле́нний Бо́жий приве́дшії;","ра́дуйтеся, Дщер ва́шу Святу́ю во свята́я святи́х вмісти́вшії.","Ра́дуйтеся, Бо́гу, воплоти́тися хотя́щему, сро́дниці явля́ющіїся;","ра́дуйтеся, а́нгелом собесі́дниці би́вшії.","Ра́дуйтеся, святі́ї і пра́веднії Богоотці́ Іоаки́мі і А́нно."]},{"h":"Кондак 7","ps":["Жела́ніє ду́ші твоєя́ іспо́лнив і обі́т твой Бо́гові возда́в, Іоаки́ме преблаже́нне, в ста́рости до́брій свя́то і пра́ведно жизнь земну́ю о Го́споді сконча́л єси́. Ті́мже ни́ні Тому́ і о нас сотвори́ моли́тву, да благу́ю, ми́рную і непости́дную кончи́ну получи́ти сподо́бимся, зову́ще Єму́: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́воє і богоуго́дноє житіє́ во вдовстві́ твоє́м, А́нно свята́я, провожда́ла єси́, у хра́ма Бо́жия примета́ющися і Святі́й і Преблагослове́нній Дще́ри твоє́й сослужа́щи, ті́мже я́ко і́стинную і богоуго́дную вдови́цю, Христо́ву же праба́бу, тя восхваля́єм, вку́пі же і му́жа твоєго́, Богоотця́ Іоаки́ма, усе́рдно че́ствуєм і с любо́вію пі́сні такови́я вам прино́сим:","Ра́дуйтеся, пра́ведници, ї́хже пра́вда, я́ко со́лнце, сія́єть во ві́ки;","ра́дуйтеся, А́нгелом дру́зі, сожи́теліє святи́м і при́снії Бо́гу.","Ра́дуйтеся, бли́жнії небе́снаго Престо́ла предстоя́теліє;","ра́дуйтеся, дерзнове́ніє ве́ліє ко Христу́ Бо́гу іму́щії.","Ра́дуйтеся, Це́ркве, на небесі́ торжеству́ющия, украше́ніє;","ра́дуйтеся, Це́ркве, во́їнствующия на землі́, до́броє заступле́ніє.","Ра́дуйтеся, святі́ї і пра́веднії Богоотці́ Іоаки́мі і А́нно."]},{"h":"Кондак 8","ps":["Стра́нствіє земно́є соверши́в, свята́я і пра́ведная А́нно, на рука́х Пребоже́ственния твоєя́ Дще́ри, Богоро́диці Марі́ї, сном сме́ртним почи́ла єси́ і к Бо́гу со упова́нієм преста́вилася єси́, ті́мже свято́є успе́ніє твоє́ сла́в'яще, мо́лим тя, о Богопрама́тер всечестна́я, да єгда́ і ми сном сме́ртним усипа́ти начне́м, умоли́ Спа́са Христа́ кро́тко ду́шу на́шу от ті́ла отдели́ти і бісо́вськия вла́сті ю ізба́вити, спасе́нія же ві́чнаго нас удосто́іти, да зове́м Єму́ в ра́дості святи́х: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь мир христия́нський блажи́ть вас по достоя́нію, святі́ї і пра́веднії Богоотці́ Іоаки́мі і А́нно, і моли́твенно ва́ша честна́я імена́ прославля́єть, Це́рков же Христо́ва сві́тло па́м'ять ва́шу пра́зднуєть і пі́сні хвале́бния вам прино́сить си́це:","Ра́дуйтеся, світи́льници, мрак душ на́ших благода́тно озаря́ющії;","ра́дуйтеся, от го́рних висо́т сла́ви ва́шея к земноро́дним ми́лостиво прониця́ющії.","Ра́дуйтеся, Богоро́дице Марі́ї сомоли́твенници всегда́шнії;","ра́дуйтеся, Христа́ Бо́га умилостиви́теліє многомо́щнії.","Ра́дуйтеся, любо́в і ві́ру к вам іму́щих от вся́ких бід спаса́ющії;","ра́дуйтеся, моли́твенно на по́мощ вас призива́ющих от напра́сния і на́глия сме́рти ізбавля́ющії.","Ра́дуйтеся, святі́ї і пра́веднії Богоотці́ Іоаки́мі і А́нно."]},{"h":"Кондак 9","ps":["Всі а́нгели Бо́жії і ли́ци святи́х Бо́жиїх на небесі́ вас, святі́ї і пра́веднії Богоотці́ Іоаки́мі і А́нно, цілу́ють, ро́ди же челові́честії на землі́ моли́твенними пі́сньми вас похваля́ють і о предста́тельстві ва́шем благода́рно вопію́ть Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Вити́йства на́ша не довлі́ють к досто́йной вам похвалі́, святі́ї прароди́теліє Христо́ви; оба́че ви, ми́лостиви су́ще, і на́ша убо́гая хвале́нія не отвраті́те, но бу́діте о нас те́плії предста́телі і моли́твенниці ко Го́споду, ва́шими святи́ми моли́твами ску́дость душ на́ших восполня́юще, да благода́рственні вам зове́м:","Ра́дуйтеся, ра́дости і сла́ви ві́чния вожделе́ннії нам стяжа́теліє;","ра́дуйтеся, благ вре́менних і ві́чних усе́рднії нам пред Го́сподем хода́таї.","Ра́дуйтеся, от смертоно́сния я́зви предста́тельством ва́шим ві́рния сохраня́ющії;","ра́дуйтеся, тлетво́рния ві́три моли́твами ва́шими разгоня́ющії.","Ра́дуйтеся, трясе́ніє землі́ і бу́ри зі́льния хода́тайством ва́шим установля́ющії і в тишину́ прелага́ющії;","ра́дуйтеся, во вся́ких біда́х і злоключе́ніїх на по́мощ к нам ускоря́ющії.","Ра́дуйтеся, святі́ї і пра́веднії Богоотці́ Іоаки́мі і А́нно."]},{"h":"Кондак 10","ps":["Спасе́нія душе́внаго жела́ющим і о сем усе́рдно подвиза́ющимся, помо́щници блазі́ї, святі́ї і пра́веднії Богоотці́ Іоаки́мі і А́нно, яви́стеся, ов у́бо і́ноком, о́ва же і́нокинем храни́тели імену́єтеся, о́бщеє моле́ніє за всіх ві́рних Бо́гу принося́ще, да всі благода́рственно зову́ть просла́вльшему вас во вселе́нній, Царю́ сла́ви Христу́: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіно́ю моли́тв ва́ших небе́сних, святі́ї і пра́веднії Богоотці́ Іоаки́мі і А́нно, сохраня́йте і огражда́йте нас от іскуше́ній врага́ дия́вола, і́щущаго душе́вній поги́белі на́шей: ві́ми бо, ві́ми, я́ко мно́го мо́жеть моли́тва ва́ша пред лице́м Христа́ Бо́га на́шего, ва́шего же по пло́ті Вну́ка. Єго́же умоля́ти не преста́йте о всіх, с любо́вію вас почита́ющих і вопію́щих:","Ра́дуйтеся, ма́слина благопло́дная, єле́й ми́лости Бо́жієй оби́льно нам істоча́ющая;","ра́дуйтеся, кипари́си дво́є благосенноли́ственнії, зной страсте́й на́ших в поко́й безстра́стія приводя́щії.","Ра́дуйтеся, виссо́ні і багряни́це, із ни́хже Ски́нія Бо́жия селе́нія сооруди́ся;","ра́дуйтеся, го́рлиці єдиносупру́жнії, Голуби́цю непоро́чную проізве́дшії.","Ра́дуйтеся, со Дще́рію ва́шею, всіх Цари́цею, ві́чно ца́рствующії;","ра́дуйтеся, в Сіо́ні го́рнем в оби́телі Єя́ небе́сній сві́тло торжеству́ющії.","Ра́дуйтеся, святі́ї і пра́веднії Богоотці́ Іоаки́мі і А́нно."]},{"h":"Кондак 11","ps":["Пі́ніє на́ше хвале́бноє ми́лостивно приймі́те і щедро́т ва́ших моли́твенних нас не лиші́те, о святі́ї прароди́теліє Христо́ви Іоаки́мі і А́нно, а́ще і недосто́йнії єсьми́, гріхо́в ра́ди на́ших, ва́шего свята́го заступле́нія: оба́че я́ко бла́зі і всеще́дри су́ще, сіє́ нам подаді́те, і помозі́те нам покая́нієм очи́ститися от скве́рни гріхо́вния, да в чистоті́ серде́ць воспоє́м Созда́телю на́шему хвале́бную піснь: Аллилу́я."]},{"h":"Ікос 11","ps":["Світопода́тельная два світи́льника, всеми́рную Свіщу́ возже́гшії, позна́єм святи́х Богооте́ць Іоаки́ма і А́нну, о бра́тіє, і сія́нієм тіх небе́сния сла́ви озаря́ємі, воспої́м їм такова́я:","Ра́дуйтеся, сла́внійшую без сравне́нія Серафи́м воспита́ти удосто́ївшіїся;","ра́дуйтеся, луча́ми благода́ті Бо́жия осія́нії.","Ра́дуйтеся, благоуха́нія духо́внаго преіспо́лненнії;","ра́дуйтеся, фимія́м моли́тв ва́ших о всем ми́рі христия́нстім Бо́гу принося́щії.","Ра́дуйтеся, с Богоро́дицею Марі́єю і Предте́чею Іоа́нном у Престо́ла Христо́ва ви́ну предстоя́щії.","Ра́дуйтеся, святі́ї і пра́веднії Богоотці́ Іоаки́мі і А́нно."]},{"h":"Кондак 12","ps":["Благода́ть Бо́жию і ми́лость нам пода́ти, проще́ніє же гріхо́в і ісправле́нія житія́ ниспосла́ти просі́те нам у Го́спода, святі́ї Богоотці́ Іоаки́мі і А́нно, і не преста́йте о нас пред лице́м Вседержи́теля Бо́га моля́ще, я́ко стяжа́вшії к Нему́ дерзнове́ніє мно́гоє. О сем усе́рдно к вам припа́дающе, я́ко при́сних предста́телей і засту́пников на́ших, про́сим і благоумиле́нно зове́м всіх Творцю́: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще многомо́щноє предста́тельство ва́ше к Бо́гу, Іоаки́мі і А́нно пра́веднії, велича́єм возвели́чившаго вас Христа́ Го́спода, воспіва́єм і рожде́нную от вас Пренепоро́чную Єго́ Ма́тер, вам же от усе́рдія на́шего сія́ достодо́лжния похвали́ прино́сим:","Ра́дуйтеся, от восто́ка і до за́пада препросла́вленнії;","ра́дуйтеся, стра́жіє боже́ственнії, неуси́пно бдя́щії в моли́твах к Бо́гу о всіх ві́рних.","Ра́дуйтеся, по́мощ ва́шу благода́тную вся́цій душе́ христия́нстій подаю́щії;","ра́дуйтеся, во благи́х моле́нія і проше́нія благочести́вих ісполня́ющії.","Ра́дуйтеся, душе́вних і тіле́сних неду́гов преізря́днії і безме́зднії ціли́телі;","ра́дуйтеся, благ вре́менних і ві́чних всеусе́рднії і благоприя́тнії нам хода́таї.","Ра́дуйтеся, святі́ї і пра́веднії Богоотці́ Іоаки́мі і А́нно."]},{"h":"Кондак 13","ps":["О святі́ї і пра́веднії Богоотці́ Іоаки́мі і А́нно! Мо́лим вас со усе́рдієм і любо́вію, к подно́жію ног ва́ших припа́дающе: умолі́те Го́спода Бо́га ізба́вити нас от поги́белі ві́чния, грі́шником угото́ванния, да милосе́рдієм Бо́га на́шего спаса́ємі і ва́шими святи́ми моли́твами споспешеству́ємі, благода́рственно воспої́м Єму́ а́нгельськую піснь: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгел предста́тель по́слан бисть к вам от Бо́га, святі́ї і пра́веднії Богоотці́ Іоаки́мі і А́нно, єгда́ о безпло́дії своє́м ов у́бо в пусти́ні, о́ва же в саду́ своє́м се́товасте, к Бо́гу моли́тву вознося́ще; і та́ко благові́стіє ра́достноє принесе́ безпло́тний, я́ко роди́ти і́мате Дщер Преблагослове́нную, о Не́йже возблагослови́ться весь род челові́чеський, с ни́мже і ми вам ра́достноє прино́сим хвале́ніє:","Ра́дуйтеся, ко́рене Дави́дова святопроцве́тшия ро́зги виногра́да живо́тнаго;","ра́дуйтеся, ро́ждшії Дщер, от всіх родо́в Преблагослове́нную.","Ра́дуйтеся, вопло́щшагося Си́на Бо́жия прароди́теліє всечестні́ї;","ра́дуйтеся, та́їнства, от ві́ка утає́ннаго, прояви́теліє всеїзря́днії.","Ра́дуйтеся, уті́хи Ізра́їлеви ближа́йшії по пло́ті сро́дниці;","ра́дуйтеся, обітова́ннаго ми́ру Спаси́теля єдинокро́внії ю́жиці.","Ра́дуйтеся, святі́ї і пра́веднії Богоотці́ Іоаки́мі і А́нно."]},{"h":"Кондак 1","ps":["Ізбра́ннії от челові́чеськаго ро́да прароди́теліє Христо́ви, ро́ждшії Преблагослове́нную Богоотрокови́цю, із Нея́же по пло́ті Син Бо́жий роди́ся, святі́ї і пра́веднії Богоотці́ Іоаки́мі і А́нно! Я́ко іму́щії дерзнове́ніє ве́ліє ко Христу́ Бо́гу і ви́ну предстоя́щії Престо́лу Єго́ небе́сному, Тому́ прилі́жно молі́теся от бід нам ізба́витися, да ви́ну зове́м вам:","Ра́дуйтеся, святі́ї і пра́веднії Богоотці́ Іоаки́мі і А́нно."]},{"h":"Молитва","ps":["О присносла́внії Христо́ви пра́ведници, святі́ї Богоотці́ Іоаки́мі і А́нно, предстоя́щії небе́сному Престо́лу Вели́каго Царя́ і ве́ліє дерзнове́ніє к Нему́ іму́щії, я́ко от Преблагослове́нния Дще́ри ва́шея, Пречи́стия Богоро́диці і Присноді́ви Марі́ї, воплоти́тися ізво́лившему, к вам, я́ко многомо́щним предста́телем і усе́рдним о нас моли́твенникам, прибіга́єм ми, грі́шнії і недосто́йнії. Молі́те бла́гость Єго́, я́ко да отврати́ть от нас гнів Свой, по діло́м на́шим пра́ведно на ни дви́жимий, і да безчи́сленния прегріше́нія на́ша презрі́в, обрати́ть нас на путь покая́нія і на стезі́ за́повідей Свої́х да утверди́ть нас. Та́же моли́твами ва́шими в ми́рі живо́т наш сохрані́те і во всіх благи́х благо́є поспіше́ніє іспросі́те, вся я́же к животу́ і благоче́стію потре́бная нам от Бо́га да́рующе, от вся́ких напа́стей і бід і напра́сния сме́рті предста́тельством ва́шим нас ізбавля́юще, і от всіх враг ви́димих і неви́димих защища́юще, я́ко да ти́хоє і безмо́лвноє житіє́ поживе́м во вся́ком благоче́стії і чистоті́, і та́ко в ми́рі вре́менноє сіє́ житіє́ преше́дше, во ві́чний дости́гнем поко́й, іді́же ва́шим святи́м умоле́нієм да сподо́бимся Небе́снаго Ца́рствія Христа́ Бо́га на́шего, Єму́же со Отце́м і Пресвяти́м Ду́хом подоба́єть вся́кая сла́ва, честь і поклоне́ніє во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 2","ps":["Пра́ведних Твої́х, Го́споди, па́м'ять пра́зднующе, / ті́ми мо́лим Тя, // спаси́ ду́ші на́ша."]},{"h":"Інший тропар, глас 1","ps":["І́же в зако́нній благода́ті пра́ведні би́вше, / Младе́нця богода́ннаго породи́ша нам Іоаки́м і А́нна. / Ті́мже днесь сві́тло торжеству́єть, / ве́село пра́зднующи, Боже́ственная Це́рков, честну́ю ва́шу па́м'ять, / сла́вящи Бо́га, // воздви́гшаго рог спасе́нія нам в дому́ Дави́дові."]},{"h":"Кондак, глас 2","ps":["Ра́дується ни́ні А́нна, / непло́дства разріши́вшися соу́з, / і пита́єть Пречи́стую, / созива́ющи вся воспі́ти / Дарова́вшаго от чре́ва єя́ челові́ком // єди́ну Ма́тер і Неіскусому́жную."]},{"h":"Величання (на успіння прав. Анни)","ps":["Велича́єм тя, / свята́я пра́ведная А́нно / прама́ти Христа́ Бо́га на́шего, / і всечестно́є сла́вим / успе́ніє твоє́."]}],"notes":[]},{"u":"Акафіст святій рівноапостольній Марії Магдалині","e":"Akathist to the Holy Equal-to-the-Apostles Mary Magdalene","secs":[{"h":"Кондак 1","ps":["Угото́ванная Господом к равноапо́стольному служе́нію, свята́я Марі́є Магдали́но, возлю́бленному ті Христу́ послі́довала єси́: ті́мже пі́сньми с любо́вію восхваля́єм тя; ти же, я́ко іму́щая дерзнове́ніє ве́ліє ко Го́споду, от вся́ких нас бід моли́твами твої́ми ізба́ви, да с ра́достію ви́ну зове́м ті:","Ра́дуйся, свята́я равноапо́стольная Марі́є Магдали́но, па́че всіх благ Сладча́йшаго Го́спода Ісу́са возлюби́вшая."]},{"h":"Ікос 1","ps":["А́нгелов Творе́ць і Госпо́дь сил, предуві́дівий благо́є проізволе́ніє твоє́, свята́я мироно́сице, от гра́да Магдали ізбра́ тя, свободи́в от дия́вольськия сі́ті; ти же по сих ві́рная служи́тельниця Го́сподеві яви́лася єси́, ревну́ющи о прославле́нії Єго́ житіє́м і служе́нієм. Ми же, чудя́щеся таково́му о тебі́ Бо́жию смотре́нію, в умиле́нії серде́ць зове́м ті:","Ра́дуйся, от Си́на Бо́жия із тьми дия́вольськия в чу́дний світ Єго́ призва́нная;","ра́дуйся, Того́ благода́тію ті́лом і ду́хом до конця́ чи́ста преби́вшая.","Ра́дуйся, с чистото́ю се́рдця і нищету́ духо́вную до конця́ сохранившая;","ра́дуйся, пе́рвіє всіх воскре́сшаго Христа́ узрі́ти сподо́бившаяся.","Ра́дуйся, си́лу вра́жию до́брі побіди́вшая;","ра́дуйся, крі́пкою ві́рою і те́плою любо́вію ко Христу́ Бо́гу просія́вшая.","Ра́дуйся, всім се́рдцем Спа́са Христа́ возлюби́вшая;","ра́дуйся, ві́рно Тому́ да́же до сме́рти послужи́вшая.","Ра́дуйся, душе́ю твоє́ю благода́тно обновившаяся;","ра́дуйся, про́повідь Єва́нгелія в сокро́вище се́рдця своєго́ вмісти́вшая.","Ра́дуйся, про́повідь воскресе́нія апо́столом возвісти́вшая;","ра́дуйся, а́нгельською бесі́дою почтенная.","Ра́дуйся, свята́я равноапо́стольная Марі́є Магдали́но, па́че всіх благ Сладча́йшаго Го́спода Ісу́са возлюби́вшая."]},{"h":"Кондак 2","ps":["Ви́дящи свята́я Марі́я себе́ от седьми́ лю́тих бісо́в ізбавлену, всім се́рдцем побіди́телю а́да Христу́ Бо́гу приліпи́ся, вся лю́ди науча́ющи не усти́ то́кмо, но і всім житіє́м Бо́гу служи́ти, вопію́щи Тому́: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум челові́чеський недоуміва́єть, помишля́я, із какови́я біди́ на висоту́ ангелоподо́бнаго житія́ благода́тію Христо́вою возшла́ єси́, достохва́льная Марі́є Магдали́но. Ті́мже і ми, до́брую тя предста́тельницю іму́ще, мо́лимся тебі́ те́плі: ізба́ви і нас от бе́здни гріхо́вния, да любо́вію вопіє́м ті такова́я:","Ра́дуйся, лю́таго де́монськаго ра́бства ізбі́гшая;","ра́дуйся, лесть лука́вих бісо́в я́ві обличи́вшая.","Ра́дуйся, в напа́сти вражієй ко Христу́ Бо́гу прибіга́ти всіх научи́вшая;","ра́дуйся, нікому́же отчаява́тися во вели́цій гріхо́вній ско́рби побужда́ющая.","Ра́дуйся, ко свя́тости всім грі́шником путь показа́вшая;","ра́дуйся, всемо́щную си́лу благода́ті Христо́ви позна́вшая.","Ра́дуйся, досто́йнаго Бо́гу благодаре́нія до́брая наста́внице;","ра́дуйся, і́стиннаго богохваленія ві́рная учи́тельнице.","Ра́дуйся, в житії́ твоє́м пра́вий путь земна́го тече́нія нам показа́вшая;","ра́дуйся, всім грі́шником пред Бо́гом блага́я засту́пнице.","Ра́дуйся, душ на́ших от ле́сти сатани́нськия защи́тнице;","ра́дуйся, во вся́кой ско́рби те́плая ко Христу́ на́ша хода́тайце.","Ра́дуйся, свята́я равноапо́стольная Марі́є Магдали́но, па́че всіх благ Сладча́йшаго Го́спода Ісу́са возлюби́вшая."]},{"h":"Кондак 3","ps":["Си́лою Боже́ственния благода́ті, ку́пно же і свої́м благи́м проізволе́нієм безпеча́льно оста́вила єси́ дом отця́ твоєго́, я́коже дре́вле Авраа́м, і ра́достно послі́довала єси́ Христу́ Бо́гу; ті́мже мо́лим тя, учени́це Христо́ва, сла́вная Марі́є, моли́твами твої́ми і на́ша се́рдця просвіти́ любо́вію к Бо́гу, да і ни́ні і при́сно взива́єм Тому́: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́щи богодарова́нную ті прему́дрости си́лу, му́жеськи отве́ргла єси́, Марі́є Магдали́но, сего́ ми́ра кра́сная, і я́ко учениця до́брая, премно́гим милосе́рдієм обнища́вшему за ни Сло́ву і́стинно послужи́ла єси́. Сего́ ра́ди і ми со умиле́нієм вопіє́м ті:","Ра́дуйся, до́брая Христо́ва учени́це;","ра́дуйся, і́стинния любве́ к Бо́гу наста́внице.","Ра́дуйся, суєту́ ми́ра сего́ до́брі позна́вшая;","ра́дуйся, му́жеськи єго́ ра́дости отве́ргшая.","Ра́дуйся, кра́сная ми́ра ні во что́же вміни́вшая;","ра́дуйся, чи́ну і́ночеському до́брий путь житія́ предпоказавшая.","Ра́дуйся, всіх ко Христу́ Бо́гу путеводствующая;","ра́дуйся, для діл милосе́рдія із до́му земна́го ізше́дшая.","Ра́дуйся, Христо́во милосе́рдіє зді і на Небесі́ обрі́тшая;","ра́дуйся, я́ко тім блаже́нства ві́чнаго дости́гшая.","Ра́дуйся, му́драя а́гнице, от злих волко́в к до́брому па́стирю Христу́ прибі́гшая;","ра́дуйся, во двор слове́сних ове́ць Єго́ вше́дшая.","Ра́дуйся, свята́я равноапо́стольная Марі́є Магдали́но, па́че всіх благ Сладча́йшаго Го́спода Ісу́са возлюби́вшая."]},{"h":"Кондак 4","ps":["Бу́ря бісо́вськия я́рости превеликою си́лою устреми́ся на храм душі́ твоєя́, свята́я Марі́є, но того́ поколеба́ти до конця́ не возмо́же: обріла́ бо єси́ спасе́ніє на тве́рдем ві́ри Христо́ви ка́мені, на не́мже ти, му́драя же́но, недви́жимо стоя́щи, учи́ши всіх всеблаго́му Бо́гу воспіва́ти піснь: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шаще, богому́драя Марі́є, я́ко в послі́дованії Христу́ обріла́ єси́ і́стинноє весе́ліє се́рдця, пра́вду, мир і ра́дость о Ду́сі Свя́те, тщі́мся і ми яви́тися в ли́ці прича́стник сего́ Ца́рства Бо́жия. Тебі́ же, я́ко прича́стнице того́ су́щей і путь нам к нему́ показавшей, рцем всі такова́я:","Ра́дуйся, небе́сную Ісу́сову сла́дость возлюби́вшая;","ра́дуйся, жизнь і́стинную во Христі́ обрі́тшая.","Ра́дуйся, тоя́жде о́браз і нам ві́рно показа́вшая;","ра́дуйся, в ра́дості небе́сній ни́ні при́сно живу́щая.","Ра́дуйся, ра́йськія сні́ди ви́ну вкушающая;","ра́дуйся, огнь любве́ к Бо́гу в се́рдці твоє́м возже́гшая.","Ра́дуйся, Христо́м Бо́гом, я́ко раба́ Єму́ ві́рная, возлю́бленная;","ра́дуйся, прилі́жная о нас к Бо́гу моли́твеннице.","Ра́дуйся, в біда́х на́ших помо́щнице;","ра́дуйся, на́ша блага́я і кро́ткая учи́тельнице.","Ра́дуйся, Ду́ха Свята́го пречестно́є жили́ще.","Ра́дуйся, свята́я равноапо́стольная Марі́є Магдали́но, па́че всіх благ Сладча́йшаго Го́спода Ісу́са возлюби́вшая."]},{"h":"Кондак 5","ps":["Боготе́чная звізда́, спутствующи Христу́, сла́вная Марі́є, посреді́ мироно́сиць яви́лася єси́. С ни́ми же ни́ні ви́ну предстоя́щи Святі́й Тро́йці, і нас моли́твами твої́ми к свяще́нному тіх ли́ку совокупи́, путь те́мний житія́ на́шего сві́том твої́м озаря́ющи, да ра́достно возопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дящи, свята́я Марі́є, Христа́ Бо́га на кресті́ ви́сяща, ди́вноє му́жество показа́ла єси́: мно́зі бо от учени́к Учи́теля своєго́ оста́виша; ти же, непреста́нними боже́ственними уче́ньми Того́ ду́шу і мисль разже́гши, не́мощ єстества́ же́нськаго превозмогла єси́ і та́ко причасти́лася єси́ спаси́тельній Христо́вой стра́сті. Сего́ ра́ди ми, сицево́є твоє́ до́блественноє му́жество зря́ще, вопіє́м ті:","Ра́дуйся, му́дрих жен красото́ і удобре́ніє;","ра́дуйся, христия́н всіх до́броє ра́дованіє.","Ра́дуйся, Христу́ Бо́гу, на кресті́ ви́сящу, сострадавшая;","ра́дуйся, непоколеби́мій любві́ к Тому́ нам путь показа́вшая.","Ра́дуйся, сицево́ю любо́вію в предста́тельстві о нас к Бо́гу дерзнове́ніє ве́ліє обрі́тшая;","ра́дуйся, жена́м добро́то і похвале́ніє.","Ра́дуйся, христия́ном крі́пкоє прибі́жище;","ра́дуйся, па́че си́льних муже́й кріпча́йшая.","Ра́дуйся, мудрецо́в ми́ра сего́ мудрі́йшая;","ра́дуйся, я́ко тебі́ та́йная прему́дрости Своєя́ Бог яви́л єсть.","Ра́дуйся, я́ко тебі́ і́стинному богосло́вію Сам Бог Сло́во научи́л єсть;","ра́дуйся, Христа́ Бо́га па́че жи́зні своєя́ возлюби́вшая.","Ра́дуйся, свята́я равноапо́стольная Марі́є Магдали́но, па́че всіх благ Сладча́йшаго Го́спода Ісу́са возлюби́вшая."]},{"h":"Кондак 6","ps":["Благода́тію Твоє́ю не́мощная врачу́єши і некрепкия сосу́ди тве́рди соді́ловаєши, Христе́ Царю́. Мироно́сиці бо жени́ у Креста́ Твоєго́ му́жеськи предстоя́ть і благода́ть кре́стную всім небоя́зненно возвіща́ють; лиці́ же му́дрих жен, ликам а́нгельським уподо́битися тща́щеся, бо́дренно ви́ну взива́ють Тро́йці Святі́й: Аллилу́я."]},{"h":"Ікос 6","ps":["Взиску́ющи озари́тися сві́том і́стиннаго богоразу́мія, єгда́ Бо́га на Кресті́ ви́сяща ви́діла єси́, глаго́лала єси́ слезя́щи, ди́вная Марі́є: ка́ко Жизнь смерть во́льную ни́ні приє́млеть? Ми же, сла́вноє просвіще́ніє твоє́ благода́тію Свята́го Ду́ха ві́дуще, вопіє́м ті сицева́я:","Ра́дуйся, Христа́ ра́сп'ята от глубини́ душі́ оплакавшая;","ра́дуйся, весе́ліє ві́чноє в селе́ніїх небе́сних обрі́тшая.","Ра́дуйся, нам о́браз до́браго пла́ча показа́вшая;","ра́дуйся, я́ко ти єси́ на́ше непреста́нноє ра́дованіє.","Ра́дуйся, всіх скорб'я́щих утіше́ніє нело́жноє;","ра́дуйся, я́ко Христу́, Єго́ ра́ди, на землі́ спострадала єси́.","Ра́дуйся, я́ко с Ним о Нем на Небесі́ прославля́єшися;","ра́дуйся, всіх враго́в на́ших крі́пкая побіди́тельнице.","Ра́дуйся, во всіх ско́рбіх на́ших ско́рая помо́щнице;","ра́дуйся, я́ко всім христия́ном воспомина́ніє твоє́ пресла́дко.","Ра́дуйся, я́ко всій Це́ркві Христо́вой і́м'я твоє́ прече́стно;","ра́дуйся, і́стинная лозо́ виногра́да Христо́ва.","Ра́дуйся, свята́я равноапо́стольная Марі́є Магдали́но, па́че всіх благ Сладча́йшаго Го́спода Ісу́са возлюби́вшая."]},{"h":"Кондак 7","ps":["Хотя́щи уразумі́ти Креста́ всепобедительную си́лу, до конця́ Христо́вой стра́сті предстоя́ла єси́ у креста́ Спасова со іни́ми жена́ми, пресла́вная Марі́є. Ма́тері же Госпо́дні болі́зненно состра́ждущи, та́ко недоумі́нно вопія́ла єси́: что сіє́ єсть стра́нноє чу́до? Содержа́й всю твар пострада́ти ізво́ли. Ми же на Живоно́сний Крест во́лею Возне́сшемуся любо́вію вопіє́м: Аллилу́я."]},{"h":"Ікос 7","ps":["Ди́вная жена́ яви́лася єси́, блаже́нная Марі́є, любо́вію твоє́ю ко Христу́ Бо́гу: ту́ю бо горестними із'являя рида́ньми, ко снятому со Креста́ припа́дающи, слеза́ми пречи́стия я́зви Єго́ оми́ла єси́. Єще́ же благообра́зному Іо́сифу і правдолюбивому Никоди́му послі́дующи, ко гро́бу Спа́сову со іни́ми святи́ми жена́ми текла́ єси́, о́во пла́чущи, о́во пла́чущу неуті́шно Ма́тер Єго́ Пренепоро́чную, Єй же ду́шу лю́тоє ору́жіє про́йде, утешающи. Ми же, такову́ю твою́ до́блесть ві́дуще, смире́нно взива́єм ті:","Ра́дуйся, пречи́стия я́зви Христо́ви слеза́ми омившая;","ра́дуйся, Ма́тері Того́ Пренепоро́чній я́ві сострадавшая.","Ра́дуйся, Христа́ да́же до гро́ба не оставившая;","ра́дуйся, во гроб полагавшуюся Жизнь недоумі́нно зревшая.","Ра́дуйся, слеза́м покая́нія на́ша до́брая учи́тельнице;","ра́дуйся, ті́ми слеза́ми гріхо́вния скве́рни омивати нас наставля́ющая.","Ра́дуйся, ті́ми же се́рдце на́ше окамене́нноє ум'ягчати побужда́ющая;","ра́дуйся, о́браз і́стинной му́дрости нам показа́вшая.","Ра́дуйся, па́м'ятовати ви́ну стра́сті Христо́ви нас науча́ющая;","ра́дуйся, сла́вная Марі́є, ку́пно с Пренепоро́чною Ді́вою Марі́єю, на́ша ві́рная хода́тайце.","Ра́дуйся, до́брая слуго́ Христо́ва;","ра́дуйся, Го́сподеві, а не челові́ком угождавшая.","Ра́дуйся, свята́я равноапо́стольная Марі́є Магдали́но, па́че всіх благ Сладча́йшаго Го́спода Ісу́са возлюби́вшая."]},{"h":"Кондак 8","ps":["Стра́нно, богому́драя Марі́є, яви́ся тебі́ погребе́ніє всім жизнь подаю́щаго Жизнода́вця: Того́ любо́вію уязвля́єма, єще́ су́щей тьмі, ко гро́бу Єго́ принесла́ єси́ ми́ро і сле́зния пролила єси́ арома́ти. Ті́мже і пребива́єши ни́ні во благово́нних рая́ селе́ніїх, со а́нгельськими ли́ки взива́ющи ви́ну Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь сла́дость, весь ра́дость, весь жизнь тебі́ бисть Ісу́с, свята́я Марі́є, Того́ ра́ди, ви́дівши ка́мень взят от гро́ба, Сего́ же не обрі́тши, рида́ющи текла́ єси́ к живо́му ві́ри ка́мені Си́мону і друго́му, єго́же любля́ше Ісу́с, ученику́, болі́зненно глаго́лющи і́ма: взя́ша Го́спода от гро́ба і не вім, гді положи́ша Єго́. Ни́ні же ти, свободи́вшися от ско́рби тоя́, со Христо́м ві́чно ра́дуєшися на Небесі́. Ми же на землі́ в такову́ю ра́дость моли́твами твої́ми вни́ти ча́юще, со умиле́нієм вопіє́м ті та́ко:","Ра́дуйся, сія́нієм любве́ твоєя́ ко Христу́ тьму ночную побіди́вшая;","ра́дуйся, нощному бді́нію в моли́тві нас научи́вшая.","Ра́дуйся, сві́том ві́чним на Небесі́ осія́нная;","ра́дуйся, нището́ю духо́вною Ца́рство Небе́сноє купившая.","Ра́дуйся, я́ко по ско́рбі о страстеіх Христо́вих обріла́ єси́ оби́льноє утіше́ніє;","ра́дуйся, же́но кро́ткая, наслі́днице землі́ Небе́снаго рая́.","Ра́дуйся, алкавшая і жаждавшая пра́вди Христо́ви, я́ко ти ни́ні насища́єшися трапе́зи Небе́сния;","ра́дуйся, ми́лостивая, ми́лость Влади́ки обрі́тшая і о на́шем поми́лованії Того́ усе́рдно прося́щая.","Ра́дуйся, ти бо ни́ні, я́ко чи́стая се́рдцем, Бо́га лице́м к лицю́ зри́ши;","ра́дуйся, я́ко сподо́билася єси́ пе́рвіє всіх ви́діти воскресе́ніє Христа́, Ві́чнаго Ми́ра.","Ра́дуйся, ізгна́нная пра́вди ра́ди Христо́ви, я́ко твоє́ єсть Ца́рство Бо́жиє;","ра́дуйся, приобретшая ві́чноє весе́ліє і мзду мно́гу на Небесі́х.","Ра́дуйся, свята́я равноапо́стольная Марі́є Магдали́но, па́че всіх благ Сладча́йшаго Го́спода Ісу́са возлюби́вшая."]},{"h":"Кондак 9","ps":["Всяк чин а́нгельський удиви́ся вели́кой та́йні сла́внаго воскресе́нія Твоєго́, Христе́ Царю́; ад же притрепетен бисть, ви́дів, я́ко снизше́л єси́ в преіспо́дняя землі́ і сокруши́л єси́ вереї́ ві́чния, содержа́щия св'я́занния, Христе́. Ми же ра́дости жен мироно́сиць сорадующеся, с весе́лієм вопіє́м: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́й многовещанних язи́ки не довлі́ють досто́йно ізрещи́ вели́кую скорб твою́, сла́вная Марі́є, єгда́ стоя́ла єси́ вні гро́ба пла́чущи. Кто бо возмо́жеть рещи́ болі́знь душі́ твоєя́, єгда́ не обріла́ єси́ во гро́бі па́че жи́зні своєя́ возлю́бленнаго ті Го́спода? Прискорбноє се́рдце твоє́ не возмо́же внима́ти утіше́нію А́нгелов сві́тлих. Сицеву́ю скорб твою́ со умиле́нієм воспомина́юще, воспіва́єм ті такова́я:","Ра́дуйся, ви́діти Христа́ Ісу́са в пеще́ру приникшая;","ра́дуйся, ни́ні Того́ на Престо́лі Сла́ви сідя́ща зря́щая.","Ра́дуйся, сві́тлих небожи́телей єще́ су́щи на землі́ узревшая;","ра́дуйся, от тіх глас ра́дости воскресе́нія Христо́ва приі́мшая.","Ра́дуйся, я́ко ти с ни́ми ни́ні при́сно ра́дуєшися;","ра́дуйся, любо́вію ми́ро Христу́ прине́сшая.","Ра́дуйся, во благоухающую ми́ра Христо́ва воню́ сла́дці прите́кшая;","ра́дуйся, отве́ргшая ра́достей ми́ра гріхо́внаго гореч.","Ра́дуйся, возлюби́вшая небе́сную Ісу́сову сла́дость;","ра́дуйся, до́брая лі́торасле са́да Ісу́сова.","Ра́дуйся, благопло́дная лозо́ вертогра́да Бо́жия;","ра́дуйся, преукраше́нний храм Ду́ха Всесвята́го я́вльшаяся.","Ра́дуйся, свята́я равноапо́стольная Марі́є Магдали́но, па́че всіх благ Сладча́йшаго Го́спода Ісу́са возлюби́вшая."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ мир, а́ще і во гроб снизше́л єси́ безсме́ртне, но а́дову разруши́л єси́ си́лу і воскре́сл єси́, я́ко побіди́тель, Христе́ Бо́же, жена́м мироно́сицям віща́вий: ра́дуйтеся. С ни́ми же і ми ни́ні піснь ра́дости прино́сим Ті: Аллилу́я."]},{"h":"Ікос 10","ps":["Сті́ни ка́менния тве́рдоє бисть любо́в твоя́ к возлю́бльшему тя Христу́, мироно́сице сла́вная Магдали́но Марі́є. Ті́мже єди́на ви́діла єси́ пре́жде іні́х Живота́ на́шего із гро́ба возставша. Вертогра́даря же Того́ непщева́ла єси́ би́ти і вопія́ла єси́ Тому́, заби́вши єстества́ не́мощ: «А́ще ти єси́ взял Єго́, пові́ждь мі, гді єси́ положи́л Єго́, і аз возьму Єго́». Но сла́достний Того́ глас показа́ ті Учи́теля, нас же глаша́ти научи́ тебі́ си́це:","Ра́дуйся, і́стиннаго Вертогра́даря воскре́сша пе́рвіє іні́х узревшая;","ра́дуйся, во вертогра́ді Небе́снім водвори́вшаяся.","Ра́дуйся, гро́здієм Бо́жия благода́ті ни́ні ви́ну пита́ющаяся;","ра́дуйся, вино́м ра́йських ра́достей веселя́щаяся.","Ра́дуйся, я́ко твоя́ любо́в к Бо́гу єстество́ побіди́ла єсть;","ра́дуйся, я́ко та́я і нас ре́вности Бо́жієй научи́ла єсть.","Ра́дуйся, із уст Христо́вих віща́ніє воскресе́нія пе́рвіє приє́мшая;","ра́дуйся, апо́столом глаго́ли ра́дости пе́рвіє возвісти́вшая.","Ра́дуйся, ві́чную ра́дость на Небесі́ обрі́тшая;","ра́дуйся, я́ко ти і нас к той ра́дости тобо́ю зове́ши.","Ра́дуйся, я́ко о сем о нас к Бо́гу ви́ну хода́тайствуєши;","ра́дуйся, я́ко Тому́ моли́тви о нас те́плі прино́сиши.","Ра́дуйся, свята́я равноапо́стольная Марі́є Магдали́но, па́че всіх благ Сладча́йшаго Го́спода Ісу́са возлюби́вшая."]},{"h":"Кондак 11","ps":["Ні єди́но же сло́во довлі́єть воспі́ти по достоя́нію боже́ственную ра́дость воскресе́нія Христо́ва, ю́же со іни́ми жена́ми, сла́вная Марі́є, апо́столом возвісти́ в сей нарече́нний і святи́й день, пра́здников пра́здник і торжество́ із торже́ств. Ті́мже, пред вели́чієм неізрече́нних щедро́т Твої́х, Христе́ Царю́, на нас би́вших, преклоня́ющеся, со смире́нієм і любо́вію зове́м Ті: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоза́рная звізда́ гріхо́вному ми́ру яви́лася єси́, Магдали́но Марі́є, єгда́ по сла́внім Спасові вознесе́нії, гра́ди і ве́сі преходя́щи і сло́во Єва́нгелія всю́ду возвіща́ющи, мно́гі подклонила єси́ под благо́є і́го Христо́во. Дости́гши же да́же до дре́вняго Ри́ма, му́жеськи Тиве́рію ке́сарю предста́ла єси́ і тому́ о́бразом кра́снаго яйця і му́дрими словеси́ живоно́сную си́лу Христа́ уясни́ла єси́, лука́ваго же Пила́та і безбо́жнаго архієре́я обличала єси́, да по беззако́нним ді́лом свої́м досто́йная при́ймуть, таково́му по́двигу апо́стольства твоєго́ див'я́щеся, ра́достно вопіє́м ті си́це:","Ра́дуйся, Христо́ва уче́нія сла́вная благовестительнице;","ра́дуйся, язи́чеськия тьми світоза́рная прогони́тельнице.","Ра́дуйся, греховниє у́зи мно́гих челові́к разріши́вшая;","ра́дуйся, Христо́вой му́дрости всіх научи́вшая.","Ра́дуйся, мно́гіє лю́ди із тьми неві́дінія в чу́дний Христа́ світ приве́дшая;","ра́дуйся, о́браз тве́рдаго стоя́нія за пра́вду Христо́ву нам показа́вшая.","Ра́дуйся, спасе́ніє душ грі́шников па́че своєя́ жи́зні возлюби́вшая;","ра́дуйся, за́повіді Христо́ви до́брі уразумі́вшая.","Ра́дуйся, тім ві́рно последовавшая;","ра́дуйся, тьму язи́чеськую дерзнове́нно обличи́вшая.","Ра́дуйся, гні́ва ке́сарева не убоявшаяся;","ра́дуйся, зло́бу і кова́рство враго́в Христо́вих тому́ показа́вшая.","Ра́дуйся, свята́я равноапо́стольная Марі́є Магдали́но, па́че всіх благ Сладча́йшаго Го́спода Ісу́са возлюби́вшая."]},{"h":"Кондак 12","ps":["Благода́ті от Бо́га ізоби́льно іспо́лненная, мно́жество душ ко Христу́ привела́ єси́, сла́вная Марі́є, по сем же пришла́ єси́ во Єфе́с, іді́же апо́стольськи любо́вію с Апо́столом любве́ спасе́нію челові́к послужи́вши, блаже́нним успе́нієм ко Го́споду преста́вилася єси́, Єму́же ни́ні с многочи́сленними небе́сними півці́ ви́ну поє́ши: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще твоє́ достохва́льноє житіє́ на землі́ і сла́ву, я́же на Небесі́, ра́достно сла́вим, поє́м і велича́єм ди́внаго во святи́х Свої́х Царя́ Небе́снаго, зане́ не то́кмо сама́ ти, свята́я Марі́є, Того́ благода́тію в селе́ніїх пра́ведних ни́ні лику́єши, но і нас весели́ши на землі́, оста́вивши нам многоці́нноє ми́ро моще́й твої́х, я́же му́дрий Лев цар із Єфе́са в Константи́н град пренести́ повелі́. Ти́я і ми, я́ко істоча́ющия благода́ть неоску́дную всім любо́вію притекающим, ві́рою і любо́вію ми́сленно лобиза́юще, уми́льно воспіва́єм ті такова́я:","Ра́дуйся, на землі́ любо́вію ко Христу́ горі́вшая;","ра́дуйся, на Небесі́ в ра́йськия оби́телі Того́ вселившаяся.","Ра́дуйся, ві́рним тве́рдоє заступле́ніє;","ра́дуйся, благово́нноє ми́ро, Це́рков благоуха́ющеє.","Ра́дуйся, кади́льнице злата́я, фиміа́м моли́тви о нас к Бо́гу ви́ну принося́щая;","ра́дуйся, істо́чник ісціле́ній неоску́дний.","Ра́дуйся, сокро́вище Бо́жієй благода́ті неіждива́ємоє;","ра́дуйся, а́нгельських лико́во ві́рная соучастнице.","Ра́дуйся, Небе́сних черто́гов сла́вная жительнице;","ра́дуйся, я́ко мзда твоя́ мно́га єсть на Небесі́х.","Ра́дуйся, я́ко ра́дость твоя́ ві́чна єсть во оби́теліх святи́х;","ра́дуйся, я́ко ти і нам прия́ти ра́дость, благода́ть же і сла́ву ви́ну хода́тайствуєши.","Ра́дуйся, свята́я равноапо́стольная Марі́є Магдали́но, па́че всіх благ Сладчайшего Го́спода Ісу́са возлюби́вшая."]},{"h":"Кондак 13","ps":["О пречу́дноє і преди́вноє жен украше́ніє, всім же христия́ном похвала́ і ра́дованіє, апо́столом ра́вная я́вльшаяся, мироно́сице сла́вная Магдали́но Марі́є! Ни́нішнєє на́ше моле́ніє приє́мши, от вся́ких нас бід і скорбе́й душе́вних і тіле́сних і от враг ви́димих і неви́димих, на нас находя́щих, ізба́ви і к Ца́рствію Небе́сному хода́тайством твої́м напра́ви всіх, со умиле́нієм і любо́вію пою́щих о тебі́ Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов Творе́ць і Госпо́дь сил, предуві́дівий благо́є проізволе́ніє твоє́, свята́я мироно́сице, от гра́да Магдали ізбра́ тя, свободи́в от дия́вольськия сі́ті; ти же по сих ві́рная служи́тельниця Го́сподеві яви́лася єси́, ревну́ющи о прославле́нії Єго́ житіє́м і служе́нієм. Ми же, чудя́щеся таково́му о тебі́ Бо́жию смотре́нію, в умиле́нії серде́ць зове́м ті:","Ра́дуйся, от Си́на Бо́жия із тьми дия́вольськия в чу́дний світ Єго́ призва́нная;","ра́дуйся, Того́ благода́тію ті́лом і ду́хом до конця́ чи́ста преби́вшая.","Ра́дуйся, с чистото́ю се́рдця і нищету́ духо́вную до конця́ сохранившая;","ра́дуйся, пе́рвіє всіх воскре́сшаго Христа́ узрі́ти сподо́бившаяся.","Ра́дуйся, си́лу вра́жию до́брі побіди́вшая;","ра́дуйся, крі́пкою ві́рою і те́плою любо́вію ко Христу́ Бо́гу просія́вшая.","Ра́дуйся, всім се́рдцем Спа́са Христа́ возлюби́вшая;","ра́дуйся, ві́рно Тому́ да́же до сме́рти послужи́вшая.","Ра́дуйся, душе́ю твоє́ю благода́тно обновившаяся;","ра́дуйся, про́повідь Єва́нгелія в сокро́вище се́рдця своєго́ вмісти́вшая.","Ра́дуйся, про́повідь воскресе́нія апо́столом возвісти́вшая;","ра́дуйся, а́нгельською бесі́дою почтенная.","Ра́дуйся, свята́я равноапо́стольная Марі́є Магдали́но, па́че всіх благ Сладча́йшаго Го́спода Ісу́са возлюби́вшая."]},{"h":"Кондак 1","ps":["Угото́ванная Господом к равноапо́стольному служе́нію, свята́я Марі́є Магдали́но, возлю́бленному ті Христу́ послі́довала єси́: ті́мже пі́сньми с любо́вію восхваля́єм тя; ти же, я́ко іму́щая дерзнове́ніє ве́ліє ко Го́споду, от вся́ких нас бід моли́твами твої́ми ізба́ви, да с ра́достію ви́ну зове́м ті:","Ра́дуйся, свята́я равноапо́стольная Марі́є Магдали́но, па́че всіх благ Сладча́йшаго Го́спода Ісу́са возлюби́вшая."]},{"h":"Молитва перша","ps":["О свята́я мироно́сице і всехва́льная равноапо́стольная Христо́ва учени́це Магдали́но Марі́є! К тебі́, я́ко ві́рній і мо́щній о нас к Бо́гу хода́тайце, грі́шнії і недосто́йнії, ни́ні усе́рдно прибіга́єм і в сокруше́нії серде́ць на́ших мо́лимся. Ти в житії́ своє́м стра́шния ко́зні бісо́вськия іспита́ла єси́, но благода́тію Христо́вою я́вно тіх свободи́лася єси́, і нас моли́твами твої́ми от сі́ті бісо́вськия ізба́ви, да ви́ну во всем житії́ на́шем ді́лом, сло́вом, ми́слію і та́йними помишле́нії серде́ць на́ших ві́рно послу́жим єди́ному Свято́му Влади́ці Бо́гу, я́коже Тому́ обещалися єсьми́. Ти па́че всіх благ земни́х сладча́йшаго Го́спода Ісу́са возлюби́ла єси́ і Тому́ чрез все житіє́ до́брі послі́довала єси́, Боже́ственними уче́нії Єго́ і благода́тію не то́кмо свою́ ду́шу пита́ющи, но і мно́жество люде́й от тьми язи́чеськия ко Христа́ чу́дному сві́ту приводя́щи; то ві́дуще, про́сим тя: іспроси́ нам у Христа́ Бо́га благода́ть просвіща́ющую і освяща́ющую, да, є́ю осіня́ємі, преуспіва́єм во ві́рі і благоче́стії, в по́двизіх любве́ і самоотверже́нія, да нелі́ностно тщі́мся служи́ти бли́жнім в їх ну́ждах духо́вних і тіле́сних, пам'яту́юще примі́р твоєго́ человіколю́бія. Ти, свята́я Марі́є, бо́дренно благода́тію Бо́жиєю протекла єси́ житіє́ на землі́ і ми́рно отшла́ єси́ во оби́телі Небе́сния, моли́ Христа́ Спа́са, да моли́твами твої́ми сподо́бит нас непреткнове́нно соверши́ти стра́нствіє на́ше в сей юдо́лі пла́ча і в ми́рі і покая́нії сконча́ти живо́т наш, да та́ко і в свя́тости на землі́ пожи́вше, ві́чния блаже́нния жи́зні на Небесі́ сподо́бимся і та́мо с тобо́ю і всі́ми святи́ми вку́пі ви́ну восхва́лим Тро́йцю Неразді́льную, воспої́м Єди́но Божество́, Отця́ і Си́на і Ду́ха Всесвята́го, во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["О свята́я мироно́сице, равноапо́стольная Магдали́но Марі́є! Ти те́плою любо́вію своє́ю ко Христу́ Бо́гу попра́ла єси́ зли́я ко́зні вра́жия і обріла́ єси́ безці́нний би́сер, Христа́, і дости́гла єси́ Ца́рства Небе́снаго. Сего́ ра́ди к тебі́ припа́даю і умиле́нною душе́ю і сокруше́нним се́рдцем вопію́ ті, аз, недосто́йний: при́зри с висоти́ Небе́сния на м'я, бори́маго гріхо́вними іскуше́нії, виждь, коль мно́гими гріхи́ і біда́ми на всяк день враг запина́єть м'я, іща́ моєя́ поги́белі. Сла́вная і всехва́льная учени́це Христо́ва Марі́є! Умоли́ возлю́бленнаго тобо́ю і возлюби́вшаго тя Христа́ Бо́га, да пода́сть мі оставле́ніє мно́гих мої́х прегріше́ній, укріпи́ть м'я благода́тію Своє́ю тре́звенно і бо́дренно ше́ствовати путе́м святи́х за́повідей Єго́ і да соді́лаєть м'я благоуха́нний храм Ду́ха Свята́го, да та́ко в ми́рі непости́дно сконча́ю многотру́дноє житіє́ моє́ на землі́ і вселю́ся во сві́тлия і блаже́нния оби́телі рая́ Небе́снаго, іді́же ти со всі́ми святи́ми ви́ну ра́достно славосло́виши Єдиносу́щную Тро́йцю, Отця́, Си́на і Ду́ха Всесвята́го. Амі́нь."]},{"h":"Тропар, глас 1","ps":["Христу́, нас ра́ди от Ді́ви ро́ждшемуся, / честна́я Магдали́но Марі́є, послі́довала єси́, / Того́ оправда́нія і зако́ни храня́щи. / Ті́мже днесь всесвяту́ю твою́ па́м'ять пра́зднующе, / гріхо́в разріше́ніє // моли́твами твої́ми приє́млем."]},{"h":"Кондак, глас 3","ps":["Предстоя́щи, пресла́вная, у Креста́ Спа́сова со іни́ми мно́гими, / і Ма́тері Госпо́дні состра́ждущи, і сле́зи точа́щи, / сіє́ в похвалу́ приноша́ше глаго́лющи: / что сіє́ єсть стра́нноє чу́до? / Содержа́й всю твар, пострада́ти ізво́ли. // Сла́ва держа́ві Твоє́й."]},{"h":"Величання","ps":["Велича́єм тя, / мироно́сице свята́я равноапо́стольная Марі́є Магдали́но, / і чтим болі́зні і труди́ твоя́, / ї́миже труди́лася єси́ / во благові́стії Христо́ві."]}],"notes":[]},{"u":"Акафіст святителю Луці, сповіднику, архієпископу Кримському","e":"Akathist to St Luke, Confessor, Archbishop of Crimea","secs":[{"h":"Кондак 1","ps":["Ізбра́нний святи́телю Це́ркве Правосла́вния і іспові́дниче, возсія́вий страні́ на́шей, я́ко світоза́рноє світи́ло, до́брі потруди́вийся і за і́м'я Христо́во гоне́ніє претерпі́вий, прославля́юще просла́вльшаго тя Го́спода, дарова́вшаго нам тебе́ но́ваго моли́твенника і помо́щника, похва́льноє воспіва́єм ті пі́ніє; ти же, я́ко імі́яй ве́ліє дерзнове́ніє ко Влади́ці Небесе́ і землі́, от вся́ких неду́гов душе́вних і тіле́сних свободи́ нас і до́брі стоя́ти во Правосла́вії укріпи́, да всі во умиле́нії зове́м ті:","Ра́дуйся, святи́телю і іспові́дниче Луко́, врачу́ благи́й і ми́лостивий."]},{"h":"Ікос 1","ps":["А́нгелов собесі́дниче і челові́ков наста́вниче, Луко́ пресла́вний, подо́бні євангели́сту і апо́столу Луці́, єму́же тезоімени́ть сий, от Бо́га дар ціли́ти неду́ги челові́чеськія прия́л єси́, мно́гія труди́ под'є́мля во врачева́нії болі́зней бли́жніх, плоть нося́, о пло́ті не раді́л єси́, ді́ли же до́брими Отця́ Небе́снаго просла́вил єси́. Ті́мже благода́рні во умиле́нії зове́м ті:","Ра́дуйся, от ю́ности ра́зум свой і́гу Христо́ву покори́вий;","ра́дуйся, пречестно́є Святи́я Тро́йці селе́ніє би́вий.","Ра́дуйся, блаже́нство ми́лостивих, по сло́ву Го́спода, унаслі́довавий;","ра́дуйся, ві́рою Христо́вою і зна́нієм богодарова́нним мно́гія неду́жния ісціли́вий.","Ра́дуйся, стра́ждущих неду́ги тіле́сними врачу́ милосе́рдний;","ра́дуйся, во дні бра́ні вожде́й і во́їнов ціли́телю іску́сний.","Ра́дуйся, всіх враче́в наста́вниче;","ра́дуйся, ско́рий в ну́ждах і ско́рбіх су́щим помо́щниче.","Ра́дуйся, Це́ркве Правосла́вния утвержде́ніє;","ра́дуйся, землі́ на́шея озаре́ніє.","Ра́дуйся, кри́мськия па́стви похвале́ніє;","ра́дуйся, гра́да Симферо́поля украше́ніє.","Ра́дуйся, святи́телю і іспові́дниче Луко́, врачу́ благи́й і ми́лостивий."]},{"h":"Кондак 2","ps":["Ви́дя в челові́ціх во вре́м'я врачева́ній, а́ки в зерца́лі, прему́дрость і сла́ву Творця́ вся́чеських Бо́га, к Нему́ ду́хом всегда́ возноси́лся єси́, богому́дре; сві́том же богоразу́мія твоєго́ і нас озари́, да вопіє́м ку́пно с тобо́ю: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум твой Боже́ственними уче́ньми просвіти́л єси́, Луко́ всесла́вне, отве́ргнув вся́коє плотсько́є мудрова́ніє, с ра́зумом же і во́лю повину́л єси́ Го́сподеві, подо́бен апо́столом бив. Ті́ї бо, по сло́ву Христо́ву: гряді́те по Мні, і сотворю́ ви ловці́ челові́ком, оста́виша вся і по Нем ідо́ша, і ти, свя́те, усли́шав Го́спода Ісу́са, зову́щаго тя на служе́ніє, приє́млеши свяще́нство в Це́ркві Правосла́вній. Сего́ ра́ди, я́ко богому́драго наста́вника тя ублажа́юще, воспіва́єм си́це:","Ра́дуйся, о душі́ при́сноє попече́ніє показа́вий;","ра́дуйся, А́нгела храни́теля твоєго́ возвесели́вий.","Ра́дуйся, во уче́нії преспіва́вий і мудреці́ ми́ра сего́ удиви́вий;","ра́дуйся, от творя́щих беззако́ніє стопи́ твоя́ уклони́вий.","Ра́дуйся, Бо́жия Прему́дрости пропові́дниче і созерца́телю;","ра́дуйся, і́стиннаго богосло́вія златослове́сний учи́телю.","Ра́дуйся, апосто́льських преда́ній блюсти́телю;","ра́дуйся, Правосла́вія ревни́телю.","Ра́дуйся, звіздо́, путь ко спасе́нію показу́ющая;","ра́дуйся, свіще́, Бо́гом возжже́нная, мрак нече́стія разгоня́ющая.","Ра́дуйся, раско́льников обличи́вий;","ра́дуйся, свиді́ній і оправда́ній Госпо́дніх возжада́вий.","Ра́дуйся, святи́телю і іспові́дниче Луко́, врачу́ благи́й і ми́лостивий."]},{"h":"Кондак 3","ps":["Си́лою благода́ті Бо́жия, єще́ во вре́менній жи́зні прия́л єси́ дар, свя́те Луко́, неду́ги ціли́ти, да всі усе́рдно притека́ющії к тебі́ ісціле́нія болі́зней тіле́сних і найпа́че душе́вних сподобля́ються, вопію́ще Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я неуси́пноє попече́ніє о спасе́нії душ, вві́ренних тебі́ от Бо́га, Луко́ блаже́нне, па́стирськи к душеспаси́тельной жи́зні і сло́вом, і са́мим ді́лом непреста́нно їх наставля́л єси́. Сего́ ра́ди прийми́ от на́шего усе́рдія похвали́, досто́йно тебі́ приноси́мия:","Ра́дуйся, ра́зума Боже́ственнаго іспо́лненний;","ра́дуйся, благода́тію Ду́ха Свята́го приосіне́нний.","Ра́дуйся, нището́ю Христо́вою обогати́вийся;","ра́дуйся, щі́те, защища́яй благоче́стіє.","Ра́дуйся, па́стирю до́брий, блужда́ющих по гора́м суєму́дрія взиска́вий;","ра́дуйся, ді́лателю виногра́да Христо́ва, чад Бо́жиїх во ві́рі укріпля́яй.","Ра́дуйся, непоколеби́мий Правосла́вія сто́лпе;","ра́дуйся, тве́рдий ка́меню ві́ри.","Ра́дуйся, душепа́губнаго неві́рія і обновле́нчеськаго раско́ла обличи́телю;","ра́дуйся, в ді́ланії духо́внім подвиза́ющихся му́дрий укріпи́телю.","Ра́дуйся, от ми́ра гони́мим приста́нище ти́хоє указу́яй;","ра́дуйся, я́ко приї́м крест, Христу́ послі́довал єси́.","Ра́дуйся, святи́телю і іспові́дниче Луко́, врачу́ благи́й і ми́лостивий."]},{"h":"Кондак 4","ps":["Бу́рю внутр імі́я помишле́ній мно́гих, недоуміва́ше раб Бо́жий, что рече́ть о нем Госпо́дь, єгда́ проразуміва́ху єго́ досто́йна би́ти єпи́скопом гра́ду Ташке́нту, оба́че всего́ себе́ Христу́ Бо́гу преда́в, Тому́ о всем благодаре́ніє возсила́ше, зови́й: благослове́н Бог, ізлива́яй благода́ть Свою́ на архієре́ї Своя́, і поя́ Єму́: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавше лю́діє правосла́внії, в гоне́нії су́щії, о благопло́дних добро́тах душі́ твоєя́, богоно́се Луко́, і ви́дівше тя на степе́ні святи́тельства, я́ко досто́йний сосу́д Боже́ственния благода́ті, вся немощна́я врачу́ющия і оскудіва́ющая восполня́ющия, дивля́хуся чу́дному промишле́нію Бо́жию о тебі́ і приноша́ху ті благохвале́нія сицева́я:","Ра́дуйся, архієре́ю, от Самаго́ Го́спода пронарече́нний;","ра́дуйся, о надписа́нії са́на єпи́скопскаго на кни́зі твоє́й предука́заніє ми́сленноє приє́мий.","Ра́дуйся, ієра́рхов ізря́дноє украше́ніє;","ра́дуйся, па́стирю, ду́шу за о́вці Христо́ви положи́ти гото́вий.","Ра́дуйся, многосві́тлий Це́ркве світи́льниче;","ра́дуйся, апо́столов соприча́стниче.","Ра́дуйся, іспові́дников удобре́ніє;","ра́дуйся, вся́коє о себі́ отве́ргнувий попече́ніє.","Ра́дуйся, скорбе́й утоли́телю;","ра́дуйся, о людськи́х неві́жествіїх печа́льниче.","Ра́дуйся, іска́вших спасе́нія пра́вим уче́нієм оглаша́вий;","ра́дуйся, житіє́м твої́м сего́ уче́нія не посрами́вий.","Ра́дуйся, святи́телю і іспові́дниче Луко́, врачу́ благи́й і ми́лостивий."]},{"h":"Кондак 5","ps":["Богото́чною Кро́вію Христо́вою от ві́чния сме́рти іскупле́нния жела́я соблюсти́, во дні стра́шних гоне́ній сан єпи́скопський от рук архієре́єв правосла́вних прия́л єси́, святи́телю Луко́, і ді́ло благові́стника до́брі сотвори́л єси́, облича́я, запреща́я, умоля́я со вся́ким долготерпі́нієм і уче́нієм і поя́ Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше А́нгельстії чи́нове вели́кия по́двиги твоя́, удиви́шася, єгда́ по за́повіді Госпо́дней: блаже́нні ізгна́ні пра́вди ра́ди, я́ко тіх єсть Ца́рствіє Небе́сноє, в крі́пості серде́чній безро́потно поне́сл єси́ заточе́ніє і ізгна́ніє за і́м'я Го́спода і Святу́ю Це́рков Христо́ву, терпі́нієм ве́ліїм устроя́я спасе́ніє своє́, приме́ром же свої́м ві́рних ду́ші назида́я. Ми же тя, усе́рдно любо́вію почита́юще, че́ствуєм похвала́ми си́ми:","Ра́дуйся, світи́льниче, на сві́щниці церко́внім поста́вленний;","ра́дуйся, подви́жниче, о́браз любве́ долготерп'я́щия яви́вий.","Ра́дуйся, защища́ти тя ві́рним воспрети́вий;","ра́дуйся, в ру́ки мучи́телей за ві́ру смире́нно но́щію преда́вийся.","Ра́дуйся, посо́бниками непра́ведних суде́й уничиже́нний;","ра́дуйся, в заточе́ніє со смире́нієм безро́потно ше́дий.","Ра́дуйся, пра́вди ра́ди с па́ствою твоє́ю ташке́нтською разлуче́ніє претерпі́вий;","ра́дуйся, я́ко ві́рнії о разлуче́нії с тобо́ю рида́ху.","Ра́дуйся, за Го́спода расп'я́таго із'я́звленний і зауше́нний;","ра́дуйся, лжи́вая уста́ безбо́жних загради́вий.","Ра́дуйся, пра́ведними усти́ твої́ми Небе́сния і́стини і во ізгна́нії віща́вий;","ра́дуйся, я́ко му́ченици на Небесі́х о терпі́нії твоє́м ликовствова́ху.","Ра́дуйся, святи́телю і іспові́дниче Луко́, врачу́ благи́й і ми́лостивий."]},{"h":"Кондак 6","ps":["Пропові́дник немо́лчний та́йни Пресвяти́я, Єдиносу́щния і Неразді́льния Тро́йці бил єси́ і в темни́ці, і во гра́діх ізгна́нія сиби́рськаго, терп'я́ глад, мраз страни́ сі́верния і жесто́кость клевре́тов безбо́жних. Сего́ ра́ди пропові́дуєть Це́рков Кри́мская вели́чія Бо́жия, явле́нная на тебі́, святи́телю Луко́. Ми же єди́нім се́рдцем і єди́німи усти́ воспіва́єм Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́, я́ко звізда́ лучеза́рная, красноя́рськой па́стві і тамбо́вськой, озаря́я ду́ші ві́рних і разгоня́я тьму нече́стія і безбо́жия. І іспо́лнишася на тебі́ слова́ Христо́ви: блаже́нні єсте́, єгда́ поно́сять вам, і іждену́ть, і реку́ть всяк зол глаго́л на ви, лжу́ще, Мене́ ра́ди. Ти бо, гони́мий із гра́да во град і клевети́ терпі́вий, архипа́стирськоє служе́ніє усе́рдні ісполня́л єси́ і сла́достію писа́ній твої́х вся а́лчущия і жа́ждущия пра́вди насища́л єси́, і́же благода́рні взива́ють тебі́:","Ра́дуйся, наста́вниче, всіх к Небесі́ путеводя́й;","ра́дуйся, о сла́ві Бо́жієй і́скренно ревнова́вий.","Ра́дуйся, во́їне Христо́в непобіди́мий;","ра́дуйся, за Христа́ Го́спода темни́ці і біє́нія терпі́вий.","Ра́дуйся, смире́нія Єго́ і́стинний подража́телю;","ра́дуйся, вмісти́лище Ду́ха Свята́го.","Ра́дуйся, вше́дий с му́дрими в ра́дость Го́спода твоєго́;","ра́дуйся, користолю́бія обличи́телю.","Ра́дуйся, па́губу тщесла́вія показа́вий;","ра́дуйся, беззако́нники ко обраще́нію призива́вий.","Ра́дуйся, тобо́ю бо Христо́с просла́вися;","ра́дуйся, тобо́ю бо сатана́ посрами́ся.","Ра́дуйся, святи́телю і іспові́дниче Луко́, врачу́ благи́й і ми́лостивий."]},{"h":"Кондак 7","ps":["Хотя́ досто́йно соверши́ти по́двиг, от Бо́га ті угото́ванний, обле́клся єси́ во вся ору́жія Бо́жия і стал єси́ на брань проти́ву миродержи́телей тьми ві́ка сего́, духо́в зло́би поднебе́сних, препоя́сав чресла́ своя́ і́стиною і оді́явся в броню́ пра́вди, угаси́л єси́, іспові́дниче Луко́, вся стрі́ли лука́ваго, поя́ Соді́телю і Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́воє гоне́ніє воздвиго́ша беззако́ннії і безбо́жнії челові́ци на Це́рков Правосла́вную і во глубину́ да́льнія тає́жния страни́ ізгна́ша тя, святи́телю Луко́, і близ сме́рти бив, руко́ю же Бо́жиєю сохране́н, взива́л єси́ со апо́столом Па́влом: до ни́нішняго часа́ і а́лчем, і жа́ждем, і наготу́єм, і стра́ждем, і скита́ємся. Гони́ми, терпи́м; я́коже отре́біє ми́ру би́хом, всім попра́ніє досе́лі. Сего́ ра́ди, ві́дуще о тебі́ такова́я, убла́жаєм тя:","Ра́дуйся, іспові́дниче Христо́в блаже́нний;","ра́дуйся, мраз лю́тий і глад во ізгна́нії претерпі́вий.","Ра́дуйся, близ сме́рти би́вий, Го́сподем же сохране́нний;","ра́дуйся, самоотверже́ніє всеці́лоє показа́вий.","Ра́дуйся, уневі́стивий ду́шу твою́ Жениху́ Христу́;","ра́дуйся, Го́спода, расп'я́таго на Кресті́, при́сно пред собо́ю предзрі́вий.","Ра́дуйся, во бді́ніїх і моли́твах неосла́бно преби́вий;","ра́дуйся, Єдиносу́щния Тро́йці і́стинний ревни́телю.","Ра́дуйся, вся́кия болі́зні ско́рий і безме́здний врачу́;","ра́дуйся, от неісці́льних гно́йних болі́зней і ран стра́ждущия здра́ви возста́вивий.","Ра́дуйся, я́ко ві́рою твоє́ю разсла́бленнії ісцілі́ша.","Ра́дуйся, я́ко труди́ твої́ми враче́бними ісціле́ннії к ві́рі приведе́ні би́ша.","Ра́дуйся, святи́телю і іспові́дниче Луко́, врачу́ благи́й і ми́лостивий."]},{"h":"Кондак 8","ps":["Стра́нник во юдо́лі земні́й бив, терпі́нія, воздержа́нія і чистоти́ о́браз показа́л єси́, іспові́дниче Луко́. Єгда́ оте́чество в біді́ от наше́ствія іноплеме́нник пребива́ше, любо́в єва́нгельськую явля́я, денноно́щно во враче́бниці труди́лся єси́, ісціля́я неду́ги і ра́ни вожде́й і во́їнов оте́чества земна́го, непам'ятозло́бієм і любо́вію удивля́я всіх творя́щих ті напа́сти, і мно́гія сим обрати́л єси́ ко Христу́, во є́же пі́ти Єму́: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь іспо́лнь любве́ Христо́ви, Луко́ благосе́рде, ду́шу твою́ полага́л єси́ за дру́ги твоя́, і я́ко А́нгел храни́тель бил єси́ бли́жнім і да́льним, злотворя́щия укроща́я, вражду́ющия примиря́я і спасе́ніє всім устроя́я. Помина́юще труди́ твоя́ во бла́го люде́й оте́чества твоєго́, благода́рні взива́єм ті:","Ра́дуйся, ди́вную любо́в ко оте́честву земно́му показа́вий;","ра́дуйся, смире́нія і незло́бія учи́телю.","Ра́дуйся, ізгна́ніє і жесто́кия му́ки му́жественно претерпі́вий;","ра́дуйся, за Христа́ страда́вий і му́чим би́вий.","Ра́дуйся, тве́рдо Єго́ іспові́давий;","ра́дуйся, зло́бу враго́в любо́вію Христо́вою побіди́вий.","Ра́дуйся, о́тче благосе́рдий, спасе́нія мно́гих взиска́вий;","ра́дуйся, вели́кими скорбми́ іскуше́нний.","Ра́дуйся, в гоне́ніїх терпі́ніє ди́вноє яви́вий;","ра́дуйся, я́ко за враги́ Го́сподеві моли́лся єси́.","Ра́дуйся, я́ко любо́в твоя́ вся́ку вражду́ побіди́;","ра́дуйся, я́ко незло́біє твоє́ сердца́ жесто́кая покори́.","Ра́дуйся, святи́телю і іспові́дниче Луко́, врачу́ благи́й і ми́лостивий."]},{"h":"Кондак 9","ps":["Всім бил єси́ вся, я́коже і святи́й Па́вел, даби́ спасти́ хотя́ би ні́которих, святи́телю Луко́, архипа́стирський по́двиг соверша́я, в Тамбо́вськом кра́ї мно́гими труди́ хра́ми обновля́я і созида́я, уста́ви святооте́чеськия стро́го соблюда́я, спасе́нію па́стви твоєя́ служи́ти не престава́л єси́, чи́сто Бо́гові поя́: Аллилу́я."]},{"h":"Ікос 9","ps":["Ві́тіії челові́честії не возмо́гуть по достоя́нію ізрещи́ твої́х благодія́ній мно́жество, єгда́ яви́ся на Кри́мськой землі́, я́ко оте́ць чадолюби́вий, святи́телю о́тче Луко́: щедрода́тельная бо десни́ця твоя́ всю́ду досяза́ше. Ми же, благосе́рдію твоєму́ подража́ти хотя́ще, во удивле́нії взива́єм к тебі́:","Ра́дуйся, луче́ любве́ Бо́жия;","ра́дуйся, сокро́вище милосе́рдія Спа́сова неістощи́моє.","Ра́дуйся, я́ко вся своя́ неіму́щим раздава́л єси́;","ра́дуйся, бли́жнія твоя́ па́че себі́ возлюби́вий.","Ра́дуйся, стра́ждущих сиро́т пита́телю і окорми́телю;","ра́дуйся, безпомо́щних ста́рцев і ста́риць попечи́телю.","Ра́дуйся, я́ко боля́щия і в темни́ці заключе́нния посіща́л єси́;","ра́дуйся, я́ко ну́жди бі́дних во мно́зіх мі́стіх оте́чества своєго́ предваря́л єси́.","Ра́дуйся, я́ко ни́щія ми́луя, трапе́зи їм устроя́л єси́;","ра́дуйся, я́ко о глубині́ милосе́рдія твоєго́ Ма́ти Бо́жия возра́довася.","Ра́дуйся, а́нгеле земни́й і челові́че Небе́сний;","ра́дуйся, я́ко коєму́ждо в го́рестіх, а́ки А́нгел уті́шитель, явля́лся єси́.","Ра́дуйся, святи́телю і іспові́дниче Луко́, врачу́ благи́й і ми́лостивий."]},{"h":"Кондак 10","ps":["Спасе́нію кри́мськия па́стви твоєя́ служи́ти многолі́тні не престава́я, по о́бразу Пастиренача́льника Христа́, на ра́мена заблу́ждшия взем, Небе́сному Отцю́ приве́л єси́, наде́ждею бо на Бо́жиє милосе́рдіє утіша́я, ко ісправле́нію житія́ словеси́ учи́тельними твої́ми влекл єси́ вся, во є́же се́рдцем чи́стим пі́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Царя́ Небе́снаго Христа́ Бо́га ві́рний служи́тель бив, святи́телю о́тче Луко́, неуста́нно возвіща́л єси́ сло́во І́стини во всіх хра́міх землі́ Таври́чеськия, душеспаси́тельною пи́щею уче́нія єва́нгельськаго ві́рная ча́да пита́я і уста́в церко́вний стро́го ісполня́ти повеліва́я. Ті́мже тя, я́ко па́стиря до́браго, прославля́єм си́це:","Ра́дуйся, неутоми́мий пропові́дниче єва́нгельськия пра́вди;","ра́дуйся, я́ко Бо́гом вруче́нноє тебі́ ста́до слове́сноє до́брі упа́сл єси́.","Ра́дуйся, о́вці своя́ от душепа́губних волко́в охраня́вий;","ра́дуйся, чи́на церко́внаго стро́гий блюсти́телю.","Ра́дуйся, чистоти́ ві́ри правосла́вния охрани́телю;","ра́дуйся, тобо́ю бо Дух Святи́й написа́ словеса́ спаси́тельная.","Ра́дуйся, мудреце́м ві́ка сего́ битіє́ Бо́жиє пропові́давий;","ра́дуйся, я́ко сло́во твоє́, а́ки в ри́зи позлаще́ни, в та́йни ві́ри оді́яся.","Ра́дуйся, мо́лніє, горди́ню низлага́ющая;","ра́дуйся, гро́ме, беззако́нно живу́щия устраша́яй.","Ра́дуйся, церко́внаго благоче́стія насади́телю;","ра́дуйся, архіпа́стирю, па́стирі духо́вния наставля́яй і вразумля́яй непреста́нно.","Ра́дуйся, святи́телю і іспові́дниче Луко́, врачу́ благи́й і ми́лостивий."]},{"h":"Кондак 11","ps":["Пі́ніє у гро́ба твоєго́, уго́дниче Бо́жий, не умолка́ше во днех блаже́ннаго успе́нія твоєго́. Мно́зі бо, ві́дуще тя богоно́сна і равноа́нгельна, собра́шася от всіх преді́л земна́го оте́чества твоєго́ соверши́ти моле́ніє собо́рноє о душі́ твоє́й, в го́рнія оби́телі Оте́чества Небе́снаго восходя́щей, воспіва́юще Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Свіще́ю, в Це́ркві Христо́вій горя́щею сві́том невеще́ственним благода́ті Бо́жия, бил єси́, святи́телю Луко́, вся конці́ землі́ на́шея озаря́я. Помина́юще блаже́нноє успе́ніє і ве́ліє твоє́ на Небесі́ і на землі́ прославле́ніє, с ра́достію прино́сим ті благохвале́нія сія́:","Ра́дуйся, світи́льниче неме́ркнущий Сві́та Невече́рняго;","ра́дуйся, я́ко мно́зі просла́виша твої́х ра́ди до́брих діл Отця́ Небе́снаго.","Ра́дуйся, уго́дниче Бо́жий, тече́ніє благоче́стне сконча́вий;","ра́дуйся, ві́ру, наде́жду і любо́в от Го́спода стяжа́вий.","Ра́дуйся, со Христо́м, Єго́же возлюби́л єси́, на ві́ки соєдини́вийся;","ра́дуйся, Ца́рствія Небе́снаго і сла́ви ві́чния наслі́дниче.","Ра́дуйся, я́ко світ до́брих діл твої́х пред челові́ки просвіти́ся;","ра́дуйся, мно́гих научи́вий за́повідем Христо́вим і сотвори́вий я.","Ра́дуйся, архієре́ю, от Ві́чнаго Архієре́я Христа́ благода́тними да́ри іспо́лненний;","ра́дуйся, ско́рий помо́щниче призива́ющим тя.","Ра́дуйся, землі́ Кри́мськия но́воє світи́ло і утвержде́ніє;","ра́дуйся, ро́да христия́нськаго благода́тний покрови́телю.","Ра́дуйся, святи́телю і іспові́дниче Луко́, врачу́ благи́й і ми́лостивий."]},{"h":"Кондак 12","ps":["Благода́ть, сви́ше ті да́нную, позна́вше, благогові́йно лобиза́єм честни́й о́браз твой, святи́телю Луко́, ча́юще тобо́ю прия́ти проси́моє от Бо́га. Ті́мже припа́дающе ко святі́й іко́ні твоє́й (а́ще же пред мощми́ глаго́леши: ко святи́м моще́м твої́м), со умиле́нієм мо́лим тя: укріпи́ нас до́брі стоя́ти во ві́рі правосла́вній, і угожда́юще благи́ми ді́ли, немо́лчно пі́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще Бо́га, ди́внаго во святи́х Свої́х, хва́лим тя, Христо́ва іспові́дника, святи́теля і предста́теля пред Го́сподем. Весь бо єси́ во ви́шніх, но і ни́жніх не оставля́єши, святи́телю о́тче Луко́, при́сно со Христо́м ца́рствуєши і о нас грі́шних пред Престо́лом Бо́жиїм хода́тайствуєши. Сего́ ра́ди во умиле́нії зове́м ті:","Ра́дуйся, Сві́та непристу́пнаго зри́телю;","ра́дуйся, тебі́ бо сора́дуються А́нгели і о тебі́ веселя́ться челові́ци.","Ра́дуйся, ді́ли і писа́ньми твої́ми неві́рующія просвіща́яй;","ра́дуйся, малові́рния і малоду́шния укріпля́яй і утвержда́яй.","Ра́дуйся, я́ко досто́їн яви́лся єси́ Ца́рствія Небе́снаго;","ра́дуйся, путе́м іспові́дничества ра́йських селе́ній дости́гнувий.","Ра́дуйся, поноше́нія Христа́ ра́ди терпі́вий і ві́чную с Ним сла́ву приє́мий;","ра́дуйся, ду́ші на́ша к Ца́рствію Небе́сному путеводя́й.","Ра́дуйся, предста́телю пред Престо́лом Бо́жиїм за нас грі́шних;","ра́дуйся, Правосла́вія похвало́ і землі́ на́шея ра́дованіє.","Ра́дуйся, в со́нмі святи́х би́ти сподо́бивийся;","ра́дуйся, собо́ру всіх Кри́мських святи́х соприча́стниче.","Ра́дуйся, святи́телю і іспові́дниче Луко́, врачу́ благи́й і ми́лостивий."]},{"h":"Кондак 13","ps":["О вели́кий і пресла́вний уго́дниче Бо́жий, святи́телю о́тче наш Луко́, прийми́ сіє́ похва́льноє пі́ніє от нас недосто́йних, с любо́вію сино́внею тебі́ приноси́моє! Предста́тельством твої́м у Престо́ла Бо́жия і моли́твами твої́ми всіх нас во ві́рі правосла́вній і до́брих ді́ліх утверди́, от вся́ких бід, скорбе́й, болі́зней і напа́стей, в сей жи́зні находя́щих, сохрани́, і от муче́ній в бу́дущем ві́ці ізба́ви і сподо́би во ві́чній жи́зні ку́пно с тобо́ю і со всі́ми святи́ми пі́ти Творцю́ на́шему: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов собесі́дниче і челові́ков наста́вниче, Луко́ пресла́вний, подо́бні євангели́сту і апо́столу Луці́, єму́же тезоімени́ть сий, от Бо́га дар ціли́ти неду́ги челові́чеськія прия́л єси́, мно́гія труди́ под'є́мля во врачева́нії болі́зней бли́жніх, плоть нося́, о пло́ті не раді́л єси́, ді́ли же до́брими Отця́ Небе́снаго просла́вил єси́. Ті́мже благода́рні во умиле́нії зове́м ті:","Ра́дуйся, от ю́ности ра́зум свой і́гу Христо́ву покори́вий;","ра́дуйся, пречестно́є Святи́я Тро́йці селе́ніє би́вий.","Ра́дуйся, блаже́нство ми́лостивих, по сло́ву Го́спода, унаслі́довавий;","ра́дуйся, ві́рою Христо́вою і зна́нієм богодарова́нним мно́гія неду́жния ісціли́вий.","Ра́дуйся, стра́ждущих неду́ги тіле́сними врачу́ милосе́рдний;","ра́дуйся, во дні бра́ні вожде́й і во́їнов ціли́телю іску́сний.","Ра́дуйся, всіх враче́в наста́вниче;","ра́дуйся, ско́рий в ну́ждах і ско́рбіх су́щим помо́щниче.","Ра́дуйся, Це́ркве Правосла́вния утвержде́ніє;","ра́дуйся, землі́ на́шея озаре́ніє.","Ра́дуйся, кри́мськия па́стви похвале́ніє;","ра́дуйся, гра́да Симферо́поля украше́ніє.","Ра́дуйся, святи́телю і іспові́дниче Луко́, врачу́ благи́й і ми́лостивий."]},{"h":"Кондак 1","ps":["Ізбра́нний святи́телю Це́ркве Правосла́вния і іспові́дниче, возсія́вий страні́ на́шей, я́ко світоза́рноє світи́ло, до́брі потруди́вийся і за і́м'я Христо́во гоне́ніє претерпі́вий, прославля́юще просла́вльшаго тя Го́спода, дарова́вшаго нам тебе́ но́ваго моли́твенника і помо́щника, похва́льноє воспіва́єм ті пі́ніє; ти же, я́ко імі́яй ве́ліє дерзнове́ніє ко Влади́ці Небесе́ і землі́, от вся́ких неду́гов душе́вних і тіле́сних свободи́ нас і до́брі стоя́ти во Правосла́вії укріпи́, да всі во умиле́нії зове́м ті:","Ра́дуйся, святи́телю і іспові́дниче Луко́, врачу́ благи́й і ми́лостивий."]},{"h":"Молитва","ps":["О всеблаже́нний іспові́дниче, святи́телю о́тче наш Луко́, вели́кий уго́дниче Христо́в! Со умиле́нієм прекло́ньше колі́на серде́ць на́ших, моля́щеся пред святи́м о́бразом твої́м (а́ще же пред мощми́ глаго́леши: і припа́дающе к честни́м і многоціле́бним моще́м твої́м), я́коже ча́да отця́, мо́лим тя всеусе́рдно: усли́ши нас грі́шних і принеси́ моли́тву на́шу к ми́лостивому Человіколю́бцю Бо́гу, Єму́же ти ни́ні в ра́дості святи́х і с ли́ки А́нгел предстої́ши. Ві́руєм бо, я́ко лю́биши ни то́ю же любо́вію, є́юже вся бли́жнія возлюби́л єси́, на землі́ пребива́я. Іспроси́ у Христа́ Бо́га на́шего, да утверди́ть во Святі́й Своє́й Правосла́вній Це́ркві дух пра́вия ві́ри і благоче́стія, па́стирем єя́ да дасть ре́вность святу́ю і попече́ніє о спасе́нії па́стви, вві́ренния їм: пра́во ве́рующия соблюда́ти, сла́бия і немощни́я во ві́рі укріпля́ти, неве́дущия наставля́ти, проти́вния облича́ти. Всім нам пода́й дар, коєму́ждо благопотре́бен, і вся, я́же к жи́зні вре́менній і к ві́чному спасе́нію поле́зная: градо́в на́ших утвержде́ніє, землі́ плодоно́сіє, от гла́да і па́губи ізбавле́ніє, скорб'я́щим утіше́ніє, неду́гующим ісціле́ніє, заблу́ждшим на путь і́стини возвраще́ніє, роди́телем благослове́ніє, ча́дом в стра́сі Госпо́днем воспита́ніє і науче́ніє, си́рим і убо́гим по́мощ і заступле́ніє. Пода́ждь всім нам твоє́ архипа́стирськоє свято́є благослове́ніє, да тім осіня́ємі, ізба́вимся от ко́зней лука́ваго і ізбі́гнем вся́кия вражди́ і нестроє́ній, єресе́й і раско́лов. Да́руй нам по́прище жи́зні вре́менния богоуго́дно прейти́, наста́ви нас на путь, веду́щий в селе́нія пра́ведних, ізба́ви возду́шних мита́рств і моли́ о нас Всеси́льнаго Бо́га, да во ві́чній жи́зні с тобо́ю непреста́нно сла́вим Отця́, і Си́на, і Свята́го Ду́ха, в Тро́йці сла́вимаго Бо́га, Єму́же подоба́єть вся́кая сла́ва, честь і держа́ва во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 1","ps":["Возвісти́телю путі́ спаси́тельнаго, / іспові́дниче непоколеби́мий, / і́стинний храни́телю оте́чеських преда́ній, / Правосла́вія наста́вниче, / Кри́мськия землі́ архіпа́стирю, / врачу́ богому́дрий, святи́телю Луко́, / Христа́ Спа́са непреста́нно моли́, // дарова́ти душа́м на́шим ве́лію ми́лость."]},{"h":"Кондак, глас 1","ps":["Я́коже звізда́ всесві́тлая, / в нощі́ безбо́жия доброді́тельми просія́л єси́, / і от гони́телей мно́го пострада́в, / непоколеби́м ві́рою преби́л єси́, / враче́бною же му́дростію укра́шен, / мно́гия лю́ди ісціли́л єси́. / Сего́ ра́ди с любо́вію вопіє́м ті: / ра́дуйся, добропобі́дний іспові́дниче, / ра́дуйся, о́тче святи́телю Луко́, // ра́дуйся, землі́ Ру́ськия похвало́ і утвержде́ніє."]},{"h":"Величання","ps":["Велича́єм тя, іспові́дниче Христо́в святи́телю о́тче наш Луко́, і чтим святу́ю па́м'ять твою́, ти бо мо́лиши за нас Христа́ Бо́га на́шего."]}],"notes":[]}];
export default D;
